window.__D("text/likkutei-sichot/c004",{"p":[[1301470069,"<h3>שיחה א</h3>\nא. \"ויאמר לרשע למה תכה רעך\"<sup data-n=\"1\">1</sup>, ופרש\"י \"למה תכה — אע\"פ שלא הכהו נקרא רשע בהרמת יד\". ומקורו במס' סנהדרין<sup data-n=\"2\">2</sup>: אמר ריש לקיש המגבי' ידו על חבירו אע\"פ שלא הכהו נקרא רשע שנאמר ויאמר לרשע למה תכה רעך למה הכית לא נאמר אלא למה תכה אע\"פ שלא הכהו נקרא רשע.\nדין זה הובא להלכה ברמב\"ם, וז\"ל<sup data-n=\"3\">3</sup>: אסור לאדם לחבול בין בעצמו בין ב­חבירו. . כל המכה אדם כשר מישראל. . הרי זה עובר בלא תעשה. . אפילו להגבי' ידו על חבירו אסור וכל<sup data-n=\"4\">4</sup> המגבי' ידו על חבירו אע\"פ שלא הכהו הרי זה רשע.\nוהנה הרמב\"ם שינה מלשון הש\"ס ב­שתים: (א) מוסיף \"אפילו להגבי' ידו על חבירו אסור\". (ב) במקום \"נקרא רשע\" כ' \"הרי זה<sup data-n=\"5\">5</sup> רשע\".\nויש לפרש כוונת הרמב\"ם בזה: מאמר ר\"ל בש\"ס אפשר לפרש שלא נאמר להלכה למעשה, אלא כדברי אגדה<sup data-n=\"6\">6</sup> ב­גודל עון הכאת חבירו כו' [וכדמשמע לכאורה מהמאמרים שהובאו בגמ' שם בהמשך לזה — \"נקרא חוטא. . תיקצץ ידו<sup data-n=\"7\">7</sup>. . אין לו תקנה אלא קבורה\"] — ומדגיש הרמב\"ם שאינו כן, אלא (א) ש­הגבהת יד על חבירו יש בזה איסור גמור, ו(ב) שהמגבי' ידו \"הרי זה רשע\", כלומר, שאין זה ענין של קריאת שם בלבד, אלא שחל עליו דין רשע, וכמ\"ש בהגהות מיימוניות כאן<sup data-n=\"8\">8</sup> (בשם הראב\"ן<sup data-n=\"9\">9</sup>) שהוא פסול לעדות ולשבועה.\nועפ\"ז יש לבאר טעמו של הטור ש­שינה בדין זה מלשון הרמב\"ם, וז\"ל<sup data-n=\"10\">10</sup>: \"אסור לאדם שיכה לחבירו ואם הכהו עובר בלאו. . והמרים ידו על חבירו ל­הכותו אע\"פ שלא הכהו נקרא רשע\" — היינו (א) שהשמיט הדגשת הרמב\"ם שיש בזה איסור, (ב) נקט לשון הש\"ס \"נקרא רשע\" (ולא כלשון הרמב\"ם \"הרי זה רשע\"), כי הטור סבירא לי' שאין בזה פס\"ד הלכה למעשה<sup data-n=\"11\">11</sup>, ומביא זה בסגנון אגדה, להודיע גודל העון (כמו שמביא דברי אגדה בכמה מקומות בנוגע למדות והנהגות וגם למצות שונות)<sup data-n=\"12\">12</sup>.",[["1","1","פרשתנו ב, יג."],["2","2","נח, ב."],["3","3","הל' חובל ומזיק פ\"ה ה\"א­ב (וש\"נ)."],["4","4","כל — כ\"ה גם בש\"ס לכמה גי' (ע\"י ועוד — ראה דק\"ס סנהדרין שם. וש\"נ)."],["5","5","ראה ילקוט שינויי נוסחאות ברמב\"ם מ­הדורת פרענקל, שבכמה כת\"י הגירסא \"נקרא רשע\"."],["6","6","וראה שו\"ת מהרי\"ט אה\"ע סי' מג (סד\"ה ולפי עדות) \"ואפשר דדברי הגדה הם ולאו עיקר דרשה\" (ומסיים \"ויש לחוש בזה להחמיר\")."],["7","7","ראה רש\"י שם. ערוך לנר שם (אבל בתוס' שם פליג. וראה עיון יעקב לע\"י סנהדרין שם)."],["8","8","אות א'. ובדפוס קושטנטינא (נדפס ברמב\"ם מהדורת פרענקל) \"וכן פסק כו'\"."],["9","9","לסנהדרין שם, הובא במרדכי (ב\"ק סק\"ב. סנהדרין סתרצ\"ה) — הביאו הב\"י לטור חו\"מ הל' עדות סל\"ד ס\"ד (כדלקמן בפנים), וכן בב\"ח שם סי\"ב. וכן נפסק להלכה ברמ\"א חו\"מ שם ס\"ד."],["10","10","חו\"מ ר\"ס תכ."],["11","11","אבל ראה יש\"ש ב\"ק פ\"ח סס\"ג (מתשובת ר' חיים, הובא בשו\"ת מהר\"י ווייל סכ\"ח): כל רבותינו שוין בזה שהמגבי' ידו על חבירו נק' רשע ופסול לעדות ולשבועה. . ואע\"פ שלא הכהו."],["12","12","ומודגש גם בחילוק המשך לשון הרמב\"ם והטור: ברמב\"ם בא ענין זה בסגנון של המשך — \"אסור לאדם לחבול כו' ולא החובל בלבד אלא כל המכה כו' אפילו להגבי' כו' אסור\" — כי זהו דין ואיסור כהלכה הקודמת; משא\"כ בטור בא כמאמר בפ\"ע — \"אסור לאדם שיכה כו' והמרים ידו על חבירו כו'\"."]]],[1301470070,"[ולכאורה כ\"ה דעת המחבר בשו\"ע, שהעתיק<sup data-n=\"13\">13</sup> (בהל' חובל<sup data-n=\"10\">10</sup>) ל' הטור הנ\"ל (ע\"ד חומר הרמת יד על חבירו), ואעפ\"כ השמיט בשו\"ע הל' עדות<sup data-n=\"15\">14</sup> את דברי ה­מרדכי<sup data-n=\"16\">15</sup> שהמגבי' ידו על חבירו פסול לעדות ולשבועה (אף שבב\"י בהל' עדות<sup data-n=\"15\">14</sup> העתיק דעת המרדכי, וכדלקמן סעיף ב), דמזה משמע לכאורה, שלהלכה למעשה לא נקט כהמרדכי<sup data-n=\"18\">16</sup>].\nב. והנה מפשטות לשון הרמב\"ם \"אפילו להגבי' ידו על חבירו אסור\" — דלא כמ\"ש בהלכה שלפנ\"ז בנוגע למכה אדם \"הרי זה עובר בל\"ת\" — משמע, ש­אינו איסור דאורייתא אלא רק איסור ד­רבנן<sup data-n=\"19\">17</sup> (ואסמכוה אקרא<sup data-n=\"20\">18</sup> ד\"ויאמר ל­רשע למה תכה רעך\"). וכן מפורש בחי­נוך<sup data-n=\"21\">19</sup>, \"וחכמים ז\"ל מנעו אותנו אפילו מלרמוז להכות ואמרו כל המגבי' ידו על חבירו להכותו נקרא רשע שנאמר ויאמר לרשע למה תכה רעך\", הרי ל­הדיא שהוא רק איסור דרבנן<sup data-n=\"22\">20</sup>.\nאמנם בב\"י על הטור שם<sup data-n=\"15\">14</sup> כ' בביאור דעת המרדכי<sup data-n=\"16\">15</sup> שהמגבי' ידו על חבירו פסול לעדות, וז\"ל \"ואם המגבי' יד על חבירו אינו לוקה צ\"ל דהעובר על ל\"ת שאין בו מלקות פסול מדרבנן, ואע\"פ שמדברי הרמב\"ם ורבינו נראה שאינו פסול מדרבנן אלא העובר על דברי רבנן, משמע דכ\"ש הוא לעובר על ד\"ת שאין בהם מלקות\".\nהרי שהב\"י מפרש דעת המרדכי ש­",[["13","13","ועד\"ז בשו\"ע אדה\"ז ריש הל' נזקי גוף ונפש."],["10","10","חו\"מ ר\"ס תכ."],["15","14","סל\"ד שם."],["16","15","נסמן בהערה 9."],["15","14","סל\"ד שם."],["18","16","ותלוי לכאורה בשקו\"ט אם זה שהשמיט המחבר דינים שהביאם בב\"י הוא משום שלא ס\"ל כן להלכה או מפני טעמים אחרים (ראה יד מלאכי כללי השו\"ע אות ד. שד\"ח כללי הפוסקים סימן יג אות ה. וש\"נ). ולהעיר שבנדו\"ד משמע בשו\"ת הב\"י (דיני קידושין ס\"ב) שס\"ל כהמרדכי להלכה (שפסול עכ\"פ מדרבנן)."],["19","17","לדעת הכס\"מ (ריש הל' גזילה ואבידה) דכשהרמב\"ם כותב סתם \"אסור\" אינו אלא דרבנן. וגם לדיעות החולקים (ראה יד מלאכי כללי הרמב\"ם אות יו\"ד. שד\"ח כללי הפוסקים סי' ה אות ט) — הרי בנדו\"ד ששינה הרמב\"ם מלשונו שלפנ\"ז, משמע כבפנים. וראה שד\"ח שם."],["20","18","ראה שו\"ת ב\"י שבהערה 16. — בסמ\"ע חו\"מ סל\"ד סק\"ד \"אסמכוה אקרא\". אבל ממשיך שם \"שהוא איסור דאורייתא\". וראה לקמן בפנים סוס\"ג והערה 28."],["21","19","מצוה תקצה. ועד\"ז הוא בסהמ\"צ (מל\"ת ש) בתרגום העליר וקאפח: וכבר הזהירו (עליהם השלום) מלרמוז להכות [ולא \"הזהירנו\" כבסהמ\"צ לפנינו].\nאבל להעיר מיד מלאכי כללי הרמב\"ם אות כב ש\"לפעמים כותב הרמב\"ם ז\"ל בספר המצות שלו על איזה דין שהוא מדרבנן ואין הכוונה מדרבנן לגמרי. . אלא שהוא מקובל אצלם אותו איסור ל­אסרו דבר תורה\". ע\"ש. וראה גם שד\"ח כללי ה­פוסקים שם אות ז. ואכ\"מ."],["22","20","אלא שצע\"ק עפ\"ז אם משום זה יחול עליו דין רשע לפוסלו לעדות — שהרי רק המחויב מלקות (מה\"ת או מדרבנן) נק' רשע (ראה רמב\"ם הל' עדות פ\"י ה\"ג) [משא\"כ אם הוא איסור דאורייתא אף שאין בו דין מלקות נפסל — כדלקמן בפנים מהב\"י].\nוי\"ל דשאני בנדו\"ד, שיש עליו דין רשע (לא רק מפני שעבר על איסור דרבנן, אלא) משום שהכתוב קראו רשע (\"ויאמר לרשע למה תכה רעך\") — ראה לבוש חו\"מ סל\"ד סוס\"ד: וקראו משה רשע לפיכך פסלוהו רבנן ג\"כ לעדות. ועייג\"כ שו\"ת ב\"י הנ\"ל (הערה 16). שו\"ת חוט השני סח\"י (צויין בברכ\"י חו\"מ שם אות טו)."],["15","14","סל\"ד שם."],["16","15","נסמן בהערה 9."]]],[1301470071,"הוא ל\"ת דאורייתא<sup data-n=\"25\">21</sup> (וכן משמע מפש­טות לשונו, שמספקא לי' אם לוקה או לאו<sup data-n=\"26\">22</sup> — כמ\"ש \"ואם המגבי' כו' אינו לוקה צ\"ל כו'\").\nונמצא ששלש שיטות יש בפירוש מאמר ר\"ל: א) שלא נאמר בתור הלכה ופס\"ד כ\"א ע\"ד האגדה. ב) שזהו איסור גמור דרבנן. ג) שעובר בל\"ת דאורייתא (ועד שקס\"ד לומר שחייב מלקות).\nג. ונראה לבאר יסוד פלוגתא הנ\"ל — שתלוי בהגדרת האיסור ד\"מגבי' ידו על חבירו\" — שיש לפרשו בשני אופנים:\nא) הגבהת ידו על חבירו ה\"ז התחלת הפעולה של הכאת חבירו. וזהו החידוש בהדין דהמגבי' ידו על חבירו נקרא רשע, דבהתחלת (כזו ד)פעולת ההכאה — כבר \"נקרא רשע\".\nב) אין האיסור מצד צער והיזק חבי­רו המוכה על ידו, אלא מצד המגבי', ש­עצם הגבהת היד על חבירו היא פעולה אסורה.\nכלומר: האיסור דהכאת חבירו או גם המגבי' יד עליו (כמו כל האיסורים שבין אדם לחבירו) יש בו ב' חלקים: א) מצד הנפעל — היזק וצער לחבירו. ב) מצד הגברא (הפועל) — הנהגה (מדה) רעה של המגבי' והמכה.\nוזהו החילוק בגדר ה\"רשעות\" ד­\"מגבי' ידו על חבירו\": לאופן הא' הרי זה רק משום שפעולה זו (הגבהת היד) היא הכנה והתחלה של פעולת הכאת חבירו; משא\"כ לאופן הב', שגדר ה­\"רשעות\" הוא הנהגה (מדה) מגונה וכיו\"ב של המגבי', הרי הגבהת היד עצמה היא מעשה רע, ולכן מצד הנהגה זו עצמה נקרא רשע<sup data-n=\"27\">23</sup>.\nויש לומר שזהו טעם הפלוגתא, אם הא דהמגבי' ידו על חבירו נק' רשע הוא רק ענין חמור מדברי אגדה או שהוא הלכה ואיסור וחל עליו דין רשע (ופסול לעדות ולשבועה) — ובהקדם:\nכלל הוא<sup data-n=\"28\">24</sup> בדיני התורה (מלבד ע\"ז כו') שאין מענישים על מחשבה. ועפ\"ז אינו מובן בנדו\"ד, אם האיסור הוא \"הכאת חבירו\" — למה \"המגבי' ידו על חבירו אע\"פ שלא הכהו נקרא רשע\"?\nואע\"פ שכאן היתה לא רק מחשבה, אלא גם מעשה של הגבהת היד — מ\"מ, הרי אין בזה מעשה דהכאת חבירו.\nויש לומר, שזהו טעם השיטה דהא ש\"נקרא רשע\" אינו דין רשע להלכה (לפסלו לעדות ולשבועה) — כי אין אדם נפסל לעדות ולשבועה על ידי הגבהת יד.\nאבל לדעת הרמב\"ם \"הרי זה רשע\" — כי ס\"ל כאופן הב' הנ\"ל, שעצם הגבהת היד ה\"ז דבר האסור<sup data-n=\"29\">25</sup>, וא\"כ עשה מעשה אסור.\nאלא שעפ\"ז צ\"ע סברת הב\"י שהמגבי'",[["25","21","ולהעיר, שבשו\"ת הב\"י שם משמע שמ­ספקא לי' אם נפסל מדרבנן או שהוא פסול מה\"ת. וכן בשו\"ת מבי\"ט ח\"א סו\"ס רצא. ובשו\"ת מהרי\"ט (שבהערה 6) משמע שלדעת המרדכי פסול מה\"ת. וראה שו\"ת חוט השני שם."],["26","22","אלא שבדרכי משה הארוך, סמ\"ע חו\"מ שם סק\"ז (ועוד) נקטו שכוונת הב\"י היא שאינו לוקה. וכ\"ה בשו\"ת מהרי\"ט שם."],["27","23","להעיר מנתיבות עולם להמהר\"ל נתיב אהבת ריע רפ\"ג. חדא\"ג מהר\"ל סנה' שם."],["28","24","ראה קידושין לט, ב. וש\"נ."],["29","25","וי\"ל שעד\"ז היא שיטת רש\"י בפירושו עה\"ת שכ' \"אע\"פ שלא הכהו נק' רשע בהרמת יד\" (ולא כ' \"בהרמת יד על חבירו\" וכיו\"ב), ומשמע שזהו מצד עצם הרמת היד."]]],[1301470072,"ידו על חבירו הוי לאו מדאורייתא (ועד שקס\"ד שחייב מלקות), שלדעתו ה\"ז משום הלאו דחובל בחבירו<sup data-n=\"30\">26</sup> — כיצד אפשר לומר שעבר על לאו זה כשחבירו לא נחבל על ידו?\nוי\"ל (בדוחק עכ\"פ) שס\"ל שזהו חידוש התורה בלאו דהכאת חבירו (שלא מצינו דוגמתו בשאר איסורים): אע\"פ שאזהרת הלאו עצמו, היא הכאת חבירו (בפועל) — \"לא יוסיף גו' להכותו\"<sup data-n=\"31\">27</sup> — בא הכתוב \"ויאמר לרשע למה תכה רעך\" (\"למה הכית לא נאמר אלא למה תכה\") לגלות על הלאו דהכאת חבירו<sup data-n=\"32\">28</sup>, שגם בתחילת פעולת ההכאה, דהיינו הגבהת היד על חבירו<sup data-n=\"33\">29</sup> (ואף שלא המשיך בפעולה זו וחבירו לא הוכה) כבר עבר<sup data-n=\"34\">30</sup> על לאו זה<sup data-n=\"35\">31</sup>.\nד. ויש למצוא מקור לג' שיטות הנ\"ל בשינויי לשונות חז\"ל בג' מקומות שהו­בא ענין זה דהמגבי' ידו על חבירו:\nא) בגמ' הלשון (כנ\"ל סעיף א): \"ה­מגבי' ידו על חבירו אע\"פ שלא הכהו נקרא רשע\".\nב) בשמות רבה פרשתנו<sup data-n=\"36\">32</sup> נאמר: \"ויאמר לרשע. . הכית לא נאמר אלא תכה מכאן שמשעה שאדם מרים ידו להכות חבירו אע\"פ שלא הכהו נקרא רשע\".\nג) בתנחומא<sup data-n=\"37\">33</sup> ובמדבר רבה<sup data-n=\"38\">34</sup> איתא: \"ארבעה נקראו רשעים, (אלו הן) הפושט ידו לחבירו להכותו אע\"פ שלא הכהו נקרא רשע. . והלוה ואינו משלם. . ומי שיש בו עזות פנים. . ומי שהוא בעל מחלוקת\".\nכלומר: בגמ' נאמר סתם \"המגבי' ידו על חבירו\", ואילו במדרשים אלו בא בהוספה והדגשה \"מרים ידו להכות חבירו\", \"הפושט ידו לחבירו להכותו\".\nוע\"פ הנ\"ל יש לומר, שלדעת הש\"ס האיסור הוא בעצם מעשה הגבהת היד על חבירו (כנ\"ל בדעת הרמב\"ם), ולכן לא נאמר בש\"ס \"להכותו\"<sup data-n=\"39\">35</sup> [ובזה יומתק",[["30","26","דפשיטא דמ\"ש \"ויאמר לרשע למה תכה רעך\" אינו לשון ציווי, לאו. וראה שו\"ת חוט השני שם."],["31","27","תצא כה, ג."],["32","28","ואולי זוהי כוונת הסמ\"ע (שבהערה 18) \"אסמכוה אקרא\"."],["33","29","להעיר מהשקו\"ט במפרשים בסוגיא דכתו­בות (לא, א) \"הגבהה צורך אכילה. . הגבהה צורך הוצאה\". וצ\"ע אם היינו ממש ככאן, אף שבשניהם אינה אלא הכנה להפעולה ולא הפעולה (\"לא הכהו\").\nויש לחלק, כי בגמ' שם מדובר שלפועל נעשית כל הפעולה (האכילה, או ההוצאה), אלא שאנו דנים מאימתי מתחיל החיוב, אם מעצם פעולת האכילה (הוצאה) עצמה, או כבר מההכנה להפעולה; משא\"כ בנדו\"ד שמעולם לא בא לידי הפעולה עצמה (שהרי \"לא הכהו\"). ועוד. ואכ\"מ."],["34","30","אבל מובן הטעם שאין בזה חיוב מלקות (ראה פוסקים שנסמנו בהערה 22) — כי לענין חובל בחבירו אין כאן מעשה (ראה גם חכמת שלמה ל­שו\"ע חו\"מ סל\"ד שם, בהשמטה שנדפסה בסוף ה­סימן)."],["35","31","ומה שדוקא באיסור זה דהכאת חבירו נפסל תיכף בתחילת הפעולה כשחבירו עדיין לא נפגע, ולא אמרינן כן בגניבה וגזילה וכיו\"ב — י\"ל כי הכאת חבירו היא כולה מעשה של רשעות, מבלי כל ריוח לעצמו, ולכן החמירה תורה באיסור זה שחל עליו תוקף האיסור מהתחלת הפעולה."],["36","32","פ\"א, כט."],["37","33","קרח ח."],["38","34","קרח פי\"ח, יב. וראה גם פסיקתא דר\"כ פ' ביום השמיני עצרת."],["39","35","אבל להעיר, שלפי תרגום העליר וקאפח בסהמ\"צ להרמב\"ם שם, הובא שם מאמר הגמ' בלשון \"כל המגבי' ידו על חבירו להכותו\" (אבל בגמ' לפנינו ליתא. ובדק\"ס לסנה' שם לא הובאה גירסא כזו. וגם בס' היד לא הובאה תיבת \"להכותו\")."]]],[1301470073,"כפל הלשון, שבסוף מאמרו חוזר עוה\"פ \"אע\"פ שלא הכהו (נקרא רשע)\"<sup data-n=\"40\">36</sup> — להדגיש, שאיסור זה אינו שייך להכאת חבירו, אלא הגבהת יד (להכות) כשל­עצמה היא האיסור, \"אע\"פ שלא (שאין המשך, לא) הכהו\"].\nמשא\"כ להמדרשים, שתוכן הענין דה­רמת יד על חבירו הוא, שזוהי (התחלת הפעולה של) הכאת חבירו, לכן מוסיפים \"מרים ידו להכות חבירו\", \"הפושט ידו לחבירו להכותו\".\n[ועפ\"ז אתי שפיר זה שגם הטור מו­סיף תיבה זו — \"והמרים ידו על חבירו להכותו\" (שליתא בגמ' כנ\"ל)<sup data-n=\"41\">37</sup> — שהרי לדעת הטור החומר דהגבהת ידו על חבירו הוא מפני שזוהי התחלת פעולת הכאת חבירו<sup data-n=\"42\">38</sup> (אע\"פ שלהיותה רק התחלה אין עליו דין רשע, כנ\"ל)].\nאמנם גם שני המדרשים הנ\"ל יש ביניהם חילוק יסודי:\nבשמו\"ר ההדגשה היא — \"מכאן שמ­שעה שאדם מרים ידו להכות חבירו. . נקרא רשע\", והיינו שהמדובר באותו גדר של קריאת שם רשע הנפעל על ידי הכאת חבירו עצמה, והחידוש שבמדרש הוא, שהתחלת קריאת שם זה היא \"מ­שעה שאדם מרים ידו להכות חבירו\", כאילו שבהגבהת ידו הוא מתחיל להכות את חבירו. וזהו כשיטת הב\"י (בפירושו על הטור), שהמגבי' ידו על חבירו הוי מגוף הלאו דחובל (ומכה) חבירו, כנ\"ל.\nמשא\"כ בתנחומא ובמדב\"ר שסתם \"ה­פושט ידו לחבירו להכותו אע\"פ שלא הכהו נקרא רשע\", ומביא פרט זה ביחד עם עוד ג' ש\"נקראו רשעים\" — אין ה­כוונה לדין והלכות רשע, אלא ע\"ד האגדה, כמו שאר הג' שנמנו במדרש שם שנקראו רשעים, שלא הובאו להלכה שנפסלו לעדות ולשבועה. וזהו כדעת הטור, כנ\"ל.\nה. ויש להוסיף ביאור בשיטת ה­רמב\"ם, שעצם הגבהת היד על חבירו יש בו איסור:\nתכלית בריאת האדם ה\"ה \"לשמש את קונו\"<sup data-n=\"43\">39</sup>, על ידי קיום התורה והמצוות, בכל אבר ואבר שבו לפי ענינו (וכ­מבואר בפרטיות בס' חרדים — חלוקת המצות לפי אברי האדם).\nוהנה \"יד\" מורה על ענין הנתינה<sup data-n=\"44\">40</sup>. וי\"ל שזהו עיקר תכלית בריאת היד — להשתמש בה לנתינה (להשפעה, חסד — מה הוא גמ\"ח אף אתה כו'<sup data-n=\"45\">41</sup>); אבל",[["40","36","וראה דק\"ס סנה' שם, שלכמה גי' ליתא סיום זה. וכן ליתא ברי\"ף ב\"ק ס\"פ החובל."],["41","37","ולהעיר שנקט הלשון \"והמרים ידו\" — שהוא ע\"ד ל' המדרש (שמו\"ר), ולא \"המגבי' ידו\" (כל' הש\"ס)."],["42","38","וי\"ל, שמטעם זה מסיים הטור (בהמשך להדין ד\"והמרים ידו כו'\") \"וכל שכן שאסור לחבול בחבירו\" — שלכאורה מקומו בתחילת הלכה זו [וכהסדר ברמב\"ם שמתחיל \"אסור לאדם לחבול כו'\" ואח\"כ ממשיך \"ולא החובל בלבד אלא כל המכה כו' (ומסיים) אפילו להגבי' כו'\"] — אלא שבזה מדגיש שהא ד\"המרים ידו על חבירו להכותו\" הוא גדר אחד עם \"לחבול בחבירו\". ולהעיר שבשו\"ע שם (וכן בשו\"ע אדה\"ז הנ\"ל הערה 13) הושמט סיום זה שבטור."],["43","39","משנה וברייתא סוף קידושין."],["44","40","להעיר ממחז\"ל (תניא פכ\"ג — כח, ב) \"יד המחלקת צדקה\". וראה תקו\"ז בהקדמה (יז, א) חסד דרועא ימינא. שרש מצות התפלה פ\"ב (ע\"פ של\"ה — יא, א­ב. יג, ב ואילך. קסא, א­ב). אוה\"ת ויקרא (כרך ג) ע' תשמח. ועוד."],["45","41","רש\"י עקב יא, כב. פ' ראה יג, ה. וראה ספרי עקב שם. סוטה יד, א."]]],[1301470074,"כאשר האדם \"מגבי' ידו על חבירו\" — שתמורת ההשתמשות ביד לתכלית ברי­אתה, להיטיב לחבירו, ה\"ה משתמש בה באופן הפכי, להכות את חבירו — ול­העיר שזהו רשעות ללא הנאה וריוח להמכה (דלא כמו הנאת הגנב מגניבתו וכיו\"ב<sup data-n=\"46\">42</sup>, ובל' הכתוב<sup data-n=\"47\">43</sup>: לא יבוזו לגנב כי יגנוב למלא נפשו כי ירעב) — הרי יש בזה חטא חמור בין אדם למקום (לבוראו), כי הרי הוא מהפך את תפקיד בריאתה של היד מהקצה אל הקצה, כנ\"ל.\n[ויש להוסיף: כיון שרובן של מצוות התורה הן מצות מעשיות, לעשותן בידו של אדם<sup data-n=\"48\">44</sup>, נמצא, שהאבר העיקרי שבו מתקיים (רוב) ה\"שימוש\" לקונו, הוא יד האדם דוקא (משא\"כ שאר האברים, שאף שגם בהם צריך הוא לשמש את קונו, הרי עיקר שימושם הוא בעניני הכשר מצוה, כמו ריצה לדבר מצוה וכיו\"ב). נמצא, שכשהוא משתמש בידו באופן הפכי, הרי יש בזה ניגוד וסתירה ל­כללות תכלית בריאת האדם \"לשמש את קונו\"].\nוחטא זה כלפי הקב\"ה, מתחיל תיכף בהגבהת היד על חבירו (גם קודם ה­פגיעה בחבירו), שבהגבהה זו ה\"ה מש­תמש בידו היפך כוונת בריאתו<sup data-n=\"49\">45</sup>.\nויש לומר, שענין זה נרמז גם במקור הלימוד — \"ויאמר לרשע למה תכה רעך\":\nהמכה והמוכה בנדו\"ד היו דתן ו­אבירם<sup data-n=\"50\">46</sup>, שהיו \"נצים\"<sup data-n=\"51\">47</sup> זה עם זה. והנה לקמן בסוף פרשתנו<sup data-n=\"52\">48</sup> מסופר, דלאחרי ששוטרי בנ\"י טענו לפרעה \"למה תעשה כה לעבדיך\" ופרעה ענה \"לכו עבדו ותבן לא ינתן לכם ותוכן לבנים תתנו\" — פגעו דתן ואבירם<sup data-n=\"53\">49</sup> את משה ואת אהרן \"ויאמרו אליהם ירא ה' עליכם וישפוט אשר הבאשתם את ריחינו בעיני פרעה ובעיני עבדיו לתת חרב בידם להרגנו\". ונמצא, שדתן ואבירם השתדלו לטובת ישראל (ובפרט ע\"פ הפירוש<sup data-n=\"54\">50</sup> שהם היו משוטרי בנ\"י, שצעקו אל פרעה (כנ\"ל) \"למה תעשה כה לעבדיך גו'\"<sup data-n=\"55\">51</sup>) — ומ\"מ,",[["46","42","ראה לעיל הערה 31."],["47","43","משלי ו, ל."],["48","44","כי העשי' שע\"י רגלי האדם אינה דומה כלל להעשי' שעל ידי ידיו<sup data-n=\"e1\">*</sup>. כנראה במוחש, ש­חכמת המעשה היא ביותר וביותר במלאכות היד מב­מלאכות הרגל."],["49","45","ע\"פ המבואר בפנים יומתק הל' \"המגבי' ידו\" דוקא, ולא נקט לשון כללי — ע\"ד \"כל המכה אדם\" (כלשון הרמב\"ם לפנ\"ז) — הכולל גם בעיטה ברגלים וכיו\"ב, כי החטא בין אדם למקום בעצם ההגבהה כו' על חבירו הוא בעיקר בידו של אדם."],["50","46","רש\"י עה\"פ. נדרים סד, ב. שמו\"ר שם. ובכ\"מ."],["51","47","ל' הכתוב כאן. וראה רמב\"ם הל' חובל ומזיק שם ה\"א — \"דרך נציון\" (אלא שי\"ג \"דרך בזיון\". ואכ\"מ)."],["52","48","ה, טו­כא."],["53","49","רש\"י בפי' הב', משמו\"ר שם (פ\"ה, כ). נדרים סד, ב. ועוד."],["54","50","נחלת יעקב (הובא בשפ\"ח) על פרש\"י שם, ע\"פ שמו\"ר שם.\n[בנחלת יעקב קאי על פי' הא' ברש\"י שם ש\"ויפגעו אנשים מישראל\". אבל מההוכחה שלו (ש\"וודאי מהשוטרים היו\") ממש\"נ \"בצאתם מאת פרעה\" (שאא\"פ לפרש שקאי על משה ואהרן) — מוכח שכ\"ה גם לפי' הב' ברש\"י (ש\"ויפגעו\" קאי על דתן ואבירם)]."],["55","51","שמות שם, טו. — וכמסופר בכ\"מ (ראה רש\"י שם, יד — משמו\"ר עה\"פ. ועוד) מסנ\"פ של השוטרים להגן על בנ\"י."],["e1","*","משא\"כ בבהמה וחי' — אין חילוק (כמעט) בין ידים לרגלים, היזק נעשה ע\"י שניהם, או גם ע\"י שן וקרן שלהם וכיו\"ב."]]],[1301470075,"בנדון זה, תמורת השתדלותם לטובת יש­ראל, הנה הם עצמם ובינם לבין עצמם התנהגו באופן הפכי (היפך רגילותם) והיו נצים זה עם זה!\n[ע\"ד ומעין הנ\"ל במגבי' ידו על חבירו — שתנועת ידו זו היא היפך כוונת בריאת היד עצמה].\nו. ובעומק יותר, וע\"ד החסידות — יש לומר:\nנתבאר במק\"א<sup data-n=\"56\">52</sup>, דכיון שאלפיים שנה קדמה תורה לעולם<sup data-n=\"57\">53</sup>, והרי קודם שנברא העולם לא שייך ענין של חטא כו' — עכצ\"ל, שבכל ענין ותיבה שבתורה יש (גם) פירוש פנימי ורוחני, שעל פיו כולו טוב.\nועד\"ז צ\"ל בענין איסור הכאת חבירו בכלל ובפרט ענין זה ד\"המגבי' ידו על חבירו. . נקרא רשע\" — שאפשר לפרשו גם למעליותא.\nוהביאור בזה:\nנוסף ע\"ז שהענין ד\"תכה רעך\" כפשו­טו ישנו גם בקדושה, כמו \"הכאת\" ה­רופא הנדרשת לרפאות את האדם, ויתי­רה מזו — מצות מילה, שבאה על ידי \"חבלה\" ויציאת דם, באופן שיש על הנימול דין חולה, ועד שביום ג' מחללים עליו את השבת<sup data-n=\"58\">54</sup>, שכ\"ז הוא באופן ש­הוא דבר רצוי וטוב [ומובן, שכבר בעת התחלת מעשה זה (רפואה או מילה ו­כיו\"ב), ע\"ד \"המגבי' כו' אע\"פ שלא הכהו כו'\", ישנה כבר מעלת הטוב עצמו] —\nהנה עמפשנת\"ל בפירוש \"מגבי' ידו על חבירו\", שזהו מצד השינוי הנפעל במציאות היד, היפך תכלית בריאתו — י\"ל שעד\"ז ישנו גם למעליותא, שהאדם משתדל באופן של שינוי טבעו ורגילותו בטובת חבירו, עד לאופן של \"הגבהה\", שמגבי' את \"ידו\" (כח ההשפעה שלו) למעלה ממדידה והגבלה, עד שהוא ב­מצב של \"על חבירו\" — למעלה מחבירו, כי השפעת החסד שלו היא יותר מה­מוכרח לחבירו, ועד שנותן למעלה מ­כלי­הקיבול של חבירו.\nולהעיר משני האופנים<sup data-n=\"59\">55</sup> דנתינה לחבירו: די מחסורו, לעשרו.\nולכן \"נקרא רשע\" — מלשון \"ובכל אשר יפנה ירשיע\"<sup data-n=\"60\">56</sup>, שפירושו \"ינצח\"<sup data-n=\"61\">57</sup>, \"יצליח\"<sup data-n=\"62\">58</sup>, דהיינו הצלחה שלא ע\"ד הרגיל, למעלה ממדידה והגבלה.\nוזוהי גם ההוראה למעשה מהלכה זו: נוסף על פשטות הענין, גודל הזהירות בתכלית מכל ענין של הגבהת יד על חבירו, הרי — מהלכה זו צריך האדם ללמוד גם הוראה בקצה השני — שתהי' הנהגתו הנהגה של \"המגבי' ידו על חבירו\" למעליותא, להשתדל בטובת חבירו — \"יד המחלקת צדקה\" — יותר מטבעו ורגילותו, עד כדי להגבי' ולהוציא את ידו (עם כל מציאותו) מכל מדידות והגבלות, \"בכל מאדך\".\n<span data-k=\"q\">(משיחת ש\"פ נח תשמ\"ח) </span>",[["56","52","לקו\"ש חלק ל ע' 17 ואילך. ועוד. וראה סה\"מ עטר\"ת ע' תקטו ואילך."],["57","53","ב\"ר פ\"ח, ב. תנחומא וישב ד. ועוד."],["58","54","שבת קלד, ב. רמב\"ם הל' מילה פ\"ב ה\"ח. הל' שבת פ\"ב הי\"ד. טושו\"ע או\"ח סשל\"א ס\"ט. שו\"ע אדה\"ז שם סי\"א."],["59","55","ספרי ורש\"י פ' ראה טו, ח. כתובות סז, ב."],["60","56","ש\"א יד, מז."],["61","57","פסיקתא דר\"כ פ' החודש. במדבר רבה פי\"א, ג."],["62","58","ראה סנהדרין צג, ב (ובחדא\"ג מהרש\"א שם ד\"ה לא אמרו). מפרשים לש\"א שם. וראה לקו\"ש חכ\"ה (ע' 277. 281)."]]],[1301470076,"<h3>שיחה ב</h3>\nא. עה\"פ<sup data-n=\"63\">1</sup> \"ויירא משה ויאמר אכן נודע הדבר\" איתא בתנחומא<sup data-n=\"64\">2</sup> שאמר משה \"יש ביניכם לשון הרע והיאך אתם ראויין לגאולה\".\nוצריך להבין: מצינו במדרשי רז\"ל<sup data-n=\"65\">3</sup> שבגלות מצרים היו בין בנ\"י עובדי ע\"ז, ואעפ\"כ נגאלו ממצרים<sup data-n=\"66\">4</sup>, וא\"כ — מהי הפשיטות אצל משה, דמכיון ש\"יש ביניכם לשון הרע (ו)היאך אתם ראויין לגאולה\", שבגלל חטא לשון הרע לחוד כבר אינם ראויים לגאולה?\nרז\"ל הפליגו מאד בחומר האיסור ד­לשון הרע, ואמרו \"כל המספר לשון הרע כאילו כפר בעיקר\"<sup data-n=\"67\">5</sup>, ועד ש\"כל<sup data-n=\"68\">6</sup> המספר לשון הרע מגדיל עונות כנגד שלש עבירות ע\"ז וג\"ע ושפ\"ד\"<sup data-n=\"69\">7</sup>, אבל מ\"מ תמוה הדבר, שהחטא דע\"ז בפו\"מ לא עיכב את גאולתם, ואילו חטא לשון הרע ה\"ה מניעה לגאולת בנ\"י!\nעוד מצינו ברז\"ל שיש חומר בענין לשון הרע אפילו לגבי ע\"ז בענין נצחון במלחמה — כדאיתא בירושלמי<sup data-n=\"70\">8</sup> \"דורו של דוד כולם צדיקים היו וע\"י שהי' להן דילטורים היו יוצאים במלחמה והיו נופלים. . דורו של אחאב עובדי ע\"ז היו ועל ידי שלא הי' להן דילטורין היו יורדים למלחמה ונוצחין\" — אבל לכ­אורה מזה למדנו רק שיש סגולה מיו­חדת בשלום<sup data-n=\"71\">9</sup> (ובמילא — חסרון בלה\"ר ומחלוקת) בענין דנצחון במלחמה; אבל מהי השייכות לגאולת ישראל, ועד כ\"כ שבזה תהי' תלוי' גאולתם משיעבוד ה­אומות?\nב. יתירה מזו:\nבשמות רבה<sup data-n=\"72\">10</sup> על פסוק זה מבליט עוד יותר את חטא לשון הרע כדבר ה­מעכב את הגאולה, וז\"ל \"הי' משה מהרהר בלבו ואומר מה חטאו ישראל",[["63","1","פרשתנו ב, יד."],["64","2","פרשתנו יו\"ד."],["65","3","ראה מכילתא בשלח יד, כט. וראה מכילתא (ופרש\"י) בא יב, ו. וכ\"כ הרמב\"ם הל' ע\"ז ספ\"א — הובא לקמן בפנים (סעיף ה)."],["66","4","להעיר משמו\"ר פמ\"ג, ח."],["67","5","ערכין טו, ב. רמב\"ם הל' דעות פ\"ז ה\"ג."],["68","6","ערכין שם. וראה ירוש' פאה פ\"א ה\"א. רמב\"ם הל' דעות שם. פיהמ\"ש להרמב\"ם אבות פ\"א מי\"ז (בסופה)."],["69","7","וראה בכל הסוגיא דערכין שם (וכן בשאר המקומות שבהערה שלפנ\"ז) כו\"כ פרטים בחומר איסור לשון הרע."],["70","8","פאה שם. הובא גם בבחיי עה\"פ כאן (ושם הביאו ממדרש תהלים ז, ח). וראה גם הנסמן בהערה הבאה."],["71","9","וכמבואר בכ\"מ בחז\"ל מעלה זו בשלום (ו­פחיתות המחלוקת) — ראה ספרי ובמדב\"ר (פי\"א, ז) עה\"פ (נשא ו, כו) וישם לך שלום. ב\"ר פל\"ח, ו. תנחומא צו ז. שופטים יח<sup data-n=\"e2\">*</sup>. פרש\"י נח יא, ט.\nוראה גם מס' דרך ארץ זוטא פ' השלום (ובכ\"מ מהנ\"ל) בנוגע מעלת השלום (וחסרון המחלוקת) ב­כלל."],["72","10","פרשתנו פ\"א, ל."],["e2","*","להעיר, שר\"א הקפר (ברבי) הוא בעל ה­מאמר (בתנחומא שם) \"גדול השלום שאפי' ישראל עצמן עושין ע\"ז ועושין חבורה א' כו'\" (וגם בספרי ובמדב\"ר בעל המאמר הוא ר\"א בנו של ר\"א הקפר), והוא הוא בעל המאמר במכילתא בא שם (שהיו בידם ד' מצות, כדלקמן הערה 34), שלשיטתו (ע\"ש ובמפרשים) היו שטופין במצרים בע\"ז."]]],[1301470077,"שנשתעבדו מכל האומות, כיון ששמע דבריו אמר לשון הרע יש ביניהן היאך יהיו ראויין לגאולה לכך אמר אכן נודע הדבר עתה ידעתי באיזה דבר הם מש­תעבדים\". ומפורש יותר בפרש\"י עה\"ת<sup data-n=\"73\">11</sup>, שבתחילה מביא \"ומדרשו — דאג לו<sup data-n=\"74\">12</sup> על שראה בישראל רשעים<sup data-n=\"75\">13</sup> דלטורין אמר מעתה שמא אינם ראויין להגאל\", ושוב (בד\"ה \"אכן נודע הדבר\") מביא \"ומדרשו נודע לי הדבר שהייתי תמה עליו מה חטאו ישראל מכל ע' אומות להיות נרדים בעבודת פרך אבל רואה אני שהם ראויים לכך\".\nולפי זה — זה שיש בין ישראל \"רשעים דלטורין\" הוא סיבה לא (רק) לזה שאינן ראויין להגאל אלא (גם) ל­היותם \"ראויים לשעבוד\", \"להיות נרדים בעבודת פרך\" יותר מכל ע' אומות. ותמוה: במה הוא החומר דחטא לשון הרע לגבי ענין זה — יותר משאר ה­חטאים?\nועוד וג\"ז עיקר: איך אפשר לומר אשר לה\"ר הי' בישראל יותר מבשבעים האומות, שלכן דוקא בנ\"י נשתעבדו ולא ע' האומות?\nוכ\"ז הוא גם בפרש\"י — (בנדו\"ד מד­רשו המיישב) פשוטו של מקרא<sup data-n=\"76\">14</sup>.\nוגם בגוף פירוש השמו\"ר ופרש\"י יש לעיין: אם חטא לשון הרע הוא סיבה להיות ראויים לשעבוד ולהיות נרדים בעבודת פרך — מהי הרבותא בזה ש­\"אמר מעתה שמא אינם ראויין להגאל\" — הרי בכלל מאתים מנה<sup data-n=\"77\">15</sup>?\nעוד אינו מובן: בדברי דתן ואבירם הי' לא רק חטא לשון הרע, אלא גם חטא הלשנה (שהלשינו על משה לפרעה<sup data-n=\"78\">16</sup>) — והרי חטא הלשנה עולה בחומרו על חטא לשון הרע (וכוללו); מדוע מדגישים חז\"ל שיראת משה היתה (רק) בגלל חטא לשון הרע, ולא על עיקר החומר שב­דבריהם — חטא הלשנה<sup data-n=\"79\">17</sup>?",[["73","11","עה\"פ."],["74","12","בדפוס ראשון ושני, ורוב כת\"י רש\"י שתח\"י — ליתא כל התחלת פרש\"י שלפנינו (\"כפשוטו. . לו\"), והתחלת פרש\"י היא — \"על שראה בישראל כו'\" (וכיו\"ב). אבל בדפוסים שלפנינו ובב' כת\"י רש\"י שתח\"י — הוא כבפנים (וכן הובא בגו\"א). ולכ­אורה תיבת \"לו\" מיותרת (ובא' מכת\"י רש\"י שתח\"י \"דואג הי'\")."],["75","13","בדפוס ראשון ואיזה כת\"י רש\"י שתח\"י \"רשעים גמורים\". ובעוד כת\"י ליתא תיבת \"רשעים\" בכלל."],["76","14","ע\"ד לשון רש\"י בראשית ג, ח."],["77","15","ובילקוט פרשתנו עה\"פ הביא ג\"כ דרש הנ\"ל ב' פעמים, אבל בשתיהם — כטעם על ה­שעבוד: אומר הי' משה לפני הקב\"ה רבש\"ע מפני מה זאת האומה משתעבדת יותר מכל האומות שיש בעולם אכן נודע הדבר החטאה הזאת שלא על חנם משתעבדים. ולאח\"ז מביא: מלמד שהי' משה מהרהר מה ראה הקב\"ה לשעבד ישראל יותר מכל האומות עד שבאו דתן ואבירם<sup data-n=\"e3\">*</sup> שעשו בו דלטוריא."],["78","16","כמו שכ' בתנחומא פרשתנו שם. שמו\"ר שם, לא. פרש\"י עה\"פ ב, טו. ועוד."],["79","17","כן מפורש בשמו\"ר (שם, ל) לפנ\"ז שאמרו \"נודיע עליך מה עשית למצרי\". ואעפ\"כ ממשיך \"כיון ששמע כן נתיירא מלשון הרע\", וכן ממשיך בדברי ר\"י ב\"ר שלום כו' \"כיון ששמע דבריו אמר לשון הרע יש ביניהן היאך יהיו ראויין לגאולה כו'\". וגם בתנחומא ופרש\"י שאינו מפורש שאמרו שיל­שינו עליו לפרעה<sup data-n=\"e4\">*</sup>, לכאורה מובן הוא, מזה שגם לשיטתם הם הלשינו עליו, כבהערה שלפנ\"ז. וב­דפוס שני וכמה כת\"י רש\"י (שתח\"י) כתוב (גם) \"מלשינים\". וראה יפה תואר השלם לשמו\"ר שם. קצור מזרחי לפרש\"י כאן. ועוד. אבל ראה נחלת יעקב לפרש\"י כאן סד\"ה מכאן אנו למדים."],["e3","*","וכן הוא גם בפרש\"י פרשתנו ב, יג. וצ\"ע ההכרח בפש\"מ וכו'. וראה פרש\"י לקמן ה, כ."],["e4","*","בפרש\"י \"רשעים דלטורין\". אבל בפשטות אין פירוש דלטורין מלשינים כ\"א הולכי רכיל וכיו\"ב, אלא שלפעמים כולל ג\"כ מלשינים — ראה ערוך וערוך השלם ערך דלטור."]]],[1301470078,"ג. והנה במק\"א<sup data-n=\"80\">18</sup> איתא \"אמר רב הונא כו' בשביל ד' דברים נגאלו ישראל ממצרים שלא שינו את שמם ואת לשונם ולא אמרו לשון הרע ולא נמצא ביניהן אחד מהן פרוץ בערוה\",\nאשר אין לשון הרע מפורט כסיבה בפ\"ע, אלא כלול בתוך ד' דברים, ואילו לפי דברי התנחומא הנ\"ל משמע<sup data-n=\"81\">19</sup> שחטא לשון הרע לחוד יש בידו למנוע מהם הגאולה.\nוצריך להבין במאי קא מיפלגי.\n[ולכאורה דוחק לומר דפליגי בחומר החטא דלשון הרע — שלפי התנחומא החטא דלשון הרע \"מגדיל עונות כנגד שלש עבירות\" (ולכן יש בחטא זה לחוד כדי למנוע הגאולה); ורב הונא שאומר בשביל ד' דברים נגאלו (ולשה\"ר הוא רק אחד מהם) קאי בשיטת המ\"ד שכל המספר לשון הרע הוא (רק) כאילו כופר בעיקר].\nד. וי\"ל נקודת הביאור בזה:\nידוע שבעת יציאת מצרים היתה לידת עם ישראל<sup data-n=\"82\">20</sup>, דעד אז לא היו בנ\"י בגדר עם (גם בפשש\"מ<sup data-n=\"83\">21</sup>) ובפ\"ע, ורק ביצי\"מ נעשו לעם בפ\"ע, וכמ\"ש<sup data-n=\"84\">22</sup> \"לקחת לו גוי מקרב גוי\". וענין זה, היותם לעם בפ\"ע, פעל בהם אחדות, שנעשו עם אחד, כלומר, שיהיו חפצא אחת של עם, ולא רק קיבוץ של שבעים נפש או י\"ב שבטים וכיו\"ב (מגזע אחד כו').\nולכן כדי שיהיו ראויים לגאולה, היי­נו שיהיו עם אחד בפ\"ע, אא\"פ שתהי' הנהגתם באופן של פירוד ומחלוקת, היפך עם אחד.\nואף שענין האחדות שבעם אינו מיו­חד, לכאורה, לעם ישראל דוקא — שהרי כן הוא גם אצל כל האומות, שהיותם לעם תלוי בזה שמתאחדים יחד, ובלי זה אא\"פ להיות עם — מ\"מ, אצל עם ישראל, גדר האחדות ונחיצותה הוא באופן אחר לגמרי (שלכן, המניעה לגאולה מפני דילטורין שייכת לגאולת ישראל דוקא).\nה. ויש לבאר זה בהקדים מ\"ש ה­רמב\"ם<sup data-n=\"85\">23</sup> בריש הל' עבודה זרה<sup data-n=\"86\">24</sup>, לאחר תיאור האופן שנתפרסם שם השם על ידי אברהם ואח\"כ ע\"י יצחק ויעקב — \"והי' הדבר הולך ומתגבר בבני יעקב ובנלוים עליהם ונעשית בעולם אומה שהיא יודעת את ה', עד שארכו הימים לישראל במצרים וכו'\".\nוקשה: אם בהיותם במצרים (לפני ה­שיעבוד) כבר היו בני ישראל \"אומה\" — מה נתחדש אח\"כ ביצי\"מ בענין זה, שהיתה אז \"לידת עם ישראל\" (כמבואר בכ\"מ, כנ\"ל)?\nוי\"ל שזה מובן ע\"פ המשך דברי",[["80","18","ויק\"ר פל\"ב, ה. שהש\"ר פ\"ד, יב (א). ועוד (נעתקה התחלתו (גם) בשמו\"ר (פרשתנו) פ\"א, כח). וראה גם מכילתא בא שם. ועוד."],["81","19","בנוגע להסתירה בין שתי הדרשות, שברז\"ל הנ\"ל מפורש שלא אמרו לה\"ר וכאן מפורש יש ביניכם לשון הרע — צ\"ל שאח\"כ חזרו בהם עכ\"פ מחטא זה (ראה המשך הלשון בתנחומא \"ועשה שם כ' שנה והיו ראויין ישראל לגאולה\"), וכמ\"ש בצידה לדרך על פרש\"י כאן (בסופו). וראה כלי יקר עה\"פ. של\"ה קס, ב."],["82","20","כמבואר בנבואת יחזקאל קאפיטל טז וב­מפרשים שם. וע\"ד ההלכה אז היתה גירות דעם ישראל (ראה יבמות מו, א ואילך)."],["83","21","כמש\"נ (ויגש מו, ג) לגוי גדול אשימך שם (במצרים)."],["84","22","ואתחנן ד, לד."],["85","23","שבשבוע זה — כ' טבת — יום פטירתו."],["86","24","ספ\"א."]]],[1301470079,"הרמב\"ם שם \"עד שארכו הימים לישראל במצרים וחזרו ללמוד מעשיהן ולעבוד כוכבים כמותן חוץ משבט לוי שעמד במצות אבות כו', וכמעט קט הי' העיקר ששתל אברהם נעקר וחוזרין בני יעקב לטעות העולם ותעיותן ומאהבת ה' אותנו ומשמרו את השבועה לאברהם אבינו עשה משה רבינו רבן של כל הנביאים ושלחו, כיון שנתנבא משה רבינו ובחר ה' ישראל לנחלה הכתירן במצות כו'\"<sup data-n=\"87\">25</sup>,\nשמזה נלמד היתרון בהיותם לעם ל­אחר יצי\"מ לגבי זה שהיו \"אומה\" גם לפני יצי\"מ:\nגדר ה\"אומה\" שלפני יצי\"מ ומ\"ת הוא בזה ש\"נעשית בעולם אומה שהיא יודעת את ה'\", זאת אומרת: (א) האומה \"נעשית\" — מעצמה, ע\"י פעולת אנשי האומה, יעקב ובניו כו'. (ב) עשייתה וגדרה של אומה זו — \"שהיא יודעת את ה'\", ש­ידיעה זו היא המאחדת את אנשי האומה להקרא אומה בפ\"ע.\nולכן מצד זה יתכן ח\"ו ביטול האומה עי\"ז \"שארכו הימים לישראל במצרים וחזרו ללמוד מעשיהן ולעבוד כוכבים כמותן כו' וכמעט קט הי' העיקר ששתל אברהם נעקר וחוזרין בני יעקב לטעות העולם ותעיותן\".\nאבל ביציאת מצרים נתחדש ש\"בחר ה' ישראל לנחלה\"<sup data-n=\"88\">26</sup>, כלומר — (א) היותם לעם ואומה בא מצד בחירת הקב\"ה, ולא מצד פעולת העם, (ב) איכות הווייתן לעם היא באופן של נחלה, שבנ\"י הם נחלתו של הקב\"ה.\nולכן אין שייך בזה ענין הביטול וה­הפסק ח\"ו, שהרי בחירת הקב\"ה הוא ענין נצחי שאין בו שינוי והפסק; וזהו ענינה של \"נחלה\", דירושה אין לה הפסק<sup data-n=\"89\">27</sup>.\nומעתה מובן הטעם שנגאלו ממצרים עם היותם במצב של \"חזרו ללמוד מעשיהן ולעבוד כוכבים כמותן\":\nידוע<sup data-n=\"90\">28</sup> שאמיתית ענין הבחירה הוא כשהדבר נבחר רק ברצון הבוחר ולא מחמת איזו מעלה בדבר הנבחר. כי כאשר רוצה דבר מפני מעלתו של הדבר ההוא, אין לקראה בחירה (חפשית), ש­הרי אז ההכרעה היא לא מצד בחירת ה­בוחר, אלא מצד מעלת הדבר הנבחר.\nומכיון שביצי\"מ \"בחר ה' ישראל ל­נחלה\" — לפיכך לא הי' נוגע בזה (כ\"כ) מעמדם ומצבם הרוחני (דהיינו מעלתם) של בנ\"י<sup data-n=\"91\">29</sup>, כי הכל הי' מצד בחירתו ית'.\nאמנם, כל זה הוא רק בשייכות לשאר עבירות וחטאים, משא\"כ בנוגע לחטא לשון הרע, כדלקמן.",[["87","25","ביאור דברי הרמב\"ם שם — ראה לקו\"ש ח\"כ ע' 21 ואילך."],["88","26","אף שבפרטיות הגמר ושלימות הבחירה הי' במ\"ת (כמ\"ש בשו\"ע אדה\"ז או\"ח סי' ס ס\"ד ממג\"א שם סק\"ב: כשיאמר ובנו בחרת יזכור מ\"ת), וכמו שגמר הגירות דעם ישראל הי' במ\"ת (והתחלתה במצרים), כדאיתא ביבמות שם. וראה לקמן הערה 33."],["89","27","ב\"ב קלג, סע\"א. וראה גם שם קכט, ב. ועוד."],["90","28","ראה בארוכה לקו\"ש חי\"א ע' 5 ואילך. וש\"נ."],["91","29","ויתירה מזו ע\"פ מ\"ש אדה\"ז בתניא פמ\"ט ש\"ובנו בחרת כו' הוא הגוף החומרי הנדמה ב­חומריותו לגופי אוה\"ע\" [כי בחירה שייכת דוקא בשני דברים שווים, ולכן בהנשמה שהיא חלק אלקה ממעל ממש (תניא רפ\"ב) לא שייך בזה אמיתית ענין הבחירה — ראה לקו\"ש חכ\"ג ע' 219 ואילך] — מובן שדווקא במצב כזה דבנ\"י מודגשת בחירת הקב\"ה. וי\"ל שעפ\"ז יומתקו דברי הרמב\"ם שם שבחירת השם היתה לאחרי היות ישראל במצרים וחזרו ללמוד מעשיהן ולעבוד כוכבים כו'."]]],[1301470080,"ו. ההסברה בזה:\nבלשון הרע — ג' ענינים, בכללות<sup data-n=\"92\">30</sup>:\nא) היזק חבירו ע\"י לה\"ר, כמובן ב­פשטות, ו\"אמרו חכמים שלשה לשון הרע הורגת כו'\"<sup data-n=\"93\">31</sup>.\nב) מציאות וגילוי הרע שבאדם, שלכן הוא מספר בגנות חבירו כו'.\nג) הדיבור דלשון הרע (מה שאחד מדבר על חבירו), גם אם אין רצונו לה­זיקו, אפילו כשאין כוונתו לספר בגנותו ואינו מדבר בשנאה<sup data-n=\"94\">32</sup>, כ\"א עצם הדיבור אודות הרע שבחבירו, פעולתו הלא­טובה של חבירו (וכיו\"ב) — מורה ומד­גיש את הפירוד והחילוק בין אחד לשני.\nוהנה, בב' הפרטים הראשונים שב­לה\"ר דומה הוא לשאר חטאים: כשם ש­שאר חטאים (בדעות, במדות או במעשה) אינם פוגעים בבחירתו של הקב\"ה ב­ישראל, מאחר שהבחירה היא מצד ה­בוחר ולא מצד מעלתו של הנבחר, כן הוא בלשון הרע, שאינו פוגע בבחירת הקב\"ה;\nאבל זה שלשון הרע גורם לפירוד ומחלוקת, ה\"ז בסתירה לבחירה זו. ה­בחירה היא בהמציאות דעם ישראל, עם אחד. כלומר: אף שבחירת הקב\"ה אינה בגלל המעלות (הרוחניות) שבבני ישר­אל, כ\"א אך ורק מצד בחירתו ית' החפ­שית — מ\"מ, צ\"ל \"חפצא\" של עם ישראל שבו היא הבחירה<sup data-n=\"95\">33</sup>; וכאשר יש פירוד בין אחד לחבירו (בהנהגה חיצוניות עכ\"פ) חסר במציאותה של החפצא ד­\"(עם) אחד\".\nוזהו פירוש דיוק דברי חז\"ל שדאגת משה היתה מזה ש\"יש ביניכם לשון הרע\" (דהיינו אמירתם למשה \"מי שמך לאיש שר ושופט עלינו הלהרגני אתה אומר כאשר הרגת את המצרי\") — (ולא הדגי­שו הפרט דהלשנה לפרעה) — כי זהו עיקר המונע להגאולה: עצם הדבר שבן ישראל אינו נמנע מלדבר לשון הרע על איש אחר מבנ\"י מורה על הפירוד שיש בבנ\"י; ולכן זה דוקא (גם אם לא הי' מלשין עליו בפני פרעה) עורר דאגתו של משה ו\"אמר מעתה שמא אינם ראויין להגאל\".\nז. ועפ\"ז י\"ל, שגם תוכן דברי ר\"ה (הנ\"ל ס\"ג) \"בשביל ד' דברים נגאלו ישראל ממצרים כו'\", הוא מטעם הנ\"ל, היינו שזה נוגע לבחירה הכללית ד­הקב\"ה בעם ישראל — אלא ששם המכוון הוא מצד ההבדל של בני ישראל מה­מצריים, ואילו כאן העיקר הוא מצד האחדות דבנ\"י כשלעצמם.\nוהביאור:\nכל ד' דברים אלו \"שלא שינו את שמם ואת לשונם ולא אמרו לשון הרע",[["92","30","להעיר מלקו\"ש חכ\"ב ע' 67 ואילך."],["93","31","לשון הרמב\"ם הל' דעות פ\"ז ה\"ג (מערכין טו, ב. ירוש' פאה שבהערה 6). וראה גם רמב\"ם שם בריש הפרק ובכס\"מ שם. ועוד."],["94","32","ראה רמב\"ם שם ה\"ד. וש\"נ."],["95","33","ואולי י\"ל, דביצי\"מ היתה בחירה כללית — בחירת הקב\"ה בבני ישראל כעם, ובמ\"ת (שהוא ה­גמר והתכלית דיצי\"מ, וכמ\"ש (פרשתנו ג, יב) \"בהו­ציאך את העם ממצרים תעבדון את האלקים על ההר הזה\"), נתוספה בחירה פרטית — בחירת הקב\"ה בכל אחד מבנ\"י בפרט [ויש להעיר — חיובי תורה ומצות הם חיובים פרטיים על כאו\"א מישראל, וכמודגש בדיבור הראשון דעה\"ד (יתרו כ, ב. ואתחנן ה, ו) \"אנכי ה' אלקיך\" ל' יחיד — שכ\"א הי' אומר עמי הדבור מדבר (יל\"ש יתרו שם (רמז קפו), מפסיקתא דר\"כ פ' בחודש השלישי. וראה פסיקתא רבתי פכ\"א. רמב\"ן יתרו שם)]. ואכ\"מ."]]],[1301470081,"ולא נמצא ביניהן אחד מהן פרוץ ב­ערוה\" — תוכנם וענינם, שבהיותם מיו­חדים במעלות אלו היו מובדלים בנ\"י כעם אחד בפ\"ע — מהמצריים.\nועם היות שההדגשה במרז\"ל זה היא לא רק על שלילת החסרון הפוגם ב­אחדותם בתור עם אחד (שלא. . אמרו לשון הרע כו'), כ\"א גם על המעלות (החיוביות)<sup data-n=\"96\">34</sup> בפעולת והנהגת כאו\"א בפרט — דכ\"א לא שינה שמו כו', מ\"מ ה­עיקר בזה הוא — מה שהם מובדלים מהמצריים כנ\"ל, ולכן גם לה\"ר נכלל בד' הדברים כי זה ש\"לא הלשין אחד על חבירו\"<sup data-n=\"97\">35</sup> היינו למצריים שביכולתם להרע לבנ\"י;\nמשא\"כ בהדרש על הכתוב כאן, ש­משה דאג שמא אינם ראויים להגאל, הכוונה היא מצד חסרון כללי בה\"עם\" בזה שיש בהן \"דילטורין\" (ולא חסרון דלה\"ר כא' מד' הענינים) — כי החשש כאן אינו שמא ילשינו עליו לפרעה, כ\"א ע\"ז שהם במצב של פירוד ביניהם (דהיינו הענין הג' דלעיל ס\"ו)<sup data-n=\"98\">36</sup>.\nח. ע\"פ כהנ\"ל יש לבאר (בפנימיות), מה שרש\"י מחלק דברי השמו\"ר כאן \"הי' משה מהרהר כו'\" — (בב' ד\"ה ו)לב' ענינים<sup data-n=\"99\">37</sup> (כנ\"ל ס\"ב):\n\"ומדרשו דאג כו' אמר מעתה שמא אינם ראויין להגאל\"; \"ומדרשו נודע לי הדבר שהייתי תמה עליו מה חטאו ישראל. . להיות נרדים בעבודת פרך אבל רואה אני שהם ראויים לכך\". וב­הקדם:\nהטעם (הפנימי) לכך ד\"לשון הרע ו­דילטורין\" פוגע רק ב\"עם ישראל\" ולא בשאר האומות<sup data-n=\"100\">38</sup>, מובן ע\"פ הידוע<sup data-n=\"101\">39</sup> (וגם בפשוטו ש\"מ<sup data-n=\"102\">40</sup>) שקדושה ענינה אחדות [שלכן נאמר ביעקב \"נפש\" ל' יחיד — אף שהיו שבעים<sup data-n=\"103\">41</sup>], משא\"כ בלעו\"ז הוא ב­",[["96","34","להעיר שבמכילתא (בדעת ר\"א הקפר) הל' הוא \"וכי לא הי' בידם של ישראל ד' מצוות שאין כל העולם כדאי בהם\".\n[וחולק על מ\"ד הא' (ר' מתיא בן חרש) שם שהיו ערומים מכל המצות — ראה פי' \"זה ינחמנו\" ו­מרכבת המשנה למכילתא שם. ובפרש\"י בא יב, ו הביא בהמשך לדברי ר' מתיא בן חרש, גם מדברי ר\"א הקפר — ראה לקו\"ש חט\"ז ע' 116 ואילך. ואכ\"מ]."],["97","35","ל' רז\"ל — בהנסמן בהערה 18."],["98","36","בסגנון אחר: ברז\"ל הנ\"ל בשביל ד' דברים ה\"ז סיבה חיובית, זכות שיש להם שהם ראויין לגאולה, כדברי המכילתא שם (ובפסיקתא דר\"כ (פ' ויהי בשלח), שהש\"ר (פ\"ד, יב (א)), במדב\"ר (פ\"כ, כב), תנחומא בלק (טז), פדר\"א (ספמ\"ח) הלשון \"בזכות ד' (ג') דברים כו'\"), ומניעה מלשון הרע לבד אינה סיבה מספיקה להגאל;\nמשא\"כ בהדרש שלפנינו, שהמדובר בפעולת ודיבור לה\"ר, הפירוד בין א' לחבירו — היא לבדה סיבה ש\"אינן ראויין להגאל\"."],["99","37","בב' כת\"י רש\" שתח\"י — הגירסא: ויירא משה, כפשוטו. אכן נודע הדבר, כמשמעו (ואח\"כ ממשיך) ומדרשו דואג כו' על שראה כו' (ואח\"כ) אכן נודע הדבר, נודע לי דבר כו'."],["100","38","להעיר מב\"ר ופרש\"י נח שבהערה 9 ב­מעלת דור ההפלגה על דור המבול ששנאוי המח­לוקת וגדול השלום. וי\"ל א) דשם מדובר במחלוקת שבמעשה, \"דור המבול היו גזלנים והיתה מריבה ביניהם\" (ל' רש\"י שם), וזה נוגע גם אצל ב\"נ. ובישראל פוגע הפירוד מצד הדיבור דאחד על חבירו, גם בלא היזק כו'. ב) לפני יצי\"מ ומ\"ת דלא היתה עדיין ההבדלה בין ישראל לעמים, פעל ענין האחדות גם בב\"נ. וראה לקו\"ש ח\"ו ע' 55 ואילך. ח\"ט ע' 112 הערה 38. וראה גם לקו\"ש חכ\"א ע' 106 ואילך."],["101","39","בהבא לקמן — ראה בארוכה תו\"ח נח עג, ג ואילך. ד\"ה החלצו תרנ\"ט פ\"ג ואילך (סה\"מ תרנ\"ט ע' נה ואילך). ועוד."],["102","40","פרש\"י ויגש מו, כו."],["103","41","ראה ויק\"ר פ\"ד, ו (פרש\"י בהערה ה­קודמת)."]]],[1301470082,"אופן דפירוד והתחלקות [דלכן בעשו — אף שהיו רק שש נפשות נאמר \"נפשות\" ל' רבים<sup data-n=\"103\">41</sup>].\nושרש הענין (בפנימיות) הוא: פירוד והתחלקות באים כתוצאה מישות וגאוה, שמרגיש את עצמו ליש ודבר חשוב, ולכן אינו יכול להיות באחדות והת­כללות עם חבירו — כי הזולת ממעט את מציאותו;\nמשא\"כ בנ\"י שעליהם נאמר<sup data-n=\"105\">42</sup> \"כי אתם המעט מכל העמים — שממעטין עצמכם\"<sup data-n=\"106\">43</sup>, היינו שהם בביטול (היפך הישות), ולכן כ\"א נותן מקום לזולתו, עד שהם באחדות והתכללות<sup data-n=\"107\">44</sup>.\nוהנה נראה בחוש, שגם מי שיש בו תוקף הישות והגאוה, הרי כשנמצא ב­מצב של עבדות ובפרט באופן דעבודת פרך, הרי זה פועל שבירת ונמיכות רוחו וביטול ישותו וגאוותו (היפך ממש\"נ<sup data-n=\"108\">45</sup> וישמן ישורון ויבעט)<sup data-n=\"109\">46</sup>.\nוזוהי כוונת רש\"י בזה שמחלקם לב' ענינים — ד\"דאג. . שמא אינם ראויין להגאל\"; \"נודע לי. . בעבודת פרך. . ראויים לכך\":\nא) מכיון שיש בהם דילטורין — שמא אינם ראויין להגאל;\nאבל מכיון שסו\"ס הגאולה עתידה לבא, לכן —\nב) \"ויאמר אכן נודע הדבר\" — שראויים לעבודת פרך, שכוונתו בזה — לא שראויים לזה בתור עונש (על חטאם בלה\"ר), אלא, הם ראויים להיות \"נרדים בעבודת פרך\", \"עבודה קשה המפרכת את הגוף ומשברתו\"<sup data-n=\"110\">47</sup>, למען הכין אותם להיות ראויים להגאולה;\nוכמשנת\"ל, שע\"י שבירת רוחם והכ­נעת גאוותם וישותם (הסיבה), מתבטל במילא (המסובב —) הפירוד שביניהם — לה\"ר<sup data-n=\"111\">48</sup> ודילטורין, שאז ראויים להגאל, כי שלימות ענין הגאולה הוא לא רק שיהיו עם אחד מצד מעלתם וענינם (היינו מה ש\"לא שינו כו' לשון הרע כו'\"), כ\"א (גם) מצד בחירתו של הקב\"ה.\nואז נעשו אומה נצחית, שא\"א להם להתבטל עוד בתור אומה — \"בחר ה' ישראל לנחלה\", עם עולם.\n<span data-k=\"q\">(משיחת ש\"פ צו תשכ\"ו) </span>",[["103","41","ראה ויק\"ר פ\"ד, ו (פרש\"י בהערה ה­קודמת)."],["105","42","ואתחנן ז, ז. חולין פט, א — הובא בפרש\"י עה\"פ."],["106","43","וראה בהמשך הגמ' (ופרש\"י עה\"פ) בנוגע אוה\"ע שהוא להיפך."],["107","44","עפ\"ז תומתק השייכות בין ב' הדיעות בערכין שם \"כל המספר לשון הרע אמר הקב\"ה אין אני והוא יכולין לדור בעולם כו' ואיכא דמתני לה על גסי הרוח\", דשניהם מאותו הטעם (וכמודגש בהכתוב (תהלים קא, ה) שהביא מ\"ד הא' \"גבה עינים ורחב לבב גו'\"). אלא דמ\"ד הא' חשיב מעשה ופעולת האדם — לה\"ר; ו\"איכא דמתני\" חשיב עיקר הסיבה — \"גסות הרוח\"."],["108","45","האזינו לב, טו."],["109","46","ראה גם בהנסמן בהערה 48."],["110","47","ל' רש\"י — פרשתנו א, יג. וראה סוטה יא, ריש ע\"ב ובפר+ש\"י."],["111","48","וכמ\"ש בערכין שם: מה תקנתו של מספרי לה\"ר כו' אם ע\"ה הוא ישפיל דעתו שנאמר (משלי טו, ד) וסלף בה שבר ברוח, ובפרש\"י שם: מי ש­סילף בה וחפץ לסלקה שלא תהא בו עוד ישבור רוחו. וכמבואר בהסוגיא בגמ' שם, מדרשי רז\"ל ובפרש\"י ר\"פ מצורע ועוד — בהטעם שלוקחים למצורע (עץ ארז ו)אזוב ושני תולעת."]]],[1301470083,"<h3>שיחה ג</h3>\nא. ויקח משה את אשתו ואת בניו וירכיבם על החמור וישב ארצה מצרים ויקח משה את מטה האלקים בידו<sup data-n=\"112\">1</sup>. ופרש\"י \"על החמור\" — \"חמור המיוחד, הוא החמור שחבש אברהם לעקידת יצחק<sup data-n=\"113\">2</sup>, והוא שעתיד מלך המשיח ל­הגלות עליו שנאמר<sup data-n=\"114\">3</sup> עני ורוכב על חמור\".\nבפשטות כוונת רש\"י הוא לבאר מ\"ש \"על החמור\", בה\"א הידיעה<sup data-n=\"115\">4</sup>, שמזה מוכח שהכוונה ל\"חמור המיוחד\", ומפרש רש\"י את ייחודו של החמור — \"הוא החמור שחבש אברהם כו'\".\nאבל יש להבין:\nא) בכדי לבאר ייחודו של חמור זה הי' מספיק לכאורה לומר \"הוא החמור שחבש אברהם\" ותו לא, שבגלל זה הרי הוא כבר \"חמור מיוחד\", ומהו הצורך להוסיף שהחמור שחבש אברהם אבינו הי' לעקידת יצחק (שהרי לא מצינו ב­קרא שאברהם חבש חמור בזמן או לענין אחר), ומה גם להוסיף עוד ש\"הוא (ה­חמור) שעתיד מלך המשיח להגלות עליו\", דבר נפלא ונס גדול ביותר, שה­חמור יהי' חי וקיים אלפי שנים<sup data-n=\"116\">5</sup>! ובפרט שכ\"ז אינו נוגע להבנת הכתוב.\nב) לשם מה מעתיק רש\"י מהכתוב גם תיבת \"על\" — הרי לפי הנ\"ל מבאר רק תיבת \"החמור\"?\nב. והנה בגמ'<sup data-n=\"117\">6</sup> איתא שפסוק זה הוא אחד מהפסוקים ששינו ע\"ב הזקנים כש­תרגמו את התורה עבור תלמי המלך וכתבו \"וירכיבם על נושא בני אדם\", ופרש\"י<sup data-n=\"118\">7</sup> \"דמשמע גמל שלא יאמר משה רבכם לא הי' לו סוס או גמל\", ובראב\"ע כאן<sup data-n=\"119\">8</sup> פירש הטעם לשינוי זה \"בעבור שהוא דרך גרעון שתרכב אשת הנביא על חמור אחד היא ושני בני'\".\nועפ\"ז יש מקום לומר שכוונת רש\"י היא גם ליישב השאלות הנ\"ל<sup data-n=\"120\">9</sup>, מדוע הרכיב משה את אשתו ושני בניו על חמור אחד<sup data-n=\"121\">10</sup> (ובפרט שכפי שמסתבר ב­",[["112","1","פרשתנו ד, כ."],["113","2","וירא כב, ג."],["114","3","זכרי' ט, ט."],["115","4","ראה מפרשי רש\"י כאן — קצור מזרחי. באר מים חיים (לאחי המהר\"ל). דבק טוב. ועוד."],["116","5","בגו\"א כאן בסופו (וכן בגבורות ה' פכ\"ט) \"ואין הפירוש שהחמור הי' חי כ\"כ\". אבל בפרש\"י אינו נחית לתרץ ולבאר זה. ובפשטות משמע כפשוטו, שהוא אותו החמור. וראה רש\"י וירא (כב, יג) באילו של א\"א \"מוכן הי' לכך מששת ימי בראשית\"."],["117","6","מגילה ט, א."],["118","7","ד\"ה נושא. ובתוד\"ה על \"פן יאמר להם וכי לא הי' לו למשה רבכם סוס או גמל\". וראה הגהות הרש\"ש שם."],["119","8","פרשתנו עה\"פ."],["120","9","ראה גם מלאכת הקודש ובאר בשדה על פרש\"י כאן. וכ\"מ מחדא\"ג מהרש\"א מגילה שם. ש\"ך עה\"ת כאן."],["121","10","בראב\"ע שם מביא \"ויפת אמר כי הוא שם המין\"<sup data-n=\"e5\">*</sup> (ועד\"ז הוא בטור הארוך, אברבנאל ועוד כאן). וממשיך בראב\"ע (דלא כיפת) \"ואין לתמוה אם רכב גרשום בנו אחרי' כי אולי קטן הי' והי' אליעזר בחיקה כי עוד לא נימול\" (וראה גם חזקוני כאן). וברמב\"ן כאן בתחלתו \"כי לא הי' לו רק גרשום כאשר הזכיר הכתוב ואליעזר נתעברה ממנו בדרך או במצרים אם הלכה שם\". אבל בפרש\"י (ד, כד) מפורש שאליעזר נולד לפני הליכתו למצרים. וראה גם פרש\"י יתרו יח, ב."],["e5","*","ולפי' העץ יוסף בתנחומא כאן (כג) זוהי הכוונה בתנחומא \"כאדם שאומר יצאו הבהמין [יצאה הבהמה]\"."]]],[1301470084,"פשטות — יחד עם כל חפציהם) — ולא הרכיבם על (סוס או גמל, או) כמה חמורים? ולכן מפרש רש\"י שלא הי' חמור רגיל אלא \"חמור המיוחד\" ש\"הוא החמור שחבש אברהם כו'\", וכיון שכן, אין פלא איך שחמור פלאי כזה<sup data-n=\"122\">11</sup> בכוחו לשאת משא כבד שאינו רגיל ובטבע.\n[ועפ\"ז יש לומר, שענין זה מרמז רש\"י במה שהעתיק מן הכתוב גם תיבת \"על\", להדגיש, שבפירושו בא לבאר וליישב מה שהרכיב והעמיס כל כך \"על ה­חמור\"].\nאמנם הא גופא טעמא בעי: מדוע הוצרך משה לקחת חמור מיוחד ול­הרכיב עליו את אשתו ואת שני בניו וכל חפציהם — ולא לקח די חמורים או סוס וגמל וכיו\"ב<sup data-n=\"123\">12</sup>?\nג. גם צריך ביאור:\nדרש זה שבפרש\"י מקורו בפרקי דר' אליעזר<sup data-n=\"124\">13</sup>, אבל שם מקדים \"הוא החמור בן האתון שנבראת בין השמשות\", ואילו רש\"י משמיט פרט זה.\nואף שגם כשרש\"י מביא מדרשי חז\"ל אין דרכו להעתיקם בלשונם וכצורתם אלא מביא רק מה שנוגע לפשוטו של מקרא, כמשנ\"ת כמה פעמים (ומה גם בנדו\"ד שבפדר\"א בא הדרש על הפסוק דאברהם, ואילו רש\"י כאן מביאו כדי להסביר הפסוק דפרשתנו) — מ\"מ, כיון שתוכן הדרש הוא להסביר ייחודו של חמור זה, הו\"ל לרש\"י להביא הפרט שבו כבר נתייחד החמור והי' ידוע בו ש\"הוא בן האתון שנבראת בין השמשות\"\n— הענין שהוא החמור ש\"עתיד מלך המשיח להגלות עליו\", ה\"ז באחרית הימים ואיך יתיישב זה בפשוטו של מקרא.\nועכצ\"ל, שכוונת רש\"י כאן היא לבאר לא (רק) את ייחודו של חמור זה בכלל (כבפרקי דר\"א), אלא בעיקר את ייחודו של החמור בנוגע לעניננו — לענין הלי­כת משה ממדין למצרים כדי לגאול את ישראל, ולכן הביא גם את הפרט ש\"הוא שעתיד מלך המשיח להגלות עליו\", כלו­מר שחמור זה נועד עבור גאולת ישראל — שהרי הליכת משה עם אשתו ובניו למצרים היתה כדי לגאול את בני ישר­אל מארץ מצרים<sup data-n=\"125\">14</sup>.\nאבל לפ\"ז אינו מובן לאידך: הענין",[["122","11","שכבר אז הי' לפחות קרוב לד' מאות שנה — מזמן אברהם, ומכ\"ש ע\"פ המשך ל' רש\"י שחמור זה יהי' גם אצל משיח."],["123","12","בשלמא אם משה עצמו הי' רוכב על חמור זה, י\"ל טעמו: היות שחמור זה נועד לדברים חשובים ונעלים, שאברהם אבינו חבשו לעקידת יצחק והוא החמור שעתיד המלך המשיח להגלות עליו, לכן מתאים שגם משה (גואל ראשון) ירכב עליו בשליחות של הקב\"ה לגאול את ישראל ממצרים. אבל בפסוק נאמר רק \"ויקח משה את אשתו ואת בניו (בלבד) וירכיבם על החמור\"<sup data-n=\"e6\">*</sup> — וא\"כ מה טעם השתמש משה בחמור המיוחד, שאותו חבש אברהם לעקידת יצחק וכו'? וראה לקמן הערה 25."],["124","13","פל\"א."],["125","14","ראה אברבנאל כאן (ועוד) בטעמו של משה לקחת גם אותם — כדי לחזק לבב ישראל כו'. ולהעיר מפרש\"י יתרו שם."],["e6","*","ראה פי' הר\"ח (הובא בבחיי כאן ד, כד) — שמבאר הכתוב כאן שמשה שלח אותם לפניו וזהו פי' \"וירכיבם על החמור\". וכן הוא בש\"ך עה\"ת שם."]]],[1301470085,"ד\"הוא החמור שחבש אברהם לעקידת יצחק\", לכאורה אינו שייך לנדו\"ד<sup data-n=\"126\">15</sup>.\nד. וי\"ל הביאור בזה:\nבפירושו כאן בא רש\"י לבאר היתור שבפסוק, שלכאורה אינו מובן<sup data-n=\"127\">16</sup> למה לי' לפרש ולפרט אופן הליכת משה ומש­פחתו למצרים — \"וירכיבם על החמור\" — ולא כתב בקיצור \"ויקח משה את אשתו ואת בניו וישב ארצה מצרים גו'\" — ובביאורו של רש\"י מתיישב הקשר ד­פרט זה לכללות פרשה זו, כדלקמן.\nבהשקו\"ט בין משה והקב\"ה אודות שליחותו לגאול את ישראל, שהקב\"ה צווהו \"לכה ואשלחך אל פרעה והוצא את עמי בני ישראל ממצרים\"<sup data-n=\"128\">17</sup> ומשה סירב לקבל את השליחות, הנה בסיום הז' ימים שבהם \"הי' הקב\"ה מפתה את משה בסנה לילך בשליחותו\"<sup data-n=\"129\">18</sup> אמר משה \"שלח נא ביד תשלח\"<sup data-n=\"130\">19</sup>, ולפי פירוש רש\"י יש במענה זה שני ענינים: א) \"שלא הי' רוצה ליטול גדולה על אהרן אחיו שהי' גדול הימנו ונביא\"<sup data-n=\"129\">18</sup>, ולכן אמר \"שלח נא ביד תשלח\" — \"ביד מי שאתה רגיל לשלוח והוא אהרן\"<sup data-n=\"132\">20</sup>, ב) \"ביד אחר שתרצה לשלוח שאין סופי להכניסם לארץ ולהיות גואלם לעתיד\"<sup data-n=\"132\">20</sup>.\nאמנם, בסופו של דבר קיבל משה על עצמו את השליחות להוציא את בני ישראל, ופרש\"י<sup data-n=\"134\">21</sup> שזהו מפני \"שחרה בו וקבל עליו\", אבל לא נתפרש בכתוב במה ואיך נשללה טענת משה הנ\"ל [ואף שבכתוב ממשיך<sup data-n=\"135\">22</sup> \"הלוא אהרן אחיך הלוי ידעתי כי דבר ידבר הוא וגם הנה הוא יוצא לקראתך וראך ושמח בלבו\", כפרש\"י \"לא כשאתה סבור שיהא מקפיד עליך שאתה עולה לגדולה\", אינו גלאַ­טיק כ\"כ כי סירובו של משה לא הי' רק מצד קפידתו של אהרן, אלא שלא הי' רוצה ליטול גדולה על אהרן אחיו שהי' גדול ממנו].\nולכן י\"ל, שכאשר הסכים משה לקיים שליחותו של הקב\"ה, נרמז המענה על טענותיו בזה שסיבב<sup data-n=\"136\">23</sup> הקב\"ה<sup data-n=\"137\">24</sup> שההלי­כה לקיום השליחות תהי' ע\"י החמור \"ה­מיוחד\" — ש\"הוא החמור שחבש אברהם לעקידת יצחק והוא שעתיד מלך המשיח להגלות עליו\", שבזה מבוארים שני הענינים<sup data-n=\"138\">25</sup>:",[["126","15","ודוחק גדול לומר שאין להחשיבו בתור חמור המיוחד ולקוראו \"החמור\" רק בגלל מה שיקרה לעתיד (\"הוא שעתיד מלך המשיח להגלות עליו\")."],["127","16","ראה באר בשדה על פרש\"י כאן."],["128","17","ג, יו\"ד."],["129","18","ל' רש\"י ד, יו\"ד."],["130","19","ד, יג."],["129","18","ל' רש\"י ד, יו\"ד."],["132","20","פרש\"י שם."],["132","20","פרש\"י שם."],["134","21","שם, יו\"ד."],["135","22","שם, יד."],["136","23","להעיר גם מרמב\"ן כאן (בסופו): צוהו הקב\"ה. . וישוב למצרים עם בניו ואשתו. אבל לפרש\"י קשה לומר כן, דא\"כ לא הי' מקבל מאהרן לשלחם חזרה (ראה פרש\"י יתרו יח, ב). משא\"כ להרמב\"ן חזרו אח\"כ ומטעם אחר, ע\"ש."],["137","24","וי\"ל שלכן לא העתיק רש\"י בהד\"ה תיבת \"וירכיבם\" (אף שגם תיבה זו מיותרת, כנ\"ל בתחילת הסעיף), כי אז היינו מפרשים שרש\"י בא לתרץ רק זה שמשה הרכיב את אשתו ובניו על החמור (כנ\"ל ס\"ב), ולא שזה הי' רמז ומענה לטענתו של משה."],["138","25","וי\"ל שזהו הטעם שנאמר \"וירכיבם על החמור\" רק בנוגע לאשתו ובניו ולא שמשה עצמו רכב על החמור (ראה לעיל הערה 12), כי דוקא ברכיבה בלתי רגילה כזו, שהרכיב אשתו ובניו (וכן חפציהם) על חמור אחד, מדגיש שהי' כאן ענין מיוחד בשייכות להליכתו למצרים (משא\"כ אם הי' נאמר שמשה בעצמו רכב על החמור היינו מפרשים שהוא מצד זה שחמור זה עתיד מלך המשיח להגלות עליו ושייך לגאולה, ולכן גם משה רכב עליו בדרכו למצרים ע\"מ להוציא את בנ\"י, כנ\"ל). ועצ\"ע."]]],[1301470086,"ב\"עקידת יצחק\" (כשחבש אברהם את חמורו) נצטווה — \"והעלהו שם לעולה\"<sup data-n=\"139\">26</sup>, ומ\"מ לא הסס אברהם אבינו לרגע למלא את ציווי ה', ואדרבא \"נזדרז למצוה\" ו­עד שחבש את חמורו \"בעצמו ולא צוה לאחד מעבדיו\"<sup data-n=\"140\">27</sup>.\nומזה מובן בכ\"ש וק\"ו בנדו\"ד, אף שיש בזה נטילת \"גדולה\" (ונוסף לעצם נטילת הגדולה — אפשר שיבוא לידי קפידה אצל אהרן, או שעכ\"פ לא יתרצה ויקבלו בלב שלם) — איך שצ\"ל קיום ציווי השם במילואו ובשמחה ובלב שלם.\nובשייכות לטענה הב' \"שאין סופי להכניסם לארץ ולהיות גואלם לעתיד\" — רמז לו הקב\"ה \"והוא שעתיד מלך המשיח להגלות עליו\", היינו שאין הם שני ענינים וגאולות נפרדות, אלא שה­גאולה העתידה על ידי מלך המשיח, הריהי המשך לגאולה זו דיצי\"מ שעל ידי משה, והגאולה העתידה והתגלות מלך המשיח תלוי' בכחו של משה<sup data-n=\"141\">28</sup> ופעולתו בגאולת מצרים.\nה. ע\"פ הנ\"ל יש לבאר גם כמה דיוקי לשונות ברש\"י:\nא) בענין הא' כתב \"הוא החמור שחבש אברהם\", ובענין הב' כ' \"הוא שעתיד מלך המשיח להגלות עליו\". ולכ­אורה כשם שגבי אברהם נקט ע\"פ לשון הכתוב (\"ויחבוש את חמורו\"), כך הו\"ל לנקוט לשון הכתוב גבי משיח \"רוכב על חמור\", והל\"ל \"והוא שעתיד מלך המשיח לרכוב עליו\" (ע\"ד לשון הפדר\"א<sup data-n=\"124\">13</sup>).\nב) בפדר\"א שם \"שעתיד בן דוד לרכוב עליו\", ואילו רש\"י שינה וכתב \"מלך המשיח\".\nוהביאור בזה:\nנת\"ל (ס\"ג), שבפדר\"א כוונתו למנות את כל מעלותיו של החמור שחבש אבר­הם אבינו לעקידת יצחק, ש\"הוא החמור בן האתון שנבראת בין השמשות. . הוא החמור שרכב עליו משה בבואו למצרים. . הוא החמור שעתיד בן דוד לרכוב עליו\", ולכן הסתפק בלשון הכתוב ש­נאמר בו \"עני ורוכב על חמור\", וכינהו בשם \"בן דוד\":\nמשא\"כ כוונת רש\"י כאן היא (כנ\"ל) לבאר הקשר דחמור זה לנדו\"ד, וכנ\"ל שבחמור המיוחד הזה נרמזת התשובה על סירובו של משה — וזהו דיוק לשון רש\"י בשני הפרטים (כנ\"ל):\nבענין הא' כתב רש\"י \"הוא החמור שחבש אברהם לעקידת יצחק\", כי בזה בא לבאר שקיום ציווי ה' צ\"ל בלי חשבונות, כנ\"ל, ודבר זה מודגש בעיקר בזה שאברהם אבינו בעצמו חבש חמור לעקידת יצחק (כנ\"ל), שזה מורה על זריזותו ושמחתו לקיים ציווי השם (אהבה מקלקלת השורה<sup data-n=\"140\">27</sup>);\nובענין הב', שבו כוונתו להדגיש איך שהגאולה העתידה לבוא היא המשך ל­שליחות זו לגאול את בני ישראל מ­מצרים, לא מספיק לומר סתם \"שעתיד בן דוד לרכוב עליו\", כי לשון זו אין בה משמעות מיוחדת בקשר לגאולת ישראל, שהרי אפשר שבן דוד ירכוב עליו בכלל (לא בתור מושיעם של ישראל). דאף שגם זה מורה שהוא חמור מיוחד, שבן דוד רגיל לרכוב על חמור זה דוקא, מ\"מ אינו שייך לענין הגאולה דוקא;",[["139","26","וירא כב, ב."],["140","27","פרש\"י עה\"פ שם כב, ג."],["141","28","להעיר מהידוע שמשה הוא גואל ראשון הוא גואל אחרון (ראה שמו\"ר פ\"ב, ו. זח\"א רנג, א. שער הפסוקים פ' ויחי). וראה ביאורו — לקו\"ש חי\"א ע' 8 ואילך. סה\"ש תשנ\"ב ח\"א ע' 98 ואילך."],["124","13","פל\"א."],["140","27","פרש\"י עה\"פ שם כב, ג."]]],[1301470087,"ולכן מדייק רש\"י \"שעתיד מלך המשיח להגלות עליו\", היינו שהחמור שייך אליו (א) בתור \"מלך המשיח\" (ולא רק בתור \"בן דוד\"), ועוד זאת (ב) בקשר למעשה הגאולה, \"להגלות עליו\" (ולא רק בשביל \"לרכוב עליו\").\nו. ועוד יש לומר, שגם זה \"שעתיד מלך המשיח להגלות עליו\" שייך (לא רק לטענת משה שאין סופו להכניסם לארץ ולגואלם לעתיד, אלא) גם לטענתו ה­ראשונה (והעיקרית) שאינו רוצה ליטול גדולה כו' במקום אהרן אחיו הגדול ממנו (שבזה התחיל סירובו גם בתחלת דיבור ה' אליו<sup data-n=\"144\">29</sup>, \"מי אנכי כי אלך אל פרעה\").\nובהקדים דיוק לשון רש\"י שהעתיק מהכתוב \"עני ורוכב על חמור\", דלכ­אורה, אמאי העתיק רש\"י גם תיבה זו, דאם היתה כוונת רש\"י להעתיק חלק הכתוב המורה שקאי על מלך המשיח הו\"ל להעתיק הלשון שלפנ\"ז \"מלכך יבוא לך צדיק ונושע גו'\". ועכצ\"ל דאין כוונתו כ\"א רק לסמן הכתוב שבו מפורש שרוכב על החמור, וא\"כ למה דייק להביא גם התיבה \"עני ורוכב על חמור\", ובפרט שהוא בסתירה לכאורה למה שאומר \"מלך המשיח\".\nוהביאור: בפירוש הכתוב \"עני ורוכב על חמור\" פרש\"י \"עני — ענוותן\"<sup data-n=\"145\">30</sup>, \"ורו­כב על חמור — מדת ענוה היא\". והיינו מפני ששליחות מאת ה', אף שתוכן השליחות הוא להיות גואלם של ישראל, הרי זה תלוי דוקא בענין הענוה ותכלית הביטול שלו, שעי\"ז דוקא נמשכת ושורה עליו מלכותו של הקב\"ה, בלשון ה­כתוב<sup data-n=\"146\">31</sup> \"מרום וקדוש אשכון ואת דכא ושפל רוח\".\nובזה מרומז המענה למשה, שלא הי' רוצה ליטול גדולה כו', וטען \"מי אנכי\" — \"מה אני חשוב\"<sup data-n=\"144\">29</sup>: טענה זו מורה על ענוה שלו, וא\"כ אדרבה, דוקא זה הוצרך להיות אצל משה כדי להיות ראוי ל­שליחות זו, דזה שהקב\"ה בחר בו לגאול את ישראל, הוא דוקא מצד זה שהוא \"מי אנכי\" \"מה אני חשוב\".\nז. מיינה של תורה שבפרש\"י:\nע\"פ משנת\"ל נמצא שיש חילוק בין חמור דאברהם וחמור דמשה וחמור של מלך המשיח: בחמורו של אברהם נאמר שחבש אברהם את החמור; בחמורו של משה — \"וירכיבם על החמור\": ואילו בחמורו של משיח אומר רש\"י \"עתיד מלך המשיח להגלות עליו\" (אף שבקרא נאמר \"רוכב על חמור\").\nויש לומר, שחילוקי לשונות הנ\"ל הם בהתאם לג' שלבים ודרגות בהמשכת קדושה בעולם, בג' התקופות דאברהם משה ומלך המשיח.\nביאור הענין:\nמבואר במפרשים<sup data-n=\"148\">32</sup> ש\"חמור\" מרמז ומורה על \"חומר\" הגוף וחומריות העולם בכלל [וכידוע גם פירוש הבעש\"ט<sup data-n=\"149\">33</sup> על הפסוק<sup data-n=\"150\">34</sup> \"כי תראה חמור שונאך גו'\", דקאי על חומר הגוף]. וזהו כללות ה­קשר בין ענין הגאולה ל\"חמור\" דוקא [שלכן הן משה (גואל ראשון) והן מלך",[["144","29","ג, יא ובפרש\"י."],["145","30","וכ\"ה בתרגום עה\"פ."],["146","31","ישעי' נז, טו."],["144","29","ג, יא ובפרש\"י."],["148","32","ראה גו\"א כאן (ובס' גבורות ה' פכ\"ט). מנחה בלולה כאן. פנים יפות ועוד."],["149","33","\"היום יום\" כח שבט. כתר שם טוב בהוספות (הוצאת קה\"ת) סט\"ז. וש\"נ."],["150","34","משפטים כג, ה."]]],[1301470088,"המשיח (גואל אחרון)<sup data-n=\"151\">35</sup> יהיו רוכבים על חמור] — כי תוכנה הפנימי והעיקרי של הגאולה היא התגלות קדושתו ית', ש­בשביל זה צ\"ל שבירת וזיכוך ובירור החומר, הן חומר הגוף של איש ואשה ד­ישראל בפרט והן חומריות העולם ב­כלל, ובלשון רבינו הזקן (בעל ההילולא דכ\"ד טבת<sup data-n=\"152\">36</sup>) בספר התניא<sup data-n=\"153\">37</sup>, שתכלית בריאת העולם תהי' לימות המשיח, \"שאז יזדכך גשמיות הגוף והעולם ויוכלו ל­קבל גילוי אור ה'\".\nוהנה בפעולת האדם בבירור וזיכוך חומר הגוף, יש בכללות ג' אופנים:\nא) עיקר עבודתו של האדם היא ל­גלות את אור נשמתו שהיא בהעלם והסתר בחומר הגוף, כי \"עיר פרא אדם יולד\"<sup data-n=\"154\">38</sup>, ובטבעו הרי הוא הולך אחרי תאוות גופו, ועבודתו היא לפעול בעצמו שלא לנטות אחרי התאוות כו' אלא לעסוק בתורה ובמצות. ולפי אופן זה הרי העבודה היא בדרך כיבוש ושליטה, שהאדם שולט על גופו ונפשו הבהמית, ומכניע את חומר גופו באופן שחומר הגוף לא יעלים ויסתיר על אור נשמתו.\nב) למעלה מזה היא העבודה לזכך את חומר הגוף עצמו, שהגוף עצמו יהי' עובד ה', שזהו ע\"י שינוי מדותיו ה­טבעיים, שלא ירצה תאוות העולם כו'<sup data-n=\"155\">39</sup>.\nאלא שבבירור וזיכוך חומר הגוף עצמו — יש שני אופנים:\n(א) בירור וזיכוך הגוף הבא מצד אור הנשמה, דהיינו, שמסירותו לעניני קדו­שה היא בתוקף כזה, שריבוי אור ה­קדושה שבנשמה פועל גם על גופו להתברר ולהזדכך. שלפי אופן זה, הרי הקדושה שבאדם היא קדושת נשמתו, אלא שהגוף, להיותו מבורר ומזוכך, נעשה כלי לאור הנשמה.\n(ב) זיכוך הגוף מצד עצמו, והיינו שהאדם עובד עם גופו עד שהגוף מצד עצמו נהפך לחפצא של קדושה<sup data-n=\"156\">40</sup>.\nוכשם שהוא בעבודת כאו\"א בפרט — כן הוא בכללות חומריות העולם, שיש שלשה אופנים בבירור וזיכוך החומריות, שעי\"ז מתגלה קדושתו ית' בעולם:\nא) הכנעת וביטול גסות וחומריות ה­עולם המונעת השראת הקדושה, שביטול ושבירת החומריות נותן מקום שיהי' גילוי קדושה בעולם.\nב) שגשמיות העולם מתברר ומזדכך עד שנעשה כלי לגילוי אור הקדושה.\nג) תכלית השלימות בבירור וזיכוך",[["151","35","ראה לעיל הערה 28."],["152","36","ולהעיר דבשנה זו (תשמ\"ט) היא כהקביעות דשנת ההסתלקות תקע\"ג, \"מוצש\"ק דשמות כ\"ג אור לכ\"ד טבת כחצות שעה יא\" (ל' הצ\"צ — נדפס במענה לשון בתחלתו. ועוד)."],["153","37","פל\"ו (מו, ב)."],["154","38","איוב יא, יב."],["155","39","והחילוק הוא גם בדרך העבודה עם הגוף, שבאופן הא' יתכן שהאדם יעסוק בסיגופים ושבירת החומריות, משא\"כ באופן הב', וכתורת הבעש\"ט הנ\"ל \"לא בזו הדרך ישכון אור התורה כי אם עזוב תעזוב עמו לברר את הגוף ולזככו ולא לשברו בסיגופים\"."],["156","40","ויש לבאר ג' דרגות אלו בעבודת האדם: א) העבודה דתורה ומצוות, שבכללות היא העבודה בעניני קדושה, אלא שפועל שהגוף לא יבלבל לעבודתו בקיום התומ\"צ. ב) העבודה ד\"כל מעשיך יהיו לשם שמים\" (אבות פ\"ב מי\"ב. רמב\"ם הל' דעות ספ\"ג), שהוא עוסק ופועל בעניני הגוף (\"מעשיך\") שיהיו לשם שמים. ג) \"בכל דרכיך דעהו\" (משלי ג, ו. רמב\"ם שם), ש\"בדרכיך\" — עניני הגוף — עצמם יודע את הוי' (ולא רק שעושה אותם \"לשם שמים\") — ראה בארוכה לקו\"ש ח\"י ע' 103 ואילך. וראה גם לקו\"ש ח\"ט (ע' 63 ואילך. וש\"נ) ע\"ד ג' הענינים דתורה מצות ותשובה."]]],[1301470089,"העולם, שהגשמיות עצמה תתקדש, שזה יהי' לעתיד לבוא, כשיקויים היעוד<sup data-n=\"157\">41</sup> \"ונגלה כבוד ה' וראו כל בשר יחדיו כי פי ה' דבר\", היינו שזאת תהי' תכונת ה\"בשר\" לעתיד לבוא, שיזדכך עד שיהי' ביכולתו של הבשר (מצד עצמו) לראות \"כי פי ה' דבר\"<sup data-n=\"158\">42</sup>.\nח. וזהו ההפרש בין שלשת התקופות דאברהם משה ומשיח:\nבימי אברהם, כאשר \"לא ניתנה תורה עדיין. . עדיין לא נתברר ונזדכך חומ­ריות העולם\"<sup data-n=\"159\">43</sup>, פעולת אברהם היתה לבטל להכניע ולשבור חומריות העולם שלא יפריע לגילוי אור הקדושה.\nוזהו דיוק לשון רש\"י \"הוא החמור ש­חבש אברהם\"<sup data-n=\"160\">44</sup>, ש\"חבישת\" החמור מורה על הכנעת החומר<sup data-n=\"161\">45</sup>;\nבימי משה, לאחרי גמר וזיכוך ב\"כור הברזל\"<sup data-n=\"162\">46</sup> דגלות מצרים, \"שזיכך את ישראל על ידי קושי השעבוד בחומר ו­בלבנים. . וכאשר נזדככו ישראל נזדכך ג\"כ העולם וגשמיותו וחומריותו\"<sup data-n=\"163\">47</sup> — הגיע העולם למצב שגשמיותו תהי' כלי לאור הקדושה;\nוזהו שנאמר במשה \"וירכיבם על ה­חמור\", שהעבודה ד\"חבישת\" החמור כבר נעשית על ידי אברהם אבינו, וכבר אפשר להיות ה\"רכיבה\" על החמור, ש­אור הקדושה יומשך תוך חומריות העו­לם.\nאלא שאז הי' עדיין באופן ד\"וירכיבם על החמור\", היינו שאור הקדושה \"רוכב\" ומאיר על (ידי) החומריות, אבל גילוי אור הקדושה אינו מתייחס ל\"חמור\" עצ­מו, אלא להרוכב עליו.\nמשא\"כ זיכוך גשמיות וחומריות העו­לם לעתיד לבוא הוא באופן של \"עתיד מלך המשיח להגלות עליו\", שגילוי אור המשיח יהי' על ידי ה\"חמור\" עצמו, שה­חומר יזדכך כ\"כ עד שהוא עצמו יגלה את אור הקדושה בעולם.\nועפ\"ז יש לבאר הטעם הפנימי לעוד חילוק בין ג' חמורים דאברהם משה ומשיח: באברהם לא נאמר שהוא בעצמו רכב על החמור (ומשמע שהחמור נשא רק העצים והמאכלת ואילו הוא ויצחק (ושני נעריו) לא רכבו על החמור אלא הלכו ברגל); במשה נאמר שהרכיב את אשתו ובניו ולא נאמר שהוא בעצמו רכב עליו; ואילו אצל מלך המשיח מפורש \"ורוכב על חמור\".\nוע\"פ משנת\"ל יש לומר הטעם בזה<sup data-n=\"164\">48</sup>: בזמנו של אברהם, כש\"עדיין לא נתברר ונזדכך חומריות העולם\", לא הי' עדיין קשר בין אברהם עצמו (ויצחק), עם ה­\"חמור\"; אצל משה, כשכבר \"נזדכך. . העולם וגשמיותו וחומריותו\" באופן שהי' יכול להיות כלי לאור הקדושה, הרכיב את אשתו ובניו על החמור, אבל כיון שחומריות העולם מצד עצמה עדיין לא נתקדשה (ופעולת הזיכוך היא רק בכך",[["157","41","ישעי' מ, ה. וראה שער האמונה לאדמו\"ר האמצעי פכ\"ה."],["158","42","ראה לקו\"ש חי\"ז ע' 94. וש\"נ."],["159","43","תו\"א יתרו עד, א."],["160","44","אבל זה הי' חידוש של אברהם — ראה צרור המור וירא שם \"אמרו רז\"ל מיום שנברא העולם לא הי' אדם שחבש חמורו עד שבא אברהם\"."],["161","45","ע\"פ כהנ\"ל יומתק זה שלא הביא רש\"י \"הוא החמור בן האתון שנבראת בין השמשות\" (ראה לעיל ס\"ג), כי ההדגשה ברש\"י היא בעבודת ופעולת האדם בה\"חמור\", ולא ב\"חמור בן האתון שנבראת בין השמשות\", שהיא בריאה בידי שמים (והיינו שהוא חומר זך מעיקרא, למעלה מחומריות העולם)."],["162","46","לשון הכתוב ואתחנן ד, כ."],["163","47","תו\"א שם, ב."],["164","48","ראה בארוכה לקו\"ש ח\"א ע' 71 ואילך."]]],[1301470090,"שנעשה כלי לאור הקדושה שמאיר מלמעלה), לכן עדיין לא הי' \"קשר\" בין ה\"חמור\" למשה עצמו;\nודוקא לעתיד לבוא, כאשר חומריות העולם עצמה תגלה אור הקדושה, \"עתיד מלך המשיח להגלות עליו\", הרי מלך המשיח עצמו ירכוב עליו, כי אז תתגלה, ובאופן ד\"כמים לים מכסים\"<sup data-n=\"165\">49</sup>, איך ש­אמיתת המציאות של כל נברא הוא \"אמיתת המצאו\"<sup data-n=\"166\">50</sup> ית', ובלשון אדמו\"ר האמצעי<sup data-n=\"167\">51</sup>, שאז יתגלה ש\"יש הנברא\" הוא חד עם \"יש האמיתי\".\n<span data-k=\"q\">(משיחות ש\"פ שמות תשמ\"ז; י\"ט כסלו תשח\"י) </span>",[["165","49","ישעי' יא, ט. רמב\"ם סוף הל' מלכים."],["166","50","רמב\"ם ריש הל' יסוה\"ת."],["167","51","ביאוה\"ז בשלח מג, ג."]]],[1301470091,"<h3>שיחה א</h3>\nא. בתחילת פרשתנו מסופר אודות דברי ה' אל משה (במענה על טענתו (ב­ס\"פ שמות<sup data-n=\"168\">1</sup>) \"למה הרעות לעם הזה גו'\") — \"וידבר<sup data-n=\"169\">2</sup> אלקים אל משה ויאמר אליו אני ה', וארא אל אברהם אל יצחק ואל יעקב בא­ל שד­י ושמי ה' לא נודעתי להם. וגם הקימותי את בריתי אתם גו' ואזכור את בריתי. לכן אמור לבני ישר­אל אני ה' והוצאתי אתכם מתחת סבלות מצרים והצלתי אתכם גו' וגאלתי אתכם גו' ולקחתי אתכם גו' וידעתם כי אני ה' גו'\".\nומשמעות הדברים לפי פשוטם<sup data-n=\"170\">3</sup>, שלא ידאג משה ש\"והצל לא הצלת את עמך\"<sup data-n=\"171\">4</sup>, כי כעת הגיע זמן קיום הבטחת השם להאבות ויגאול את בני ישראל מארץ מצרים.\nאבל צריך ביאור מהו ענינה של ה­הקדמה הממעטת (לכאורה) בערך ההב­טחה אל האבות — ש\"וארא אל אברהם גו' בא­ל שד­י ושמי ה' לא נודעתי להם\"?\nבפרש\"י<sup data-n=\"172\">5</sup> מבואר שכוונת הכתוב שב­ימי האבות עדיין לא קיים ה' הבטחתו, וזהו \"ושמי ה' לא נודעתי להם\" — \"לא נכרתי להם במדת אמיתית שלי\" (כיון שלא קיים עדיין הבטחותיו), ועתה הגיע זמן קיום ההבטחה. אבל עיקר הקושי במקומו עומד: למאי נפק\"מ כאן זה שב­ימי האבות עדיין לא נתקיימה הבטחתו של הקב\"ה?\nועוד: כל דברי התורה הם (תורה לשון<sup data-n=\"173\">6</sup>) הוראה נצחית לכאו\"א מישראל עד סוף כל הדורות; ומהי ההוראה אלינו מהודעה זו ש\"שמי ה' לא נודעתי להם\"<sup data-n=\"174\">7</sup>?\nגם יש להבין דיוק הכתוב \"וארא אל אברהם אל יצחק ואל יעקב\", דלכאורה הו\"ל לקצר<sup data-n=\"175\">8</sup> \"וארא אל אבותיך\"<sup data-n=\"176\">9</sup> (ו­כיו\"ב)? וגם אם יש טעם שרוצה לפרט שמות שלשת האבות, הול\"ל<sup data-n=\"177\">10</sup> \"וארא אל אברהם יצחק ויעקב\", ומדוע מפסיק ביניהם בתיבת \"אל\"<sup data-n=\"178\">11</sup> (\"אל יצחק ואל יעקב\")?\nב. על הכתוב \"וידבר אלקים אל",[["168","1","ה, כב."],["169","2","ו, ב­ו."],["170","3","כפרש\"י עה\"פ."],["171","4","שמות שם, כג."],["172","5","עה\"פ."],["173","6","ראה זח\"ג נג, ב. גו\"א ר\"פ בראשית בשם הרד\"ק."],["174","7","במ\"א נת' (לקו\"ש ח\"ג ס\"ע 855 ואילך. חט\"ז ע' 52 ואילך. וראה גם לקו\"ש ח\"ו ע' 38 ואילך) ההוראה ע\"פ פי' חז\"ל (הובא גם ברש\"י כאן ו, ט), שכוונת הכתוב היא לבאר מעלת האבות על משה רבינו, שהם לא הרהרו אחר מדותיו של הקב\"ה.\nוהשאלה בפנים היא לפי פשטות לשון הכתוב, שמשמעה שבא להשמיענו רק זה ש\"שמי הוי' לא נודעתי להם\"."],["175","8","וכלשון רש\"י עה\"פ \"אל האבות\". — וכידוע השקו\"ט במפרשי רש\"י מה מוסיף רש\"י על המפורש בקרא. וראה לקו\"ש ח\"ג ע' 860. חט\"ז שם."],["176","9","ע\"ד שמות ג, יג. בא יג, ה. שם, יא. ובכ\"מ."],["177","10","כמו תיכף לאח\"ז (ו, ח) לתת אותה לאברהם ליצחק וליעקב. וראה שמות שם, טו­טז. ועד\"ז בכ\"מ."],["178","11","להעיר ממחז\"ל (מו\"ק כו, א) \"על על הפסיק הענין\"."]]],[1301470092,"משה ויאמר אליו אני ה'\" מבאר רבינו הזקן<sup data-n=\"179\">12</sup>, שיש בזה (לא רק נחמה והבטחה, אלא גם) תשובה ומענה על טענת משה \"למה הרעות לעם הזה\", כי בזה מדגיש שענינה של גאולת מצרים הוא — הת­גלות שם הוי', \"אני הוי'\", וכמפורש ב­המשך הכתובים \"לכן אמור לבני ישראל אני ה' גו' וידעתם כי אני ה' גו'\", וכדי לזכות לגילוי שם הוי', שהוא גילוי עליון ביותר, צריך להיות תחילה גלות קשה ביותר (\"הרעות\").\nומוסיף הכתוב שמטעם זה לא הי' גילוי זה בימי האבות, \"וארא אל אברהם גו' בא­ל שד­י ושמי ה' לא נודעתי להם\" — כי מעלה נפלאה בגילוי זה, שאפילו האבות לא זכו לו, \"ושמי ה' לא נודעתי להם\" [שהתגלות ה' אל האבות היתה רק ב\"א­ל שד­י\", שזהו כפי שהקב\"ה מצמצם את עצמו לפי ערך העולמות (כפירוש שם שד­י — \"שאמרתי לעולמי די\"<sup data-n=\"180\">13</sup>), ולא שם הוי', שזהו שם העצם<sup data-n=\"181\">14</sup> כפי ש­הוא למעלה מגדרי העולם, \"הי' הוה ויהי' ברגע אחד\"<sup data-n=\"182\">15</sup>] — ולכן צ\"ל בשביל זה הכנה מיוחדת של ירידה בגלות כו'.\nג. ועפ\"ז נמצא, שבדברי הקב\"ה ל­משה, \"וארא אל אברהם גו'\", מבואר יסוד ועיקר ענינה של גאולת מצרים. שלא זו בלבד שמהותה של גאולה זו (אינה גאולה גשמית בלבד, אלא ב­עיקרה) היא גאולה רוחנית ממצב של שעבוד למצרים למצב של חירות ועבו­דת השם (ובלשון הכתוב<sup data-n=\"183\">16</sup> \"בהוציאך את העם ממצרים תעבדון את האלקים על ההר הזה\", שתכליתה של יציאת מצרים היא עבודת האלקים בקבלת התורה ומצוותי'), אלא עוד זאת, שמטרת ותכ­לית גאולה רוחנית זו היא גילוי וידיעה בשם הוי'.\nועפ\"ז מובן בעומק יותר הטעם שה­כתוב מאריך כאן אודות האבות — \"וארא אל אברהם גו' בא­ל שד­י ושמי ה' לא נודעתי להם\", כי בזה מודגש, שמבלי הבט על גודל מעלת עבודת האבות, וכמאמר חז\"ל<sup data-n=\"184\">17</sup> \"האבות הן הן המרכבה\", עדיין אין זה מצב של \"גאו­לה\"; ויציאת מצרים קשורה בכך שישנה הידיעה ב\"שמי הוי'\" (שלא נודע לה­אבות<sup data-n=\"185\">18</sup>).\nומטעם זה מפרט הכתוב את כאו\"א מהאבות בפ\"ע (ולא נאמר בקיצור \"אל אבותיך\" וכיו\"ב), וגם מפסיק ביניהם ב­תיבת \"אל\" — להדגיש עוד יותר המעלה שבעבודת האבות.\nכלומר: זה שהם ה\"אבות\" של בנ\"י אינו מורה על המעלה המיוחדת שב­כאו\"א מהאבות בפ\"ע אלא על הצד­השווה שבהם. ועוד זאת: זה שהם היו ה\"אבות\" של בנ\"י הוא ענין הבא מל­מעלה (שהקב\"ה זיכה אותם, בשכר עבו­דתם, שהם יהיו האבות של כל בנ\"י<sup data-n=\"186\">19</sup>).",[["179","12","תו\"א פרשתנו נו, סע\"א ואילך (מאמרי אדה\"ז — פרשיות פרשתנו ע' רכו ואילך). וראה בארוכה תו\"ח פרשתנו (צא, ב ואילך). אוה\"ת שם (כרך ז ע' ב'תקמט ואילך). ועוד."],["180","13","חגיגה (יב, א) — הובא בתו\"א שם (נו, ג)."],["181","14","ובפרט ע\"פ המבואר (ראה אוה\"ת פרשתנו ע' קכו ואילך. כרך ז' שם. ובכ\"מ), שגילוי שם הוי' כאן הוא שם הוי' דלעילא (משא\"כ להאבות, אף ש­גם אצלם נזכר כמ\"פ שם הוי', נתגלה רק שם הוי' דלתתא). וזוהי כוונת רש\"י עה\"פ \"לא ניכרתי להם במדת אמתית שלי\"."],["182","15","ראה תניא שער היחוד והאמונה פ\"ז (פב, א), ע\"פ רע\"מ פינחס (רנז, סע\"ב)."],["183","16","שמות ג, יב. וראה רש\"י שם."],["184","17","ב\"ר פמ\"ז, ו. פפ\"ב, ו. רע\"מ פינחס (רנז, ב). וראה תניא פכ\"ג (כח, ב). שם רפל\"ד."],["185","18","ראה הערה 14."],["186","19","ראה תניא פי\"ח."]]],[1301470093,"אבל פירוטם של אברהם יצחק ויעקב בפ\"ע מדגיש את מעלתו המיוחדת של כאו\"א מהאבות [וכידוע<sup data-n=\"187\">20</sup> שעיקר עבודת אברהם היתה בקו דגמילות חסדים, ו­עבודת יצחק — \"עבודה\", ושל יעקב — לימוד התורה] — ומ\"מ, כיון שלא הי' להם הגילוי והידיעה ב\"שם הוי'\", \"שמי הוי' לא נודעתי להם\", אין זה מצב של גאולה (בשלימותה).\nד. ביאור הענין:\n\"מצרים\" הוא מלשון מיצרים וגבו­לים<sup data-n=\"188\">21</sup>, ותוכן זה שב\"מצרים\" ישנו גם ב­קדושה<sup data-n=\"189\">22</sup>, דכיון שהאדם הוא נברא בעל גבול, הרי גם כשעובד את ה' בכל כוחו­תיו, לא יצא עדיין ממיצריו והגבלותיו (אף שנמצא כולו בעולם של קדושה);\nוענינה של \"יציאת מצרים\" הוא ה­יציאה ממיצרים וגבולים, גם דקדושה, שהאדם הוא ב\"בחי' ביטול לגמרי\" עד \"שאינו מרגיש את עצמו כלל. . ואינו תופס מקום לעצמו כלל\"<sup data-n=\"190\">23</sup>, שביטול כזה אין ביכולתו של אדם לפעול בכח עצמו (ע\"ד אין<sup data-n=\"191\">24</sup> חבוש מתיר עצמו כו'), אלא בא על ידי התגלות ה' מלמעלה, ובזה גופא — גילוי שם הוי', היינו עצמותו של הקב\"ה כפי שהוא למעלה מגדרי העולם, שמפני עוצם גילוי זה מתבטל האדם מ­מציאותו, וזה מגבי' אותו למעלה ממיצ­רים וגבולים, אפילו \"מצרים\" דקדושה.\n[משא\"כ אצל האבות, ש\"שמי ה' לא נודעתי להם\", לא הי' \"יציאת מצרים\", היציאה (בשלימות) ממיצרים וגבולים].\nה. וזוהי גם ההוראה הנצחית לכאו\"א מישראל — גם בזמן הגלות:\nידוע<sup data-n=\"192\">25</sup> שכאו\"א בפרט יכול להגיע ל­מצב של גאולה ופדי' בעבודתו הרוח­נית, אף קודם גאולת כלל ישראל (שאז תהי' גאולה שלימה ופדי' גם בגשמיות כפשוטה).\nובזה יתכן, שהאדם יקשה לו להבחין אם הוא נמצא במצב של \"גלות\" או כבר זכה למצב של \"גאולה\". דאפשר שיעלה בדעתו, שאם גבר על יצרו והריהו מסור ונתון ללימוד התורה וקיום המצוות, וגם דברי הרשות שלו עושה \"לשם שמים\", הרי ודאי שכבר זכה ל\"פדי'\" וגאולה רוחנית.\nובזה משמיענו הכתוב — \"וארא אל אברהם גו' ושמי הוי' לא נודעתי להם\", דאפשר להיות עובד ה', עד לדרגא של \"מרכבה\", ועוד זאת, שעובד את ה' בכל אחד ואחד מג' העמודים דתורה עבודה וגמילות חסדים, וכל אחד מהם הוא בשלימות אצלו — ומ\"מ, כל זמן שאינו מאיר אצלו שם הוי' שלמעלה מן הטבע, עדיין לא יצא ממצרים, ואין זה מצב של גאולה.\nו. ובמה יודע איפוא אם אכן כבר זכה לגילוי שם הוי' בנפשו? הנה ע\"ז בא הפירוש בפרש\"י \"ושמי ה' לא נודעתי להם\" — \"לא נכרתי להם במדת אמתית שלי שעלי' נקרא שמי ה'\", שאי הגילוי דשם הוי' אצל האבות הוא \"שלא נכרתי להם במדת אמתית שלי\"<sup data-n=\"193\">26</sup>:\nמהותה של מדת האמת היא — העדר",[["187","20","זהר (ס\"ת) ר\"פ ויצא."],["188","21","תו\"א יתרו עא, ג. ובכ\"מ."],["189","22","ראה תו\"א שמות (מט, סע\"ד ואילך). פרשתנו (נז, ב ואילך). יתרו שם. ובכ\"מ."],["190","23","לשון התו\"א פרשתנו שם (נו, א)."],["191","24","ברכות ה, ב. וש\"נ."],["192","25","ראה תניא אגה\"ק ס\"ד."],["193","26","ראה גם פנים יפות ריש פרשתנו (הובא באוה\"ת פרשתנו ריש ע' קצד)."]]],[1301470094,"השינוי. וכדאיתא בירושלמי<sup data-n=\"194\">27</sup> ש\"חותמו של הקב\"ה אמת\"<sup data-n=\"195\">28</sup> שבג' האותיות א'מ'ת', הנה הא' ראשונה שבאותיות, מ' — אמצעיתן, ות' — אחרונה שבאותיות, כמ\"ש<sup data-n=\"196\">29</sup> \"אני ראשון ואני אחרון ומבלעדי אין אלקים\", והיינו, שענינה של \"אמת\" הוא, שנמצא בכל מקום — בתחילה אמצע וסוף — בשווה ובלי שינוי, וכ­מ\"ש<sup data-n=\"197\">30</sup> \"אני ה' לא שניתי\" (וזהו הפירוש \"אין אלקים\", שאין שום העלם והסתר<sup data-n=\"198\">31</sup> מצד שם אלקים, מדת הדין והצמצום).\nוזוהי הבחינה אם הגיע האדם למצב של יציאה אמתית מכל מיצרים וגבולים — כאשר עבודתו היא למעלה משינויים. כלומר, שלא משנה כלל באיזה ענין הוא עסוק: בלימוד התורה, בעבודת התפלה, בעשיית מצוות, או בעשיית דברי רשות שלו לשם שמים — שבכל דבר ודבר עבודתו היא מתוך אותו ביטול המוחלט לרצונו ית', בלי שינוי.\nשהכח לזה הוא ע\"י שמאיר אצלו שם הוי', \"מדת אמתית שלי\" (\"אני ראשון ואני אחרון ומבלעדי אין אלקים\"), שזה פועל אצל האדם ביטול כזה, שאינו נתפס ומוגבל בפרטי ציורי העבודה, אלא בכולם מאירה אצלו נקודת הביטול להקב\"ה, למעלה מהגבלה ושינוי.\n[וע\"ד תורת הבעש\"ט<sup data-n=\"199\">32</sup> עה\"פ<sup data-n=\"200\">33</sup> \"שויתי ה' לנגדי תמיד\" — \"שויתי לשון השתוות\", ש\"הכל שוה אצלו\" ועובד את ה' \"בכל כחו\" ו\"בכל האופנים\"<sup data-n=\"201\">34</sup> — ש­\"השתוות\" זו אצל האדם באה מזה ש\"הוי' (הוא) לנגדי תמיד\", דכאשר שם הוי' מאיר אצל האדם באופן גלוי, ה\"ז פועל \"השתוות\" בכל עניניו].\nז. כשם שהוא בנוגע לגאולת מצרים — כך הוא בנוגע לגאולה העתידה לבוא, שתוכן ענין הגאולה אינו רק גאולה גשמית, וגם לא גאולה רוחנית סתם (גאולה מהיצר הרע), אלא — גילוי שם הוי'.\nוזהו גם עומק כוונת הרמב\"ם בסיום ספרו, בתיאור מצב העולם \"באותו הזמן\" — ש\"לא יהי' עסק כל העולם אלא לדעת את ה' בלבד ולפיכך יהיו ישראל חכמים גדולים ויודעים דברים הסתומים וישיגו דעת בוראם כפי כח האדם שנאמר<sup data-n=\"202\">35</sup> כי מלאה הארץ דעה את ה' כמים לים מכסים\":\nבתחילת<sup data-n=\"203\">36</sup> ספר היד, כשמבאר ה­רמב\"ם המצוה דידיעת ה', לא הזכיר שם הוי' בפירוש<sup data-n=\"204\">37</sup> וכתב רק \"לידע שיש שם מצוי ראשון\"<sup data-n=\"205\">38</sup>, ואילו כאן מדגיש ה­רמב\"ם \"לדעת את ה'\", וכן הביא הכתוב \"מלאה הארץ דעה את ה'\", והיינו מפני שאז תהי' הידיעה בשם הוי', ובזה גופא —",[["194","27","סנהדרין פ\"א ה\"א. וכן ב\"ר פפ\"א, ב. דב\"ר פ\"א, י. שהש\"ר פ\"א, ט (א). וראה רש\"י שבת נה, א."],["195","28","שבת שם. וש\"נ. מקומות שבהערה הקודמת."],["196","29","ישעי' מד, ו — הובא במדרשים (ורש\"י) שבהערה 27. ובירושלמי שם הובא פסוק אחר."],["197","30","מלאכי ג, ו."],["198","31","לקו\"ת ר\"פ מטות. ובכ\"מ."],["199","32","צוואת הריב\"ש בתחלתה (ס\"ב)."],["200","33","תהלים טז, ח."],["201","34","צוואת הריב\"ש שם ס\"ג [וכמשנ\"ת במ\"א שפיסקא זו באה בהמשך לפיסקא הקודמת, ואולי צ\"ל \"וכן\" במקום \"וכל\", כבכתר שם טוב (קה\"ת — סר\"כ) ואו\"ת להה\"מ (קה\"ת — סז, א)]."],["202","35","ישעי' יא, ט."],["203","36","בהבא לקמן ראה גם \"הדרן על הרמב\"ם\" (ס' השיחות תשמ\"ח ח\"א ע' 8­207, ע' 215 ואילך)."],["204","37","כ\"א רק בר\"ת — \"יסוד היסודות ועמוד החכמות\"."],["205","38","ורק בהמשך הענין (ה\"ד וה\"ו) מביא כתובים שבהם נזכר שם הוי'."]]],[1301470095,"מדריגה הכי עליונה שבו (בלשון הקבלה והחסידות \"הוי' דלעילא\"<sup data-n=\"185\">18</sup>), ה­פועלת תכלית הביטול לגמרי.\nוזהו מה שמסיים הרמב\"ם \"(כי מלאה הארץ דעה את ה') כמים לים מכסים\", שגילוי שם הוי' יפעול שלא תראה מצי­אות הארץ כלל, כי תהי' בטילה לגמרי בעוצם הגילוי, עד שתהי' מכוסה ב\"דעה את ה' — כמים לים מכסים\".\n<span data-k=\"q\">(משיחת ש\"פ וארא תשכ\"א)</span>",[["185","18","ראה הערה 14."]]],[1301470096,"<h3>שיחה ב</h3>\nא. בתחילת פרשת מכת דם<sup data-n=\"207\">1</sup> \"ויאמר ה' אל משה כבד לב פרעה מאן לשלח העם\" — מעתיק רש\"י תיבת \"כבד\" ו­מפרש: תרגומו יקיר, ולא אתיקר מפני שהוא שם דבר כמו כי<sup data-n=\"208\">2</sup> כבד ממך הדבר.\nוהטעם שהוצרך רש\"י לשלול את ה­פירוש \"אתיקר\" (פועל עבר — \"שכבר נהי'. . כבד\"<sup data-n=\"209\">3</sup>), ולא הסתפק (כדרכו) לו­מר רק התרגום הנכון \"יקיר\", אינו כדי לקבוע את הגירסא הנכונה בתרגום<sup data-n=\"210\">4</sup> — כי פשוט שאין זה ענינו של פירוש רש\"י עה\"ת לברר ולקבוע גירסאות בתרגום<sup data-n=\"211\">5</sup> — אלא מפני שיש קס\"ד<sup data-n=\"212\">6</sup> בפשוטו של מקרא לפרש ש\"כבד\" כאן הוא פועל עבר.\nוההסברה בזה: בפסוק שלפנ\"ז<sup data-n=\"213\">7</sup> נאמר \"ויחזק לב פרעה\", שתרגומו<sup data-n=\"214\">8</sup> \"ואיתקף\" (כמו \"אתיקיר\"), ולכן הי' מקום לפרש (כמו שתרגמו ופירשו התיב\"ע, הרשב\"ם והאבן עזרא) דמה שנאמר בפסוק לאח\"ז \"כבד לב פרעה\" הוא ג\"כ באותו הדרך (כמו \"ויחזק\") והיינו — \"אתיקר\", פועל עבר. ומשום הכי הוצרך רש\"י לשלול פירוש זה — \"תרגומו יקיר ולא אתיקר (והטעם) מפני שהוא שם דבר כמו כי כבד ממך הדבר\".\nאבל הא גופא טעמא בעי — בלשון הרא\"ם: מי הגיד לו למתרגם שהוא שם ולא פועל עבר. . אם מפני שנמצא כי כבד ממך הדבר שהוא שם הנה מצאנו ג\"כ נער וזקן שהוא שם ועכ\"ז בא ויהי כי זקן יצחק<sup data-n=\"215\">9</sup> פועל עבר<sup data-n=\"216\">10</sup>. . ועוד ש­מלת \"מאן\" הבא תיכף אחריו שהוא פועל עבר מכריח להיות \"כבד\" פועל עבר. . כי \"מאן\" שהוא פועל עבר מורה שכבר נהי' לבו כבד מזמן שעבר.\nובגו\"א מבאר, \"ומה שהכריח את ה­תרגום לפרשו שם דבר ולא פועל עבר שאין לומר שכבד לב פרעה כבר מאן לשלח העם ולכך לך אל פרעה דשמא אע\"ג שכבר הי' חזק לב פרעה עתה אינו חזק\".\nאבל בלבוש האורה דוחה פירוש ה­גו\"א (ומקיים קושיית הרא\"ם) — כי בה' המכות הראשונות רצה הקב\"ה להודיע",[["207","1","פרשתנו ז, יד."],["208","2","יתרו יח, יח."],["209","3","ל' הרא\"ם (הובא לקמן בפנים). ובגו\"א \"פירושו נעשה כבר\"."],["210","4","אונקלוס. וראה נתינה לגר כאן שכ' ש­\"בתרגומים שלנו נמצא אתיקר, אבל בכ\"י מצאתי יקיר כו'\"<sup data-n=\"e7\">*</sup>."],["211","5","להעיר שבכמה כת\"י רש\"י (שתח\"י) \"כתרגומו (לא \"תרגומו\") יקיר כו'\". ואכ\"מ."],["212","6","ובפרט את\"ל שכוונת רש\"י כאן ב\"תרגומו\" אינה לת\"א, אלא שכן הוא התרגום הנכון של תיבה זו (וכמשנ\"ת במק\"א בנוגע ללשון \"תרגומו\" וכיו\"ב בפרש\"י עה\"ת — ראה שיחת ש\"פ האזינו תשמ\"ו). וראה בהערה שלפנ\"ז שיש גירסא בפרש\"י \"כתר­גומו\"."],["213","7","ז, יג."],["214","8","בת\"א ובתיב\"ע."],["215","9","תולדות כז, א."],["216","10","וכן הביא בראב\"ע (וראה גם רשב\"ם) כאן."],["e7","*","בנתינה לגר שם, שמ\"ש ברש\"י \"שם דבר\" הוא ט\"ס, וצ\"ל שהוא שם או תואר. אבל בכל הדפוסים וכת\"י רש\"י שתח\"י (וכן במפרשי רש\"י) איתא \"שם דבר\"."]]],[1301470097,"שפרעה לא יתן לב לשוב באמת, וזהו ש\"אמר לו השי\"ת למשה הנה כבר ראית שהי' כבד לב פרעה ומאן לשלח את העם מפני שכבר חזק לבו לפיכך כדי שלא יאמרו הבריות אע\"פ שכבר הי' חזק לבו שמא עכשיו הרך לבבו ויעשה תשובה וישלח לפיכך אינני רוצה להביא עליו מכת הדם בלא התראה אלא לך אל פרעה וגו' והתרה בו ואם עכשיו ירך לבבו ודאי יאמר אשלח את העם ולא אצטרך להביא עליו מכת הדם ואם עודנו חזק לבו איהו דאפסיד אנפשי' וידעו הכל שעודנו מתריס כנגדי ומן הדין אביא עליו מכת הדם\".\nולפ\"ז נשארת (כנ\"ל) קושיית הרא\"ם: מהו ההכרח לפרש \"כבד\" לשון \"שם דבר\", ובפרט שאין זה מתאים עם המשך הכתוב \"מאן גו'\" שהוא פועל עבר<sup data-n=\"217\">11</sup>?\nועכצ\"ל שזה שרש\"י מפרש ומכריח גירסת התרגום \"יקיר. . מפני שהוא שם דבר\" אינו מיוסד (רק) על ההוכחה מהכתוב \"כי כבד ממך הדבר\", כ\"א מצד המשך הפרשה גופא; אלא שהוא רק מסתייע לפירושו זה (ש\"כבד\" הוא שם דבר) ממש\"נ \"כי כבד ממך הדבר\".\nב. ויש לומר, שכוונת רש\"י כאן היא לתרץ שאלה כללית, לכאורה, בכתוב זה:\nבתחילה מסופר, שהקב\"ה אמר למשה \"כבד לב פרעה מאן לשלח העם\", ואח\"כ בפסוקים שלאח\"ז<sup data-n=\"218\">12</sup> ממשיך הכתוב ל­ספר שאמר לו הקב\"ה \"לך אל פרעה גו' ואמרת אליו ה'. . שלחני אליך לאמר שלח את עמי ויעבדוני. . לא שמעת עד כה. . בזאת תדע כי אני ה' הנה אנכי מכה גו' על המים גו' ונהפכו לדם\". והיינו שבכללות הדברים האלו ישנם שני ענינים: (א) הודעה למשה — \"כבד לב פרעה גו'\", (ב) דברי שליחותו ל­פרעה — \"לך אל פרעה. . ואמרת אליו גו'\".\nוהרי בזה שונה הודעה זו מההודעות של שאר המכות, שבכולן התחיל הקב\"ה דבריו למשה מיד בדברי השליחות ל­פרעה\n[מלבד במכת ארבה, שגם שם היתה הודעה מיוחדת כהקדמה לדברי השלי­חות \"בא<sup data-n=\"219\">13</sup> אל פרעה כי אני הכבדתי את לבו גו' למען שתי אותותי אלה בקרבו ולמען תספר גו' את אשר התעללתי במצרים גו'\" (וכמשנ\"ת במק\"א<sup data-n=\"220\">14</sup> טעם הו­דעה זו, שבזה הסביר הטעם שמצווה את משה להתרות את פרעה (כדיוק לשון רש\"י \"בא אל פרעה, והתרה בו\") אע\"פ ש\"אני הכבדתי את לבו גו'\", שזהו \"למען תספר גו' את אשר התעללתי במצרים\", כפרש\"י \"שחקתי\", שעושה שחוק מפרעה כאילו יש לו בחירה לשמוע או לא)].\nומזה גופא שהודעה זו ד\"כבד לב פרעה מאן לשלח העם\" נאמרה למשה רק כהקדמה לשליחותו לפרעה (ולא כחלק מהדברים שעליו לאומרם ל­פרעה<sup data-n=\"221\">15</sup>) מוכח, שדבר זה אינו (רק) ענין שצריך למסור לפרעה, אלא שזהו נוגע (גם) לידיעתו של משה עצמו, וגם, שכן הוא באמיתתו של דבר, שהטעם שבאה מכת דם על פרעה הוא מפני ש\"כבד לב פרעה מאן לשלח העם\".",[["217","11","וראה באר יצחק כאן, שתירץ קושיית ה­רא\"ם (וגם הקושיא מתיבת \"מאן\")."],["218","12","ז, טו ואילך."],["219","13","ר\"פ בא."],["220","14","לקו\"ש ח\"ו ע' 60 ואילך."],["221","15","וע\"ד לקמן ט, יז. ולהעיר מפרש\"י ז, טז (מ\"מדרשו\") בנוגע לעניננו — מכת דם."]]],[1301470098,"ותמוה: לעיל<sup data-n=\"222\">16</sup>, בסיפור שילוח משה לפרעה נאמר, שהקב\"ה אמר למשה \"ואני אקשה את לב פרעה גו' ולא ישמע אליכם פרעה\". ומזה מובן, דכאשר ראה משה (לאחרי האות דבליעת מטה אהרן) כי \"ויחזק לב פרעה ולא שמע אליהם\", בודאי חשב שזהו מפני שהקב\"ה קיים הבטחתו והקשה את לבו. וכיון שכן, איך אפ\"ל ש\"כבד לב פרעה\" היא הסיבה להעונש דמכת דם — הרי הקב\"ה הוא שהכביד את לבו<sup data-n=\"223\">17</sup>?\nזה שמשה נצטווה למסור כן לפרעה ולהגיד לו שהוא נענש משום ש\"לא שמעת עד כה\" — מובן, כי הקב\"ה רצה שפרעה סו\"ס ישלח את בנ\"י ברצונו ע\"י דיבור אחר דיבור.\n[וכן אין להקשות — איך יתכן באמת שיגיע עונש לפרעה על העדר רצונו לשלח את בנ\"י מארצו, מאחר שהסיבה לזה היתה (לא רצונו של פרעה, אלא) מה שהקב\"ה חיזק את לבו — כי קושיא זו כבר תירצה רש\"י לעיל עה\"פ<sup data-n=\"224\">18</sup> \"ואני אקשה\", וז\"ל \"מאחר שהרשיע והתריס כנגדי וגלוי לפני שאין נחת רוח באומות עו\"א לתת לב שלם לשוב טוב לי שית­קשה לבו למען הרבות בו אותותי ותכי­רו את גבורתי\". והיינו, שזה שהקב\"ה הקשה את לבו הי' עונש על \"שהרשיע והתריס כנגדי\"<sup data-n=\"225\">19</sup>].\nאבל מזה שהודעה זו היתה גם למשה עצמו, כנ\"ל, עכצ\"ל שגם עליו לדעת (ו­שכן היא אמיתית הדבר) — דמכיון ש­\"כבד לב פרעה\" לכן מגיע לו באמת עונש. ותמוה, כנ\"ל, כיצד מתאים זה עם דברי הקב\"ה אליו לפנ\"ז \"ואני אקשה את לב פרעה גו'\"?\nג. לכאורה אפשר לתרץ ע\"פ פרש\"י עה\"פ<sup data-n=\"224\">18</sup> \"ואני אקשה\" — \"ואעפ\"כ בחמש מכות הראשונות לא נאמר ויחזק ה' את לב פרעה אלא ויחזק לב פרעה\", שמ­שטחיות הלשון משמע שבה' המכות ה­ראשונות לא חיזק ה' את לב פרעה מלך מצרים, אלא הוא חיזק את עצמו<sup data-n=\"227\">20</sup>.\nאבל כד דייקת שפיר אא\"פ לתרץ כן, כי בפירש\"י נאמר רק ש(בכתוב) \"לא נאמר ויחזק ה' את לב פרעה\"; אבל ב­דברי הקב\"ה למשה לא מצינו שיודיעו שבחמש המכות הראשונות לא יקשה את לבו (כ\"א רק בחמש המכות האחרונות).\nובפרט את\"ל כפי' המפרשים<sup data-n=\"228\">21</sup>, שגם בחמש המכות הראשונות הקשה ה' את לב פרעה, אלא שבכתוב לא נאמר \"ו­יחזק ה' את לב פרעה\", כ\"א \"ויחזק לב פרעה\" [כדיוק לשון רש\"י \"ואף על פי כן בחמש מכות הראשונות לא נאמר ויחזק ה' את לב פרעה אלא ויחזק לב פרעה\" — ולא כתב בל' פשוטה \"בחמש מכות הראשונות לא חיזק ה' את לב פרעה\" (וכיו\"ב)]<sup data-n=\"229\">22</sup>.",[["222","16","ז, ג­ד."],["223","17","ומה שפרש\"י (ז, ג) \"ואעפ\"כ כו'\" — ראה לקמן סעיף ג."],["224","18","שם, ג."],["225","19","ראה בארוכה רמב\"ן שם. מפרשי רש\"י עה\"פ שם. של\"ה פרשתנו (שי, ב). לקו\"ש ח\"ו שם."],["224","18","שם, ג."],["227","20","כבשמו\"ר פי\"ג, ג — הובא ברמב\"ן שם (ע\"ש). וראה בארוכה מפרשי רש\"י שם."],["228","21","נחלת יעקב על פרש\"י כאן."],["229","22","ולכאורה כן משמע מזה שמפורש בכו\"כ מהאותות והמכות — החל מבליעת מטה אהרן (ז, יג. שם, כב. ח, יא. טו) — \"ויחזק לב פרעה ולא שמע אליהם כאשר דבר ה'\" (וכיו\"ב), שהכוונה בזה (כמפורש בפרש\"י במכת צפרדע ומכת כנים — ח, יא. טו) להכתוב \"ולא ישמע אליכם פרעה\" שבא בהמשך ל\"ואני אקשה את לב פרעה\", והרי פשטות משמעות הכתוב היא דזה ש\"לא ישמע אליכם פרעה\" הוא מפני ש\"ואני אקשה גו'\"."]]],[1301470099,"וכמבואר במפרשים<sup data-n=\"228\">21</sup>, \"דבחמש מכות הראשונות סיבב הקב\"ה פעולות שנתחזק לבו כמו. . במכת דם שאמרו ע\"י מכש­פות אתם עושים כן. . וזהו ויחזק לב פרעה, אבל ויחזק ה' היינו שהקב\"ה חז­קו בפירוש ולא ע\"י פעולות וסיבות\"<sup data-n=\"231\">23</sup>.\nוהדרא קושיא לדוכתא — מאחר ששמע משה \"ואני אקשה את לב פרעה גו'\", איך יתכן בהתאם לזה להודיעו ש\"כבד לב פרעה\" הוא טעם העונש דמכת דם?\nד. ולתרץ שאלה זו מפרש רש\"י \"כבד\" — \"תרגומו יקיר ולא אתיקר, מפני שהוא שם דבר\" — שבזה מתכוון רש\"י להדגיש ברור, שכוונת הקב\"ה ב\"כבד לב פרעה\" להודיעו, שאין זה (רק) משום שהוא ית' חיזק את לבו (שאז אין מקום להביא זה כסיבה לעונשו של פרעה), אלא למצבו של לב פרעה מצד עצמו, דזה ש\"מאן לשלח העם\" לא הי' (רק) מפני שהקב\"ה חיזק את לבו, אלא ש(גם) הוא מצד עצמו הכביד את לבו שלא לשלח את בנ\"י, ולכן ראוי הוא להענש ע\"ז.\n[וע\"ד התי' בספרים על הקושיא<sup data-n=\"232\">24</sup> — איך העניש הקב\"ה המצריים על שהעבי­דו את בנ\"י בפרך, והרי הקב\"ה גזר עליהם \"ועבדום וענו אותם\"<sup data-n=\"233\">25</sup>? — דזה שהמצריים העבידו כו' ועינו את בנ\"י לא הי' כדי לקיים גזירת הקב\"ה, אלא מפני רשעות לבם, ולכן נענשו על כך<sup data-n=\"234\">26</sup>].\nולכן פרש\"י ש\"כבד\" פירושו \"יקיר ולא אתיקר\" — כי עי\"ז ברור יותר שה­כוונה לכובד לב של פרעה מצד עצמו: אם הכוונה בלשון \"כבד\" היא \"פועל עבר\", היינו שהיתה כאן פעולת הכבדה, אין הדגשה שפרעה מצד עצמו הכביד את לבו, אדרבה — בפשטות צ\"ל שקאי על פעולת ההכבדה שהיא מעשה הקב\"ה המפורש לעיל בדברי הקב\"ה למשה \"ואני אקשה גו'\" (ושוב אין מקום לומר שענין זה יהי' הקדמה וטעם לעונש פרעה); ולכן פרש\"י ש\"כבד\" פירושו \"יקיר ולא אתיקר\", \"שם דבר\" המתאר המצב של לב פרעה — שלפ\"ז מסתבר לומר שהכוונה שלבו של פרעה הי' (בעצם) במצב של \"כבד\", שהי' לו לב כבד בעצם, ולכן מגיע לו עונש על שלא שילח את בנ\"י, כנ\"ל.\nה. מיינה של תורה בפרש\"י:\nכבדות<sup data-n=\"235\">27</sup> הלב בפשטות ענינה — עק­שות הלב, שאינו מתפעל משום דבר, וגם כששכלו מורה לו שצריך להתנהג ב­אופן הפכי, וגם הרגש שבלבו נוטה לצד אחר — הרי הוא מתעקש שלא לשנות את הנהגתו. וזהו ענינה של \"קליפת\" פרעה — פרעה אותיות הערף<sup data-n=\"236\">28</sup>, המורה על עקשות, \"קשה עורף\".\nועפ\"ז יש לבאר עומק כוונת המד­",[["228","21","נחלת יעקב על פרש\"י כאן."],["231","23","אבל בשאר מפרשי רש\"י לא פירשו כן ברש\"י. — במשכיל לדוד דוחה פי' הנחלת יעקב ממדרש הנ\"ל (הערה 20) שמפורש שבחמש מכות הראשונות לא הכביד ה' את לבו. אבל כבר נת' כמ\"פ שאא\"פ להכריח הפי' בפרש\"י עה\"ת ע\"פ מ\"ש במדרשי רז\"ל, ובפרט במקום שפשטות לשון רש\"י לא משמע כן."],["232","24","ראה רמב\"ם וראב\"ד הל' תשובה ספ\"ו."],["233","25","לך טו, יג."],["234","26","ראה רמב\"ן ובחיי לך שם. תוי\"ט אבות פ\"ב מ\"ו בסופה. ועוד. וראה לקו\"ש חכ\"ז ע' 153 ואילך."],["235","27","בכל הבא לקמן ראה אוה\"ת בא ע' רמו ואילך. שם (כרך ח) ע' ב'תתקב."],["236","28","ל\"ת ושער הפסוקים להאריז\"ל פ' וישב (מ, א). ל\"ת ר\"פ שמות. ובכ\"מ."]]],[1301470100,"רש<sup data-n=\"237\">29</sup>, שפירש \"כבד (לב פרעה)\" — שלבו של פרעה נעשה כ(חלק הגוף שנקרא) כבד, \"מה<sup data-n=\"238\">30</sup> הכבד כועס אף לבו של זה נעשה כבד\"<sup data-n=\"239\">31</sup>: ידוע שיש שלשה שליטים בגוף<sup data-n=\"240\">32</sup>, מוח ולב וכבד, כנגד ג' חלקי (כחות) הנפש — השכל (במוח), מדות (בלב), ומעשה (בכבד). וזוהי השייכות בין כבדות הלב ל\"כבד\" שבגוף — כי ענין העקשות שייך לכח המעשה של האדם (שזוהי בשליטת ה\"כבד\"), דגם כאשר אין לו שום הסברה (בשכל שב­ראש) ושום רגש (במדות שבלב) — הרי הוא עושה כן רק מחמת עקשות שלו.\nובזה מוסיף רש\"י — \"כבד. . יקיר ולא אתיקר\" — כי העקשות גופא יכולה להיות בשני אופנים: (א) ההנהגה באופן של עקשות, עקשות בפועל — \"אתיקר\" (לשון פועל); (ב) הנהגה זו חודרת בכל מציאותו, עד שנעשה אדם עקש בעצם וזהו שם התואר שלו — \"יקיר\". כלומר: אין זה רק ענין של הנהגה של עקשות, אלא שמקור הכבדות שבנפש הוא ב­גילוי אצלו, ובדרך ממילא כל ענין — אצלו הוא באופן של עקשות. וכן הי' אצל פרעה, שאין הפירוש שהי' צריך להתגבר על עצמו כדי להתעקש כנגד הקב\"ה, אלא הוא הי' \"כבד\" (עקשן) בעצם.\nו. והנה המכות שהביא הקב\"ה על פרעה כוונתן הפנימית היתה לשבור את קליפת פרעה<sup data-n=\"241\">33</sup>, וזה נעשה על ידי משה רבינו דוקא, וכמו שנאמר<sup data-n=\"242\">34</sup> \"ראה נתתיך אלקים לפרעה\", ופרש\"י \"שופט ורודה לרדותו במכות ויסורין\".\nאבל ידוע, שכדי לבטל מדה רעה וכיו\"ב ה\"ז \"במינה ודוגמתה\"<sup data-n=\"243\">35</sup> — במדה דוגמתה בצד הקדושה. כי זה לעומת זה עשה האלקים<sup data-n=\"244\">36</sup>, שכל מדה רעה היא \"לעומת\" מדה דוגמתה בצד הקדושה. וכן הוא בענין ה\"כבד\", שלעומת ה\"כבד\" דקליפה, ישנו \"כבד\" דקדושה, שהו\"ע קבלת עול מלכות שמים שלמעלה מטעם ודעת ורגש. דבעבודה שע\"פ טעם ודעת, וכן ע\"פ מדות שבלב, ישנם שינויים מזמן לזמן, כנראה בחוש שהאדם אינו עומד תמיד באותה הדרגא בהשגה, ופשיטא לא בהרגש לבו באהבת ה' ויראתו; משא\"כ העבודה דקבלת עול, \"כבד\" ד­קדושה, שהיא באופן של עקשות (כב­דות), הוא \"רחוק מהשינויים\"<sup data-n=\"245\">37</sup>.\nומזה מובן בעניננו, שכדי שמשה רבינו יוכל \"לרדות\" ולשבור את קליפת פרעה, הי' צריך לעורר בנפשו \"כבד\" דקדושה.\nויש לומר, שזהו הרמז והפירוש ה­פנימי בדברי רש\"י כאן \"כבד — תרגומו יקיר ולא אתיקר\": \"תרגומו\" של \"כבד\" פרעה, כלומר, ענין ה\"כבד\" כפי שנת­פרש בקדושה, ענינו — \"יקיר\", והו\"ע ה­",[["237","29","שמו\"ר פ\"ט, ח. וראה המשך תער\"ב ח\"א ס\"ע תקה."],["238","30","ובמדרש לקח טוב פרשתנו עה\"פ: כבד לב פרעה, כלומר לבו של פרעה נהפך לכבד כשם שהכבד אין בו בינה להבין ולהשכיל כך אין בינה בלבו להבין ולהשכיל ע\"כ נכבד לבו ונתחזק לו."],["239","31","ובשמו\"ר פי\"ג, ג: כי אני הכבדתי את לבו מהו הכבדתי שעשה הקב\"ה את לבו ככבד הזה שהיא כו' כך נעשה לבו של פרעה ככבד הזה ולא הי' מקבל דבריו של הקב\"ה."],["240","32","זח\"ב קנג, א. זהר חדש רות (פ, א)."],["241","33","ראה תו\"א פרשתנו (נז, א). אוה\"ת פרשתנו (כרך ז) ע' ב'תרו ואילך."],["242","34","פרשתנו ז, א."],["243","35","ראה תניא פל\"א."],["244","36","קהלת ז, יד."],["245","37","אוה\"ת בא שם (ע' רמח). וראה תו\"א פט, ד. ובארוכה המשך תרס\"ו ע' שכא ואילך."]]],[1301470101,"יקרות (\"הכבדות\") של העבודה דקבלת עול בקדושה.\nובזה מבאר רש\"י — \"יקיר ולא אתיקר\", שכדי לבטל כבדות של פרעה צ\"ל \"יקיר ולא אתיקר\".\nוהביאור בזה: בקבלת עול ישנן (בכללות) שתי מדריגות<sup data-n=\"246\">38</sup>:\nא) קבלת עול בדוגמת קבלת עול של עבד פשוט, דאף שבהפקירא ניחא לי'<sup data-n=\"247\">39</sup> ואין לו חשק ורצון בעבודתו ית', מ\"מ כופה א\"ע לקיים רצון אדונו. וקבלת עול זו היא למטה מכל כחות נפשו, דאף שאין לו עונג, רצון, השגה (שכל) או רגש (מדות) — הרי הוא כופה א\"ע ב­מעשה בפועל, היפך רצונו וטבעו.\nב) קבלת עול שלמעלה מכל כחות נפשו — וענינה, שאין התקשרותו לה' מדודה ומוגבלת כפי ערך ההגבלה של כחות נפשו [מדת הבנתו והשגתו בגדלות הא­ל, או מדת אהבתו ויראתו לה'] אלא הוא מוסר את עצמו לה' מכל וכל, בלי מדידה והגבלה. וקבלת עול זו מקורה בעצם הנפש, ש\"טוענת עולך\" מפני שהיא \"יחידה לייחדך\"<sup data-n=\"248\">40</sup>, \"חלק אלקה ממעל ממש\"<sup data-n=\"249\">41</sup>, ולכן אין מדידות והגבלות בתוקף התקשרותה של הנפש בהשם.\nוזהו שמפרש רש\"י — \"יקיר ולא אתיקר\" — שכדי לבטל כבדות דפרעה, שהוא \"שם דבר\", כבד בעצם, צ\"ל \"יקיר\" דקדושה ו\"לא אתיקר\", שלא מס­פיקה עבודת ה' בקב\"ע ב\"פועל\", הפעו­לה דקב\"ע, שהיא למטה מכל הכחות, אלא צ\"ל עבודת ה' מתוך קבלת עול עצמית, \"שם דבר\", כפי שהיא בעצם ה­נפש. הקב\"ע מבחי' איתן שבנשמה<sup data-n=\"250\">42</sup>, ה­\"כובד\" והחוזק שבעצם הנשמה.\nוע\"ז מביא רש\"י הראי' מהכתוב \"כמו כי כבד ממך הדבר\", הנאמר אצל משה, כי ביטול קליפת פרעה הוא על ידי משה דוקא, כנ\"ל, וזהו הרמז בפרש\"י \"כבד — ממך הדבר\", ש\"כבד\" דקדושה (המבטל \"כבד\" דפרעה) בא \"ממך\", מ­משה רבינו<sup data-n=\"251\">43</sup> — כי משה ענינו \"ונחנו מה\"<sup data-n=\"252\">44</sup>, תכלית הביטול לה', ולכן אצלו הוא אמיתית התוקף וה\"כובד\" המבטל כליל ה\"כובד\" דפרעה (שאינו אלא תוקף של ישות וגסות, \"לי יאורי ואני עשי­תיני\"<sup data-n=\"253\">45</sup>), ו\"בזאת תדע כי אני ה'\"<sup data-n=\"254\">46</sup>.\n<span data-k=\"q\">(משיחת ש\"פ וארא תשכ\"ו)</span>",[["246","38","ראה בכ\"מ (סה\"מ תרפ\"ז ע' ח ואילך. תש\"ב ע' 8. תש\"ח ע' 4. ועוד) החילוק דקבלת עומ\"ש דכל השנה להקבלת עול דר\"ה."],["247","39","גיטין יג, א."],["248","40","נוסח הושענות דיום ג'."],["249","41","תניא רפ\"ב."],["250","42","ראה לקו\"ת ר\"פ ראה."],["251","43","ראה בארוכה תו\"ח פרשתנו ד\"ה הם ה­מדברים (קיט, ב ואילך). אוה\"ת שם (ע' רכט­רל). וראה לקו\"ש חט\"ז ע' 74 ואילך. וש\"נ."],["252","44","בשלח טז, ז­ח. ועוד."],["253","45","יחזקאל כט, ג. וראה שם, ט. וראה תניא ספכ\"ב."],["254","46","פרשתנו שם, יז — הנאמר בדיבור משה לפרעה בהקדמת מכת דם. וראה תו\"א שבהערה 33 בפירוש \"וידעו מצרים כי אני ה'\" — \"וידעו הוא מלשון שבירה\"."]]],[1301470102,"<h3>שיחה ג</h3>\nא. בפסוק<sup data-n=\"255\">1</sup> \"וימלא שבעת ימים אחרי הכות ה' את היאור\" מפרש רש\"י: וימלא מנין שבעת ימים<sup data-n=\"256\">2</sup>, שלא שב היאור לקד­מותו, שהיתה המכה משמשת רביע חדש ושלשה חלקים הי' מעיד ומתרה בהם<sup data-n=\"257\">3</sup>.\nכוונת רש\"י בפשטות היא (כמ\"ש ב­מפרשים):\nא) לתרץ לשון \"וימלא\" — לשון יחיד, ד\"וימלאו (שבעת ימים) מיבעי לי'\"<sup data-n=\"258\">4</sup> [ואם \"שבעת ימים\" פירושו \"שבוע של ימים\"<sup data-n=\"259\">5</sup> (בלשון רש\"י בכ\"מ<sup data-n=\"260\">6</sup> — \"שטיינ\"א של ימים\") — הול\"ל \"ותמלא\", כי \"שבעת הוא שם לשבוע בלשון נקבה\"<sup data-n=\"261\">7</sup>]; ולכן מוסיף רש\"י תיבת מנין, כלומר, דהוי כאילו נכתב בקרא \"וימלא מנין שבעת ימים\".\nב) ליישב הלשון \"וימלא\" (גבי מנין ימים), דלכאורה אין לשון זה מתאים בנדו\"ד — \"כי<sup data-n=\"262\">8</sup> מלא לא שייך רק על דבר שיש לו שיעור (קצוב) כמו וימלאו ימי' ללדת<sup data-n=\"263\">9</sup>, מלא שבוע זאת והם שבעת ימי המשתה<sup data-n=\"264\">10</sup> — לכך אמר שגם בדבר הזה הי' המכה. . משמשת רביעית ה­חדש ויש לה שיעור שימלא\".\nאבל עדיין צריך ביאור באריכות לשון רש\"י:\nאם כוונתו היא רק להשמיענו שהי' שיעור קצוב לכל מכה ומכה (שלכן מתאים ע\"ז לשון \"וימלא\"), הי' מספיק לומר \"שבעת ימים, שהיתה המכה מש­משת רביע חדש\" — ומדוע מאריך רש\"י ומוסיף:\n(א) \"שלא שב היאור לקדמותו\" — וב­פרט שלכאורה אין בזה חידוש לגבי המפורש בקרא.\n[וגם את\"ל שכוונתו לפרט ענינה של המכה שאודותי' מדובר בקרא זה — הו\"ל לקצר ולכתוב \"שבעת ימים, ד­הכאת היאור\"<sup data-n=\"265\">11</sup> (וכלישנא דקרא כאן \"אחרי הכות ה' את היאור\"), ומדוע מאריך לתארה בלשון של שלילה \"שלא שב היאור לקדמותו\"<sup data-n=\"266\">12</sup>?].",[["255","1","פרשתנו ז, כה."],["256","2","י\"ל — שגם התיבות \"שבעת ימים\" הן חלק מהד\"ה<sup data-n=\"e8\">*</sup> (וצ\"ל נדפסות באותיות גדולות), אלא שרש\"י מוסיף תיבת \"מנין\" (כאילו נאמרה תיבה זו בכתוב, כדלקמן בפנים). ועד\"ז בכו\"כ מפרש\"י עה\"ת, כמדובר כ\"פ."],["257","3","בדפוס ראשון ושני, וכת\"י רש\"י שתח\"י — \"בו\" במקום \"בהם\" (ובמדרשים שבהערה 15 — \"בהם\"). ובפשטות — כי ההתראה היתה לפרעה."],["258","4","רא\"ם, גו\"א ועוד כאן."],["259","5","ל' רש\"י אמור כג, ח. וראה הנסמן בהערה הבאה."],["260","6","ויצא כט, כז. בא י, כב. יב, טו. אמור שם."],["261","7","ס' זכרון על פרש\"י כאן. ע\"ש."],["262","8","ל' הגו\"א. ועד\"ז בקיצור מזרחי. וראה רא\"ם. באר יצחק. ועוד."],["263","9","תולדות כה, כד."],["264","10","ויצא שם ובפרש\"י."],["265","11","וראה לשון הרשב\"ם כאן."],["266","12","ולכאורה דוחק לומר שרש\"י בא לשלול הפירוש (חזקוני ז, כ. בכור שור, הובא גם בריב\"א עה\"ת (ועוד) שם, יז) ש\"לא נעשה היאור דם כ\"א לפי שעה ומיד מתה הדגה מחמת הדם ואח\"כ חזר היאור לקדמותו ומ\"ש ולא יכלו מצרים לשתות. . לא מפני שהי' דם אלא משום והדגה. . מתה ויבאש היאור\" — כי מפשטות ל' הכתוב (ז, כא) \"והדגה גו' ולא יכלו מצרים לשתות גו' (ואח\"כ) ויהי הדם בכל ארץ מצרים\" משמע, שעיקר המכה הי' בזה שהיאור נעשה דם (וראה תוס' דעת זקנים (שם, יח). ריב\"א הנ\"ל. ועוד). ולהעיר מפרש\"י (ז, יז) דפשוטו שמכה זו לא באה להלקות המצריים כ\"א יראתם. ואכ\"מ."],["e8","*","ובדפוס ראשון דפרש\"י: וימלא שבעת ימים, מנין שבעת ימים כו'. ובדפוס שני ליתא תיבת \"מנין\"."]]],[1301470103,"(ב) \"ושלשה חלקים הי' מעיד ומתרה בהם\" — \"מעיד ומתרה\" מאן דכר שמייהו ולמאי נפק\"מ כאן (בהמדובר בקרא ע\"ד זמן הכאת היאור)?! ועוד: מנא לי' ל­רש\"י בפשוטו של מקרא שההעדאה וה­התראה נמשכו<sup data-n=\"267\">13</sup> זמן מדוייק ומוגבל של שלשה חלקי חדש<sup data-n=\"268\">14</sup> (והרי רש\"י אינו מביא זה בשם המדרש — זאת אומרת, ש­ההכרח לזה הוא מפשטות הכתובים עצמם)?\nגם צלה\"ב דיוק לשון רש\"י \"היתה כו' רביע חודש ושלשה חלקים כו'\": במדרשי חז\"ל שהובא ענין זה<sup data-n=\"269\">15</sup> — הלשון הוא: \"כ\"ד<sup data-n=\"270\">16</sup> ימים הי' מתרה בהם. . ושבעה ימים המכה משמשת כו'\" וכיו\"ב — ו­מדוע שינה רש\"י מלשון זה<sup data-n=\"271\">17</sup>?\nב. ויש לומר הביאור בכל זה:\nהלשון \"וימלא\" מורה שבשעה זו בא הדבר למילואו ולשלימותו<sup data-n=\"272\">18</sup>, ומקודם לכן עדיין חסר הוא. וכן בעניננו: טרם שעברו כל שבעת הימים עדיין הי' שיעורה של המכה חסר ולא נגמרה פעו­לתה, ורק כעבור מנין דשבוע ימים \"נת­מלא שיעורה\".\nאמנם בענין זה (שגמר המכה הוא רק כעבור כל זמנה) שונה מכת דם משאר המכות: פעולת שאר המכות (ששימשו רביע חודש<sup data-n=\"273\">19</sup>) היתה באופן, שבכל יום ויום נתחדשה פעולת המכה<sup data-n=\"274\">20</sup> [כמו מכת צפרדע, שבמשך שבעה ימים — בכל יום",[["267","13","וגם את\"ל ש(מצד חשבון השנים צ\"ל ש)המכות לא באו תיכף זא\"ז אלא נמשכו קרוב לשנה<sup data-n=\"e9\">*</sup> (ראה מפרשי השמו\"ר כאן — פ\"ט, יב. מהרז\"ו לשמו\"ר פ\"ה, יט. ועוד. וראה תו\"ש פרשתנו כאן אות צט) — מ\"מ, מנ\"ל בפשוטו של מקרא שמשה הי' מעיד ומתרה בהם כל הזמן שבין מכה למכה. וראה לשון המדרש (דב\"ר פ\"ז, ט) \"לשלשים יום היתה באה המכה והיתה עושה ז' ימים והלכה לה והיו נרווחין כ\"ג ימים בין מכה למכה\". וראה מדרש תהלים שבהערה 15 ובפי' מהר\"י כהן (חתן המהר\"ל) שם."],["268","14","היינו חודש קצוב (ולא שבוע ושבוע וכיו\"ב). ולהעיר מהתראת נינוה (יונה ג, ד), ב\"ד (ראה מו\"ק טז, א. אנציקלופדי' תלמודית ערך הזמנה (ב) וש\"נ). ועוד."],["269","15","שמו\"ר פ\"ט, יב. תנחומא פרשתנו יג (ותנחומא באבער יד). ועד\"ז בדב\"ר שם. מדרש תהלים (שוח\"ט) עה\"פ עח, לח (וכן בהוצאת באבער שם).\nבפיוט של ר\"א הקליר (הובא בבחיי כאן): ירח ימים כו' שלשה חלקים כו' ורביעית כו'. אבל מובן שטעמא בעי, אמאי העדיף רש\"י לשון זה על לשון חז\"ל בכל המדרשים הנ\"ל."],["270","16","ראה הגהות הרש\"ש לשמו\"ר שם (ועוד)."],["271","17","עוד שינויים בל' רש\"י לגבי ל' המדרש — ראה לקמן הערה 26; 36; בפנים סעיף ו'."],["272","18","ראה ס' השרשים להרד\"ק ערך מלא. וש\"נ."],["273","19","משא\"כ מכת בכורות שמתו ברגע אחד, שאינה בכלל זה ש\"היתה המכה משמשת רביע חדש\". ובמכת חשך ששת ימים. וראה השקו\"ט במפרשי רש\"י והשמו\"ר. ועוד. שו\"ת הרדב\"ז ח\"ג סתתי\"ג. ואכ\"מ. וראה הערה 20, 21. 35."],["274","20","ראה גם גבורת השם (להמהר\"ל) רפל\"ג [אבל ראה שם בהמשך הפרק (וכן בגו\"א פרשתנו ח, ה) שבמכת צפרדע ועוד לא הי' כן. ע\"ש. וראה הערה הבאה]."],["e9","*","ולהעיר: בפשש\"מ — משה הי' בן פ' בדברו אל פרעה (פרשתנו ז, ז), ונפטר בן ק\"כ שנה (ברכה לד, ז), ובנ\"י הלכו במדבר מ' שנה (בשלח טז, לה. שלח יד, לג. דברים ב, ז. ועוד). ואכ\"מ."]]],[1301470104,"היו מקרקרים בכל גבולי מצרים; במכת כנים — הלכו ורחשו באדם ובבהמה בכל יום ויום, ועד\"ז בשאר המכות<sup data-n=\"275\">21</sup>] — ולכן מתאים בהם הלשון \"וימלא\", כלו­מר, \"שיעור\" פעולת המכה \"נתמלא\" ב­שבעת הימים שהיתה מכה זו \"משמשת\" — פועלת והולכת (ועד אז עדיין לא נגמרה פעולת המכה (לא — תוצאותי')):\nמשא\"כ במכת דם, הרי ברגע הראשון של המכה נהפכו \"כל המים אשר ביאור. . ויהי הדם בכל ארץ מצרים\"<sup data-n=\"276\">22</sup>.\nכמפורש בקרא: וימלא ז' ימים אחרי הכות ה' את היאור.\nואף שבמשך כל שבעת הימים של­אחרי הכאת היאור היו נכנסים מים חדשים להיאור<sup data-n=\"277\">23</sup> — הנה לא הי' צורך לפעולת מכת הדם מחדש כדי שגם מים אלו יהפכו לדם, כי מלשון הכתוב \"כל המים אשר ביאור\" ומהלשון \"הלקה את יראתם\"<sup data-n=\"278\">24</sup> מובן שמכת דם היתה בכל היאור (נהר נילוס) ובכל מקום שנמצא \"יראתם\" — גם מחוץ לגבולות מצרים<sup data-n=\"279\">25</sup>; ואולי יש להוסיף, שרק כמות קטנה של המים החדשים שנכנסו למקור היאור הגיעו ל(חלק) היאור שבארץ מצרים ונתבטלה במיעוטה, ובכלל — קמא קמא בטיל;\nומכיון שפעולת המכה \"הכות היאור\" כבר נגמרה ברגע הראשון, שוב לא שייך לומר לכאורה שבמשך שבעת ה­ימים היתה המכה ממשיכה בפעולה עד ש\"נתמלא שיעורה\" בשבעת ימים<sup data-n=\"280\">26</sup>.\n[במדרש איתא<sup data-n=\"281\">27</sup> ד\"מצרי וישראל ב­בית אחד והגיגית מלאה מים ומצרי. . מוציאה מליאה דם וישראל שותה מים. . והמצרי אומר לו תן לי בידך מעט מים ונותן לו ונעשו דם\" (ורק \"כשהי' לוקח מישראל בדמים הי' שותה מים\"), ולפ\"ז נמצא דגם במכת דם היתה פעולת המכה נמשכת כל שבעת הימים, דהרי כשהגיעו המים מיד ישראל ליד מצרי נהפכו אז לדם.\nאבל בפרש\"י אין כל זכר לנס זה, והטעם — כי אין כל רמז לנס זה ב­פשוטו של מקרא<sup data-n=\"282\">28</sup>. ואדרבה: בכתוב מ­פורש<sup data-n=\"283\">29</sup> \"ויחפרו כל מצרים סביבות",[["275","21","וגם במכת דבר — \"ביום ראשון הוכו כולם בדבר ומתו בתוך ז' ימים\" (שו\"ת הרדב\"ז שם). וכן בחשך שהיתה המכה הולכת ומתגברת (ראה פרש\"י בא י, כב. שו\"ת הרדב\"ז שם).\nובכל אופן: גם את\"ל שהיו מכות שלא היו באופן שפעולתן היתה הולכת ומתגברת (וראה הנסמן בהערה הקודמת. ועוד) — לא קשיא, כי בהם לא נאמר הלשון \"וימלא\", משא\"כ במכת דם."],["276","22","ז, כ­כא. וכולל לא רק המים שביאור עצמו, אלא גם המים שב\"נהרותם. . יאוריהם. . אגמיהם. . כל מקוה מימיהם. . ובעצים ובאבנים\" (שם, יט. וראה רש\"י שם)."],["277","23","וראה ראב\"ע כאן פסוק כב. גבורת השם שם."],["278","24","רש\"י פרשתנו ז, יז."],["279","25","ועוד: מכיון שטעם המכה הי' כדי להלקות יראתם הי' צ\"ל המכה בכולה, שלא יאמרו שאין לו שליטה על כל \"יראתם\" (ע\"ד פרש\"י וירא יט, כד; בשלח יד, ב (בנוגע למצרים). ועוד)."],["280","26","ואף שכל יום שא\"א להמצרים לשתות מים מן היאור נתוסף בצערם — הרי אין זו הוספה בפעולת המכה (אלא רק בתוצאות שלה).\n[ועפ\"ז יומתק השינוי בל' רש\"י — \"היתה המכה משמשת\", ולא כתב (כלשון שמו\"ר ותנחומא שם) \"משמשת בהם\" (ע\"ד \"מתרה בהם\") — כי הדיוק כאן הוא פעולת המכה — \"משמשת\", ולא התוצאה בהמצריים (\"בהם\")]."],["281","27","שמו\"ר פ\"ט, י (וש\"נ) ותנחומא שם."],["282","28","כקושית הראב\"ע (פרשתנו ז, כד). — וב­פרט ע\"פ משנ\"ת במק\"א (לקו\"ש חי\"א ע' 31 ואילך), שפשש\"מ הוא כדעת הראב\"ע (שם) שג' המכות ה­ראשונות פגעו גם בישראל. ע\"ש."],["283","29","פרשתנו שם."]]],[1301470105,"היאור מים לשתות כי לא יכלו לשתות ממימי היאור\", שפירושו (ע\"ד הפשט) הוא, שהמים מחפירות אלו היו ראויים לשתי' ושתו אותם<sup data-n=\"284\">30</sup> (כי המכה היתה רק במי היאור, ולא בהמים שחפרו \"סביבות היאור\"<sup data-n=\"285\">31</sup>), והיינו שהמים האלה לא נהפכו לדם].\nולכן מבאר רש\"י — \"שלא שב היאור לקדמותו\", כלומר, גם מכה זו (\"היתה המכה משמשת\" —) היתה במשך כל שבעת הימים, אלא שלא היתה ע\"י פעולה, כ\"א באופן שלילי — \"שלא שב היאור לקדמותו\".\nוההסברה: א) מפורש בקרא, כנ\"ל, ד\"הכות היאור\" — הי' לפני ה\"שבעת ימים\", וא\"כ פעולת המכה נגמרה אז. ב) לאידך, לא מצינו שלאחרי גמר מכת דם תהי' פעולה להחזיר את הדם למים. וב­פשטות — \"שב היאור לקדמותו\" בדרך ממילא<sup data-n=\"286\">32</sup>, ונמצא שהמכה \"היתה משמשת\" כל שבעת הימים (שלא ישוב היאור לקדמותו). ולכן גם במכה זו מתאים הלשון \"וימלא (מנין) שבעת ימים\" — ש\"נתמלא\" שיעור המכה.\nג. ובכל זאת אין רש\"י מסתפק בזה, כי עדיין אינו מיושב היטב המשך ה­כתובים כאן — \"וימלא גו' אחרי הכות גו' ויאמר ה' אל משה בא אל פרעה ואמרת אליו גו'\",\nדהלשון משמע קצת, שהכתוב \"וימלא גו'\" הוא (גם) הקדמה להתראה שבפסוק שלאח\"ז, דכאשר \"וימלא שבעת ימים גו'\" אזי אמר ה' למשה שילך ויתרה את פרעה על אודות מכת צפרדע<sup data-n=\"287\">33</sup>.\nדאם כוונת הכתוב היא רק להודיענו כמה ימים נמשכה המכה — הול\"ל \"ותהי המכה שבעת ימים\" (וכיו\"ב); ומזה שה­כתוב מדייק לומר \"וימלא שבעת ימים גו'\" (היינו הזמן דסיום וגמר המכה) משמע קצת, שפסוק זה הוא הקדמה להבא לאחרי סיום מכה זו.\nאבל לאידך, אם \"וימלא גו'\" הוא רק הקדמה לפסוק שלאח\"ז — הול\"ל \"ויהי אחרי המכה\" (וכיו\"ב). ומכיון שהכתוב מודיע בהקדמה זו גם שיעור זמן שימוש המכה (\"וימלא שבעת ימים\") משמע, שגם שיעור זה נוגע לההמשך בפסוק שלאח\"ז ע\"ד ההתראה.\nוזהו שרש\"י כותב — \"שהיתה המכה",[["284","30","ומתורץ בפשטות מ\"ש (שם, כב) ויעשו כן חרטומי מצרים גו' (ראה ראב\"ע שם. חזקוני וריב\"א שבהערה 12. ועוד)."],["285","31","במדרש (שמו\"ר שם, יא) פלוגתא, ולחד מ\"ד סביבות היאור הי' דם (והמצריים חפרו בחשבם שימצאו מים — ראה מפרשים שם). אבל בפשש\"מ שהיו יכולים לשתות מים מסביבות היאור ושתו, שהרי רש\"י אינו מפרש בזה.\nוי\"ל, דאדרבה: מכיון שלפרש\"י באה מכה זו להלקות יראתם — אין להכות המים שסביבות היאור (שאינם מנילוס), שא\"כ אין מכה זו שייכת ליראתם כ\"א למים (בכלל). — ומש\"נ \"נהרותם. . יאוריהם גו'\" (ראה הערה 22), י\"ל בפשש\"מ, כי המים שב­מקומות אלו באו מהיאור (ע\"ד \"בעצים ובאבנים\" שהובאו לשם ממק\"א)."],["286","32","והרי לא מצינו שהיו צריכים להוציא הדם מהאגמים וכל מקוה מימיהם לאחרי המכה, או שהיתה פעולה ונס מיוחד שהדם בכל מקומות הנ\"ל יחזור למים — ע\"ד שנא' בהמכה (ז, יט) \"ונטה ידך על מימי מצרים על נהרותם על גו' ויהיו דם\".\nוראה השקו\"ט בכמה מפרשים (חזקוני, בכור שור, תוס' דעת זקנים וריב\"א שבהערה 12. ספורנו שם, יח. אברבנאל. ועוד) — אם המים נעשו דם או רק נראו כדם (והי' להם טעם דם) ובמהותם נשארו מים. ושתיקת רש\"י — משמעותה דמפרש כפשוטו ש\"מ ממש."],["287","33","להעיר גם מס' דבק טוב לפרש\"י כאן."]]],[1301470106,"משמשת רביע חודש ושלשה חלקים הי' מעיד ומתרה בהם\", כלומר: גם ההתראה היתה קשורה עם שיעור וזמן מסויים, ועוד זאת — שני הענינים שבכל מכה (שימושה של המכה והתראתה) ושיעורם, הם חלקים משיעור אחד שלם<sup data-n=\"288\">*33</sup> הכולל כללות המכה: השיעור השלם והקצוב של כללות המכה הי' חודש<sup data-n=\"289\">34</sup> (שלם)<sup data-n=\"290\">*34</sup>, והחודש נחלק לשנים: חלק אחד (רביע החדש<sup data-n=\"291\">35</sup>) הי' שיעורה של המכה עצמה, ושלשה חלקים — שיעור ההתראה.\nד. וי\"ל דזוהי כוונת רש\"י — שמק­דים \"שהיתה המכה משמשת\" ל\"הי' מעיד ומתרה בהם\" [היפך סדרן בפשטות, דמ­קודם באה ההעדאה וההתראה ואח\"כ המכה<sup data-n=\"292\">36</sup>]:\nמקורו לסדר זה הוא סדר הכתוב, ש­\"וימלא שבעת ימים\" (המלמדנו את שיעור הזמן שהיתה המכה משמשת) בא כהקדמה ל\"ויאמר ה' אל משה בא אל פרעה ואמרת אליו גו'\" — ההתראה על המכה שלאח\"ז. ועל יסוד זה הוא פירושו של רש\"י, שחודש הימים שנקצב לכל מכה ומכה נחלק באופן, שהרביע הרא­שון \"היתה המכה משמשת. . ושלשה חלקים (שלאח\"ז) הי' מעיד ומתרה בהם\" על המכה שלאח\"ז.\nאלא שלכאורה דבר תמוה הוא — איך מתאים לומר ששיעור זמן המכה נחלק באופן שבתחילה באה המכה ואח\"כ ההתראה על המכה שלאחרי' — הרי כל ענין ההתראה הוא הכנה והק­דמה להמכה (שתבוא לאחרי' דוקא)!\nה. ויש לומר הביאור בזה:\nכוונתן של ההתראות לפרעה הי' לא (רק) במובן הרגיל של התראה, הכנה למכה שלאחרי' — (אלא) כדי לאיים ולהשפיע על פרעה לשלוח סו\"ס את בנ\"י מארצו,\nשהרי הקב\"ה אמר למשה תיכף ב­תחילת שליחותו לפרעה \"ואני אקשה את לב פרעה גו' ולא ישמע אליכם פרעה גו'\"<sup data-n=\"293\">37</sup> —\nההתראות היו (ג\"כ) ענין של \"מכה\" — כדי \"לרדותו. . ביסורין\"<sup data-n=\"294\">38</sup>, היינו, לג­רום לו צער ויסורין, הדיבורים שהי'",[["288","*33","ואולי י\"ל שלכן נקט רש\"י שהשיעור הקצוב לכל מכה הי' חודש (ולא שבוע ושבוע — ראה לעיל הערה 14) — כי מסתבר לומר שהשיעורים של שני חלקי המכה היו חלקים מתקופה אחת — \"חודש\" (וכמו \"שבעת ימים\" של שימוש המכה שהם תקופה אחת — שבוע)."],["289","34","ובל' המדרש תהלים (באבער) שם: חודש הי' קצוב לכל מכה. וראה גם הלשון בדב\"ר שם."],["290","*34","להעיר משינוי בגובה המים בנהרות (כולל נילוס) בקשר לימים בחודש, כמחז\"ל (רבינו בחיי. וראה מו\"נ ח\"ב פ\"י) עה\"פ וממגד גרש ירחים."],["291","35","וי\"ל שבזה מוסיף רש\"י ג\"כ שאין צ\"ל \"שבעת ימים\" בדיוק בכל מכה ומכה, אלא בערך רביע חדש (וכן \"שלשה חלקים\" שלאח\"ז). ומתורצת קושיית הבעלי תוס' (דעת זקנים) כאן ש\"לא היתה כ\"א כ\"ח יום\". וכן — הערת המפרשים ממכת חשך (שלכאו' היתה רק ו' ימים)."],["292","36","ובפרט שרש\"י משנה בזה מלשון המדרשים (שצויינו בהערה 15), שבכולם מקדים \"מתרה בהם\" ל\"המכה משמשת\".\nובפשטות הטעם (וראה גם לקו\"ש ח\"ו ע' 58 הערה 14) — לפי שכאן בא לפרש \"וימלא (מנין) שבעת ימים\"; ורק אח\"כ ממשיך לבאר מה אירע בשאר חלקי החדש.\nאבל עדיין אינו מיושב לגמרי, כי רש\"י כבר פירש הכתוב \"וימלא שבעת ימים\" — בכתבו \"שלא שב היאור כו'\", והמשך לשונו הוא רק ביאור שזהו השיעור הקצוב. ולכאו' הו\"ל לתאר סדר המכה כפי שאירע בפועל."],["293","37","פרשתנו ז, ג­ד."],["294","38","ל' רש\"י — פרשתנו ז, א. והכוונה גם ע\"י דיבורו של משה — ראה לקו\"ש חט\"ז ע' 74."]]],[1301470107,"משה מדבר לפרעה מלך מצרים בסגנון של התראה וכו' במשך כל זמן הנ\"ל, ה\"ז צער ויסורין לפרעה.\nועפ\"ז מובן שההתראה היא המשך למכה שלפני', ובפרט שהמכוון בההת­ראות — \"לרדותו. . ביסורין\" — נעשה בתוקף יותר כאשר ההתראות באות ב­סמיכות למכות (בפועל<sup data-n=\"295\">39</sup>): כאשר אך זה עתה שב היאור לקדמותו — ומיד בא משה אל פרעה בהתראה על המכה הבאה — הרי זה ממשיך ומגדיל את ה­שימוש וההכאה של המכה הקודמת.\nוי\"ל אשר גם מטעם זה, באה ההת­ראה על המכה הראשונה (דם) בהמשך (ותיכף) למופת המטה — דלאחר המופת לפני פרעה שמטה אהרן נעשה לתנין גו' ויבלע גו' את מטותם<sup data-n=\"296\">40</sup> צוה ה' למשה: \"לך<sup data-n=\"297\">41</sup> אל פרעה גו' והמטה אשר נהפך לנחש תקח בידך, ואמרת אליו גו'\" (ההת­ראה על מכת דם) — כי עי\"ז פעלה ההתראה על פרעה ביתר שאת.\nו. עפ\"ז מתורץ עוד דיוק בלשון רש\"י: במדרשים<sup data-n=\"269\">15</sup> הלשון \"הי' מתרה\" ו­רש\"י מוסיף \"הי' מעיד ומתרה\" (ועוד — מקדים מעיד לפני ומתרה):\nהחילוק בין מעיד ומתרה הוא<sup data-n=\"299\">42</sup>: העדאה (לשון עדות<sup data-n=\"300\">43</sup>) ענינה — להודיע ולגלות דבר שאירע בעבר או שיקרה בודאי בעתיד; ואילו התראה פירושה, להזהיר שביאת הדבר תלוי' בהנהגתו של המותרה — דאם יעשה תשובה (או לא יחטא) לא יבוא, ואם לאו יבוא.\nוכן בדברי משה אל פרעה היו שני הסוגים: ההעדאות הן הודעות שיענש (בודאי) על בלתי שלחו את עם ישראל, וההתראות על העתיד — \"אם מאן אתה לשלח גו'\"<sup data-n=\"301\">44</sup> (לאחרי התראה זו) תבוא עליו מכה פלונית.\nוע\"פ המבואר לעיל במטרת ההת­ראות מובן הטעם שרש\"י מקדים \"מעיד\" ל\"מתרה\"<sup data-n=\"302\">45</sup> — כי ההתראות היו ענין של \"העדאה\", דהגם שנאמרו בלשון התראה — \"ואם מאן אתה גו'\" — מ\"מ, מכיון ש\"לא ישמע אליכם פרעה\", הרי הן (גם) העדאה, ומשה (שהוא המדבר לפרעה) ידע שבודאי תבוא המכה.\nז. ש\"פ וארא חלה (ברוב השנים<sup data-n=\"303\">46</sup>) בשבת מברכים חודש שבט או (כבשנה זו<sup data-n=\"304\">47</sup>) שבת ר\"ח שבט — שבעשירי לחודש זה הוא יום ההילולא של כ\"ק מו\"ח אדמו\"ר.",[["295","39","ע\"ד פרש\"י ר\"פ אחרי."],["296","40","פרשתנו ז, ט ואילך."],["297","41","שם, טו ואילך."],["269","15","שמו\"ר פ\"ט, יב. תנחומא פרשתנו יג (ותנחומא באבער יד). ועד\"ז בדב\"ר שם. מדרש תהלים (שוח\"ט) עה\"פ עח, לח (וכן בהוצאת באבער שם).\nבפיוט של ר\"א הקליר (הובא בבחיי כאן): ירח ימים כו' שלשה חלקים כו' ורביעית כו'. אבל מובן שטעמא בעי, אמאי העדיף רש\"י לשון זה על לשון חז\"ל בכל המדרשים הנ\"ל."],["299","42","בהבא לקמן ראה לקו\"ש ח\"ו ע' 58 ואילך."],["300","43","אף ש\"מעיד\" הוא ג\"כ ל' התראה (רש\"י מקץ מג, ג) — מ\"מ, מהכפל והשינוי בל' רש\"י כאן מוכח כבפנים. וראה לקו\"ש שם בהערה 13. וש\"נ."],["301","44","פרשתנו ז, כז. ועוד."],["302","45","ובפשטות הטעם, כי במכה הראשונה היתה העדאה (ראה פרשתנו ז, טז­יז), ובמכה השני' — התראה (שם, כז)."],["303","46","רק בשתי קביעויות בלבד (א' דשנה פשוטה וא' דשנה מעוברת)<sup data-n=\"e10\">*</sup> — שבת וארא אינה שבת מברכים או ר\"ח שבט (ואז חלה ביום ג' שבט — דמיני' מתברכת ש\"ק יו\"ד שבט (יום ההילולא) שלאח\"ז)."],["304","47","תשמ\"ז."],["e10","*","ראה הלוחות שבטור או\"ח לאחרי הל' ר\"ח. — ומפורסם שיש ערעור על לוחות אלה (ראה פר\"ח לאו\"ח הל' ר\"ח. שו\"ת אבני נזר חאו\"ח סשט\"ו. חת\"ס ח\"ו סי' לה. ס' קורות חשבון העבור ע' קסג ואילך. ועוד)."]]],[1301470108,"וי\"ל רמז ולימוד בעבודת השם מהנ\"ל (ע\"ד ההתראות לפרעה (להמנגד), ש­עיקרן היו כדי \"להכותו\", \"לרדותו. . ביסורין\") — ע\"פ המבואר במאמרי יום ההילולא<sup data-n=\"305\">48</sup>, בענין מדת הנצח — שיש ענין מיוחד במלחמה לשבור ולנצח את המנגד,\nאשר<sup data-n=\"306\">49</sup> ענין הנצחון (מדת הנצח) נטוע ומושרש בעצם הנפש, שלכן בשביל נצוח מלחמה פותח המלך את האוצרות החתומים והכמוסים מדור דור, וכמו\"כ ברוחניות, שבשביל נצחון על המנגדים לקדושה, לכל הקשור להקב\"ה וישראל (בניו של מקום) ותורה ומצות, הרי הקב\"ה מגלה האוצרות הרוחניים הכי נעלים כדי לנצח מלחמה זו,\nוכן הוא בנוגע למצרים, וכמו שמביא בהמאמר (בפרק השייך לשנה זו<sup data-n=\"307\">50</sup>) מש\"נ<sup data-n=\"308\">51</sup> \"מוצא רוח מאוצרותיו שהכה בכורי מצרים\", \"דבשביל להכות בכורי מצרים. . (ש)הם תוקף ועוצם הקליפה, ובשביל זה מוציא רוח מאוצרותיו\".\nומזה ההוראה גם אלינו, בדורנו זה, דרא דעקבתא דמשיחא, דמבלי הבט על גודל החושך כפול ומכופל שבעולם, עלינו לדעת שבשביל ניצוח מלחמה רוחנית זו, ניתנו לנו כל הכחות ה­דרושים לזה, מ\"אוצרות\" הכמוסים של הקב\"ה<sup data-n=\"309\">52</sup>, ועל ידי זה שעומדים חזק בתוקף גדול ומתחזקים בעסק התורה והעבודה והמצות, נזכה בקרוב לנצחון, לנצחון האמיתי,\nשבני ישראל יצאו מן הגלות ביד רמה, בגאולה האמיתית והשלימה על ידי משיח צדקנו, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחת ש\"פ וארא תשל\"ה)</span>",[["305","48","המשך באתי לגני השי\"ת, שנמסר ע\"י כ\"ק מו\"ח אדמו\"ר ללמוד ברבים ליו\"ד שבט תש\"י, יום הסתלקותו."],["306","49","ראה שם פי\"א ואילך."],["307","50","תשמ\"ז — פי\"ז<sup data-n=\"e11\">*</sup>."],["308","51","תהלים קלה, ז­ח."],["309","52","ראה המשך הנ\"ל שם פי\"ט­כ."],["e11","*","שנה הי\"ז ללימוד ההמשך פעם שני' (כמשנ\"ת כמ\"פ אשר י\"ל שכל פרק מהעשרים פרקים של ההמשך מכוון גם לשנה אחת בפ\"ע)."]]],[1301470109,"<h3>שיחה ד</h3>\nא. בדברי ההתראה לפרעה ע\"ד מכת ברד נאמר<sup data-n=\"310\">1</sup> \"הנני ממטיר כעת מחר ברד כבד מאד\", ופרש\"י \"כעת מחר — כעת הזאת למחר, שרט<sup data-n=\"311\">2</sup> לו שריטה בכותל למחר כשתגיע חמה לכאן ירד הברד\".\nבמפרשים<sup data-n=\"312\">3</sup> ביארו שדיוקו של רש\"י הוא מהלשון \"כעת מחר\" [ולא אמר סתם \"מחר\" כמו לעיל<sup data-n=\"313\">4</sup> גבי מכת דבר<sup data-n=\"314\">5</sup>] — ש\"כעת\" (בניקוד קמ\"ץ<sup data-n=\"315\">6</sup>) פירושו, \"כעת הזאת למחר\", דהיינו \"העת<sup data-n=\"316\">7</sup> אשר הי' מדבר עמו\".\nאבל צ\"ע, מנ\"ל לרש\"י (בפשוטו של מקרא) שמשה לא רק קבע לפרעה הזמן שירד הברד (\"כעת הזאת למחר\") אלא גם עשה סימן, \"שרט לו שריטה בכותל, למחר כשתגיע חמה לכאן ירד הברד\"?\nואין לומר לפי שזו היתה הדרך ה­יחידי אז לברר ולידע שעה מדוייקת ביום<sup data-n=\"317\">8</sup> — שהרי ודאי היו אז מכשירים שונים לידע השעות, כמו שעון מים<sup data-n=\"318\">9</sup> וכיו\"ב.\n[וב\"משכיל לדוד\" על פרש\"י כאן כתב, ד\"כבר הרגיש כן הרב יפה תואר<sup data-n=\"319\">10</sup> והניחו חלק, והאמת דאגדות כאלה אין להם מקום להבינם אלא עפ\"י הנסתר\", והולך ומבאר דברי רש\"י ע\"ד הסוד, כ­דלקמן סעיף ה].\nב. יש מפרשים<sup data-n=\"320\">11</sup>, שההכרח לזה הוא מלשון הכתוב \"כעת\" — \"דפי' כעת נקו­דה בקמ\"ץ הוא כמו כהעת והיינו ה­ידועה<sup data-n=\"321\">12</sup> ולזה מוכרח שאמר כעת הזאת ו\"זה\" ו\"זאת\" מורה באצבע כמ\"ש רז\"ל בכמה מקומות<sup data-n=\"322\">13</sup>. . וע\"כ צ\"ל דשרט שריטה בכותל והורה לו באצבע כשתגיע השמש לכאן שע\"ז שייך הוראה באצבע, וכן דרשו ג\"כ בתנחומא<sup data-n=\"323\">14</sup> גבי אברהם דכתיב<sup data-n=\"324\">15</sup> כעת חי' והיינו מטעם הנזכר\".\nאבל מלבד זאת שעדיין אין זה מתרץ מנ\"ל לרש\"י שהסימן הי' שריטה בכותל דוקא (ולא שהורה באצבע על \"שעון מים\" וכיו\"ב שבזמן זה למחר ירד ה­ברד), הרי עוד זאת — בפרש\"י לעיל גבי אברהם מוכח, שאין שיטת רש\"י שתיבת \"כעת\" משמעה שהראה באצבע:",[["310","1","פרשתנו ט, יח."],["311","2","תנחומא פרשתנו טז. שמו\"ר פי\"ב, ב."],["312","3","ראה רא\"ם, רע\"ב, גו\"א, לבוש, אמרי שפר, קצור מזרחי. ועוד."],["313","4","ט, ה."],["314","5","גו\"א ועוד כאן."],["315","6","ראה רע\"ב. לבוש. קצור מזרחי. באר יצחק. ועוד. וראה גם בארוכה מפרשי רש\"י לפרש\"י וירא יח, י. ואכ\"מ."],["316","7","ל' הרא\"ם."],["317","8","להעיר ממ\"ב (כ, ט­יא וברש\"י שם. וכן בישעי' לח, ח). משנה (עדיות פ\"ג מ\"ח. כלים פי\"ב מ\"ד­ה) \"אבן השעות\" ובמפרשים שם. — וראה ראב\"ע בא (יא, ד) \"בכלים גדולים של נחושת\"."],["318","9","ראה זח\"א צב, ב. ערוך מע' חלפסדרא (מב\"ר ספמ\"ט עה\"פ המכסה אני מאברהם)."],["319","10","(השלם) לשמו\"ר שם."],["320","11","באר בשדה על פרש\"י כאן."],["321","12","ראה גם קצור מזרחי כאן."],["322","13","הובא גם בפרש\"י בא יב, ב. בשלח טו, ב. בהעלותך ח, ד. וראה גם רש\"י תשא ל, יג. שמיני יא, ב."],["323","14","וירא יג. וכן בתנחומא באבער שם לו."],["324","15","וירא יח, י (כן הובא בתנחומא שם, והוא מדברי המלאך. ובת\"ב — וכן בפרש\"י שם כא, ב — הובא הכתוב דלקמן שם (יח, יד), מדברי הקב\"ה. וכבר האריכו במפרשים)."]]],[1301470110,"עה\"פ<sup data-n=\"325\">16</sup> \"שוב אשוב גו' כעת חי'\" גבי אברהם פרש\"י \"כעת הזאת לשנה הבאה\", ולא העתיק שם פירוש התנחומא ש­הקב\"ה שרט לו שריטה בכותל (וגם לא הביא איזה פירוש אחר ששייך בו \"הור­אה באצבע\"). ועד\"ז אח\"כ עה\"פ<sup data-n=\"326\">17</sup> (ב­דברי הקב\"ה לאברהם) \"למועד אשוב אליך כעת חי' ולשרה בן\" פרש\"י \"למו­עד — לאותו מועד המיועד שקבעתי לך אתמול למועד<sup data-n=\"327\">18</sup> הזה בשנה האחרת\", ואילו על התיבות \"כעת חי'\" לא פרש\"י מאומה.\nוביותר תמוה: בסיפור לידת יצחק נאמר<sup data-n=\"328\">19</sup> \"ותהר ותלד שרה גו' למועד אשר דבר אותו אלקים\", ופרש\"י \"את ה­מועד אשר דבר וקבע כשאמר לו למועד אשוב אליך שרט לו שריטה בכותל ואמר לו כשתגיע חמה לשריטה זו בשנה אחרת תלד\" — הרי שרש\"י אכן הביא פירוש התנחומא, אבל (א) לא על הכתוב \"כעת חי'\" (שנאמר שתי פעמים לפנ\"ז), אלא רק אח\"כ עה\"פ \"ותלד גו' למועד אשר דבר אותו אלקים\"<sup data-n=\"329\">20</sup>, (ב) גם כש­רש\"י מביאו בקשר ל\"המועד אשר (הקב\"ה) דבר וקבע\", מעתיק רש\"י רק התיבות \"למועד אשוב אליך\" ומשמיט המשך דברי השם \"כעת חי'\"<sup data-n=\"330\">21</sup>!\nאשר מכל זה מוכח, שלשיטת רש\"י אין הכרח מלשון \"כעת חי'\" שהיתה כאן איזו פעולה \"שע\"ז שייך הוראה באצבע\", ואינו אלא לשון המורה על קביעת זמן מיוחד וברור.\n[ויש לומר, שהכרחו של רש\"י (בפ' וירא) שהקב\"ה \"שרט לו שריטה כו'\", הוא מיתור לשון הכתוב בסיפור לידת יצחק<sup data-n=\"331\">22</sup>: לאחרי שנאמר<sup data-n=\"332\">23</sup> \"וה' פקד את שרה כאשר אמר ויעש ה' לשרה כאשר דבר\", פשיטא שלידת יצחק היתה בדיוק \"כאשר דבר\", \"למועד אשר דבר אותו אלקים\", ול\"ל להכתוב לפרט זה? ולכן מפרש רש\"י, שיתור זה מלמדנו, שבעת לידת יצחק הי' ניכר לכל שהלידה היתה \"למועד אשר דבר אותו אלקים\"; והא כיצד? ע\"ז אומר רש\"י שהקב\"ה \"שרט לו שריטה בכותל כו'\", באופן שהכל ראו והעידו שיצחק נולד בדיוק \"למועד אשר דבר אותו אלקים\"<sup data-n=\"333\">24</sup>].\nוא\"כ — מנ\"ל לרש\"י כאן בפרשתנו, שלא רק שמשה רבנו קבע לפרעה זמנה המדוייק של ירידת הברד (\"כעת הזאת למחר\"), אלא גם עשה סימן ו\"שרט לו שריטה בכותל\"?",[["325","16","שם, י."],["326","17","שם, יד."],["327","18","לך יז, כא."],["328","19","וירא כא, ב."],["329","20","ולהעיר שגם בתנחומא בא הפירוש בפרשת לידת יצחק ולא לעיל במקומו."],["330","21","בבאר בשדה על פרש\"י וירא (יח, יד) כ' דנלמד ממ\"ש \"כעת חי'\" (ע\"ש). אבל מזה שרש\"י השמיט תיבות אלו מוכח כבפנים."],["331","22","ולא מלשון \"למועד אשוב גו'\" — דא\"כ הי' רש\"י מפרש זה במקומו (וירא יח, י). וראה רא\"ם ועוד מפרשים לפרש\"י שם (כא, ב). ואכ\"מ."],["332","23","שם כא, א."],["333","24","והטעם שהכתוב מרמז ענין זה רק אצל לידת יצחק (ולא לפנ\"ז כשהקב\"ה קבע את המועד (ס\"פ לך), או כשאמר לו \"למועד אשוב אליך\") — הוא בפשטות: עיקר הצורך בסימן זה לא הי' בשביל אברהם ושרה עצמם (שלאחרי ששמעו דברים ברורים מפי הקב\"ה שוב לא הסתפקו כלל), אלא בעיקר עבור אלו שרננו אחרי יצחק ואמרו שהוא אסופי (רש\"י וירא כא, ז) או ש\"מאבימלך נתעברה שרה\" (רש\"י שם, ב. ר\"פ תולדות) — שכדי לשלול רינון זה עשה הקב\"ה (עוד) סימן שהכל יעידו שיצחק נולד באופן נסי ע\"פ דברי ה', בדיוק \"למועד אשר דבר אותו אלקים\"."]]],[1301470111,"ג. ויש לומר הביאור בזה, ובהקדם השאלה — במה נשתנתה מכה זו משאר המכות, שדוקא בה הודיע משה לפרעה את זמנה המדוייק של התחלת המכה?\nולכאורה הי' מקום לומר<sup data-n=\"334\">25</sup>, שזה הי' בשביל \"הירא את דבר ה'\", שיוכל ל­הניס את עבדיו ואת מקנהו אל הבתים<sup data-n=\"335\">26</sup>, וע\"כ הודיע משה לפרעה זמנה המדוייק של התחלת ירידת הברד כדי שידעו מתי להניס את מקניהם ועבדיהם אל הבתים.\nוכדי לשלול פירוש זה, מוסיף רש\"י \"שרט לו שריטה בכותל כו'\", שע\"י הוס­פה זו ברור, שמטרת משה באמרו \"כעת הזאת למחר\" לא היתה מכוונת ל\"הירא את דבר ה'\", שלא הי' בארמונו של פרעה ולא הי' יכול להבחין כלל בסימן זה של שריטה בכותל — אלא אך ורק בשביל פרעה עצמו, דכאשר פרעה יראה שלא זו בלבד שדברי ה' מתקיי­מים, אלא שהם מכוונים להרגע ממש שבו קבע שתתחיל המכה, הרי אא\"פ לו להיות בספק כלל שאכן יד ה' עשתה זאת.\n[וההכרח לומר שלא הי' בשביל \"ה­ירא את דבר ה'\" מובן בפשטות — כי גם אם משה הי' אומר סתם \"הנני ממטיר מחר ברד\" (כמו שאמר במכת ערוב ודבר) היו יכולים \"הירא את דבר ה'\" ל­הציל את עבדיהם ומקניהם<sup data-n=\"336\">27</sup>; וכי היתה כוונת משה להרוויח שיוכלו להניח את עבדיהם ומקניהם בשדה זמן מועט<sup data-n=\"337\">28</sup> של תחלת יום המחרת עד שירד הברד?!].\nואין להקשות מדוע עשה ה' כן רק ב­מכת ברד (ולא לפנ\"ז במכת דבר וערוב שקבע זמנם רק באופן כללי, שיהי' \"מחר\"<sup data-n=\"338\">29</sup>) — כי זה מובן מעצמו מהמשך הכתובים כאן: בדברי ההתראה למכת ברד מצינו הקדמה מיוחדת (שלא מצינו בשאר המכות שלפנ\"ז) — \"כי<sup data-n=\"339\">30</sup> בפעם הזאת אני שולח את כל מגפותי אל לבך גו' בעבור תדע כי אין כמוני בכל הארץ. . בעבור זאת העמדתיך בעבור הר­אותך את כוחי ולמען ספר שמי בכל הארץ\", והיינו שמכה זו (יותר מכל המכות הקודמות) תוכיח ברור את כוחו של הקב\"ה. וא\"כ מובן בפשטות הטעם שהראה הקב\"ה לפרעה את \"כוחו\" גם בנוגע לקביעת זמן המכה, שכיוון את הרגע ממש שבו תתחיל המכה.\nד. ע\"פ כל הנ\"ל יש לבאר ג\"כ ה­הכרח לומר שמשה \"שרט לו שריטה בכותל\" דוקא (ולא הראה על \"שעון\" של מצרים); ובכלל מנ\"ל שעשה איזה סימן ולא אמר סתם \"כעת הזאת למחר\":\nכיון שכל כוונת קביעת הזמן היתה להראות לפרעה שהקב\"ה יכול לכוון את",[["334","25","וראה לקו\"ש חכ\"א ע' 58."],["335","26","ט, כ."],["336","27","וכמפורש בפרש\"י (לעיל ט, י. וראה רש\"י בשלח יד, ז) שגם במכת דבר \"לא נגזרה גזירה אלא על אותן שבשדות בלבד. . והירא את דבר ה' הניס את מקנהו אל הבתים\". וראה אוה\"ח פרשתנו שם (ט, ה)."],["337","28","שהרי הקב\"ה אמר \"השכם בבוקר\" (ט, יג) — והברד ירד \"כעת הזאת למחר\"."],["338","29","וראה מה שתי' בגו\"א כאן."],["339","30","ט, יד­טז. — בפרש\"י (שם, יד) \"למדנו מכאן שמכת בכורות כו'\". אבל: (א) לכמה מפרשים (ר\"ת הובא ברא\"ם, לבוש ועוד) קאי על מכת ברד (\"בכורות\" — \"בפת\"ח הבית ובשורק הוי\"ו\". ע\"ש). (ב) גם להמפרשים שקאי על מכת בכורות, עכצ\"ל שהתראה זו שייכת גם למכת ברד כיון שנכתבה כאן. ועיקר: מ\"ש (פסוק טז) \"בעבור הראותך את כוחי ולמען ספר שמי גו'\" קאי לכו\"ע (גם) על מכת ברד. וכבר האריכו במפרשי רש\"י. ואכ\"מ."]]],[1301470112,"הרגע ממש — לא הי' מקום לסמוך על מורה­השעות שהיו בידי פרעה וחרטו­מיו, שעל ידם יראו איך שה' כיוון את הרגע ממש — כי יתכן שאין מורה­שעות אלו (העשויים בידי אדם) מדוייקים, או שהחרטומים יטעו בחשבונם כו', וידמו שמשה לא כיוון את הרגע,\nוע\"ד פרש\"י לקמן<sup data-n=\"340\">31</sup> גבי מכת בכו­רות, בדברי משה לפרעה \"כה אמר ה' כחצות הלילה אני יוצא גו'\" — \"שאמר משה כחצות דמשמע סמוך לו או לפניו או לאחריו ולא אמר בחצות שמא יטעו אצטגניני פרעה ויאמרו משה בדאי הוא\",\nולכן מוכרח לומר שמשה עשה איזה סימן שאי אפשר לטעות בו<sup data-n=\"341\">32</sup> — וע\"כ פירש \"שרט לו שריטה בכותל, למחר כשתגיע חמה לכאן ירד הברד\", שסימן זה אינו תלוי בידי אדם אלא בידי שמים (במהלך החמה) ואין לטעות בו.\n[ועפ\"ז יומתק הטעם שרש\"י בפירושו הנ\"ל בפ' בא עה\"פ כחצות הלילה מעתיק בהד\"ה גם תיבת \"הלילה\" (וכן בגוף פירושו<sup data-n=\"342\">33</sup>, אומר \"ור\"ד כמו כב­חצות הלילה\" — ולא קיצר \"כמו כב­חצות\") — די\"ל, שהיסוד לפרש\"י הוא מזה שהמדובר בחצות לילה דוקא: אם הי' מדובר בחצות יום, לא הי' צורך לשנות מדברי ה' כדי שלא יאמרו \"משה בדאי הוא\", כי הי' אפשר לעשות שריטה בכותל (כמו שעשה במכת ברד); אלא כיון שכאן הי' \"חצות הלילה\" ואין סימן שאא\"פ לטעות בו, לא היתה ברירה אלא לשנות ולומר \"כחצות הלילה\"].\nה. מ\"יינה של תורה\" שבפירוש רש\"י זה:\nנזכרו לעיל דברי המשכיל לדוד שביאר פרש\"י זה ע\"ד הסוד, ותמצית דבריו:\nרש\"י מביא לקמן<sup data-n=\"343\">34</sup> שהי' הברד \"נס בתוך נס האש והברד מעורבין. . ו­לעשות רצון קונם עשו שלום ביניהם\", שעירוב זה דאש ומים מורה על ההת­כללות דמדת הרחמים ומדת הדין, שהמים (חסד) באים מצד שם הוי'<sup data-n=\"344\">35</sup>, מדת רחמים, והאש (גבורה) מבית דין<sup data-n=\"344\">35</sup> — מדת הדין, והיותם מעורבים יחד מורה על יחוד קוב\"ה (הוי') ושכינתי' (דין) \"על ידי השלום\". וזהו הרמז גם כן בזה ש­\"שרט לו שריטה בכותל. . כשתגיע חמה לכאן ירד הברד\", כי השריטה ב­כותל, וכן הגעת השמש בכותל, מורים על יחוד קוב\"ה ושכינתי' (כמו שמבאר שם ע\"פ הזהר<sup data-n=\"346\">36</sup>).\nויש להוסיף, שההתכללות דרחמים ודין במכה זו — מפורשת בפשטות ה­כתובים: מכת ברד מיוחדת משאר כל המכות בשני הקצוות — מחד גיסא הרי ממכה זו הותחל תוקף הדין, מכות חמו­רות ביותר, וכמפורש בדברי ההתראה (כנ\"ל) \"בפעם הזאת אני שולח את כל מגפותי אל לבך גו' בעבור הראותך גו'\", ולאידך, היתה הקלה במכה זו שלא מצינו באף אחת משאר המכות — שניתנה אפשריות להנצל מן המכה<sup data-n=\"347\">37</sup>, על ידי",[["340","31","בא יא, ד."],["341","32","וראה גם מלאכת הקודש ובאר יצחק על פרש\"י כאן."],["342","33","דבנוגע להד\"ה י\"ל שזה שייך לתוכן פי' הא' — \"כהחלק הלילה\"."],["343","34","ט, כד."],["344","35","דבברד נאמר (ט, כג) \"והוי'\", שפירושו \"הוא וב\"ד\" (רש\"י וירא יט, כד: כל מקום כו'. וכן בפרש\"י בא יב, כט)."],["344","35","דבברד נאמר (ט, כג) \"והוי'\", שפירושו \"הוא וב\"ד\" (רש\"י וירא יט, כד: כל מקום כו'. וכן בפרש\"י בא יב, כט)."],["346","36","משפטים קטז, רע\"א. וע\"פ מ\"ש במאו\"א מע' כותל (כ, טז). ע\"ש."],["347","37","אף שלפרש\"י (משא\"כ לרמב\"ן ט, ג) גם בדבר הי' כן (ראה לעיל הערה 27) — אינו דומה, כי כאן הרי מלכתחלה התרה אותם משה (ט, יט) \"ועתה שלח העז גו'\", שביקש אותם שיצילו א\"ע ממכה זו. וראה פענח רזא (ועוד מפרשים) עה\"פ (ט, כז) חטאתי הפעם."]]],[1301470113,"הניסה אל הבתים, וכמפורש \"הירא את דבר ה' גו' הניס גו' אל הבתים\"<sup data-n=\"335\">26</sup>.\nויש לומר, שהענין של חיבור שני הפכים מודגש גם בכללות תוכן פרש\"י זה — \"כעת הזאת למחר, שרט לו שריטה כו'\", שבזה ההדגשה (כנ\"ל בארוכה) איך שהקב\"ה כיוון את הרגע ממש של התחלת המכה: המכות באו משם הוי', כמפורש כמה פעמים<sup data-n=\"349\">38</sup> בהמכות שעל ידם ידע פרעה (והמצרים) ש\"אני הוי'\", וכמפורש במכת ברד גופא<sup data-n=\"350\">39</sup>, \"והוי' נתן קולות וברד גו'\" — והרי \"שם הוי' מורה שהוא למעלה מן הזמן שהוא הי' הוה ויהי' ברגע א'\"<sup data-n=\"351\">40</sup>, וביחד עם זה באה מכה זו בתכלית הדיוק של זמן מוגבל, באותו הרגע ממש, חיבור של למעלה מזמן וזמן.\n<span data-k=\"q\">(משיחות ש\"פ וארא וש\"פ בא תש\"מ)</span>",[["335","26","ט, כ."],["349","38","פרשתנו ז, ה. ז, יז. ח, יח. ועוד."],["350","39","ט, כג."],["351","40","תניא שער היחוד והאמונה פ\"ז (פב, א), ע\"פ רע\"מ פינחס (רנז, סע\"ב)."]]],[1301470114,"<h3>שיחה א</h3>\nא. בסיפור מכת חושך נאמר בכתוב<sup data-n=\"352\">1</sup> \"ויט משה את ידו גו' ויהי חושך אפילה בכל ארץ מצרים שלשת ימים. לא ראו איש את אחיו ולא קמו איש מתחתיו שלשת ימים ולכל בני ישראל הי' אור במושבותם\". ואי' במדרש רבה<sup data-n=\"353\">2</sup> \"ובג' ימי אפלה נתן הקב\"ה חן העם בעיני מצרים<sup data-n=\"354\">3</sup> והשאילום שהי' ישראל נכנס לתוך בתי­הן של מצרים והי' רואין בהן כלי כסף וכלי זהב ושמלות<sup data-n=\"355\">4</sup> אם היו אומרים אין לנו להשאיל לכם היו ישראל אומרים להן הרי הוא במקום פלוני, באותה שעה היו המצריים אומרים אם היו אלה רוצים לשקר בנו היו נוטלין אותן בימי החושך ולא היינו מרגישין שהרי ראו אותן כבר אחר שלא נגעו חוץ מדעתנו כמו כן לא יחזיקו והיו משאילין להן, ל­קיים מה שנאמר<sup data-n=\"356\">5</sup> ואחרי כן יצאו ברכוש גדול, הה\"ד ולכל בני ישראל הי' אור וגו', בארץ גושן לא נאמר אלא במושבו­תם שכל מקום שהי' יהודי נכנס הי' אור נכנס ומאיר לו מה שבחביות ובתיבות ובמטמוניות\".\nוכן איתא (בקיצור) בתנחומא<sup data-n=\"357\">6</sup> \"וכן במצרים הענן מאיר לישראל ומחשיך למצרים שנאמר לא ראו וגו' ולכל בני ישראל הי' אור והי' מאיר לישראל ו­מראה להן כל כלי כסף וזהב ושמלות וכל טוב מצרים ומה שבתיבות ובחביות ובמטמוניות הי' מראה להן והיו שואלין ונותנין להן בעל כרחן שהיו אומרים להם ישראל הרי לך במקום פלוני כלי כך וכך\".\nתוכן דרש זה הובא בקיצור בפרש\"י<sup data-n=\"358\">7</sup> \"ולמה הביא עליהם חושך שהיו. . ועוד<sup data-n=\"359\">8</sup> שחפשו ישראל וראו את כליהם וכשיצאו והיו שואלין מהן והיו אומרים אין בידינו כלום אומר לו אני ראיתיו בביתך ובמקום פלוני הוא\".\nוהנה לפום ריהטא נראה, שכוונת רש\"י לפרש הכתוב כמו בפירוש ה­מדרש, דזה שבנ\"י ראו את כלי המצריים",[["352","1","פרשתנו י, כב­כג."],["353","2","שמו\"ר פי\"ד, ג."],["354","3","לשון \"ובג' ימי אפילה נתן הקב\"ה חן העם. . והשאילום\" — אין הכוונה שזה הי' בג' ימי אפי­לה, אלא בתר הכי, וכמובן מהמשך לשון המדרש, והכוונה ב\"ובג' ימי אפילה\" היא — שע\"י (מה שארע ב)ג' ימי אפילה נתן הקב\"ה כו', וכמ\"ש במפרשי המדרש (וכן צריך לפרש לשון התנחומא (וארא יד בסופו) \"אם היו אומרים אין לנו להשאיל הי' מאיר הקב\"ה את המקום שהיו שם והי' אומר לו כו'\" — ראה עץ יוסף שם). וכבר העירו שבמדרש לקח טוב (כאן ולקמן יא, ב) מפורש שלקחו בג' ימי אפילה (וכפשטות לשון התנחומא). וצ\"ע. ואכ\"מ."],["355","4","ראה פרשתנו יב, לה (ובפרש\"י)."],["356","5","לך טו, יד."],["357","6","פרשתנו ג. וראה גם תנחומא וארא שם."],["358","7","פרשתנו שם, כב."],["359","8","ולא כתב ע\"ז \"ורבותינו דרשו\" וכיו\"ב, והיינו שזהו ענין המובן ומוכרח ע\"פ פשוטו של מקרא. וגם לא כתבו בתור פירוש שני (\"ד\"א\"), אלא \"ועוד\" — כי לפרש\"י היתה מכת חושך בגלל שני הטעמים. וראה בארוכה במפרשי רש\"י כאן (וראה גם יפה תואר (השלם) לשמו\"ר שם), שמפרשים שב' הטעמים הם על ב' אופני החושך, טעם הא' ברש\"י הוא על ג' ימים הראשונים שלא ראו איש את אחיו, וטעם הב' על ג' ימים אחרים שהי' חושך כפול ומכופל שלא קמו איש מתחתיו. ואכ\"מ."]]],[1301470115,"הוא פירוש הכתוב \"ולכל בני ישראל הי' אור במושבותם\"<sup data-n=\"360\">9</sup>.\nאבל דוחק גדול לפרש כן כוונת רש\"י, כי:\nא) הדיוק הנ\"ל שבמדרש, \"בארץ גושן לא נאמר אלא במושבותם, שכל מקום שהי' יהודי נכנס הי' אור נכנס כו'\", אינו פשטות הפירוש של \"במושבותם\" (ואדרבה, זהו היפך פירוש הפשוט)<sup data-n=\"361\">10</sup>, ואם רש\"י ס\"ל הכי הו\"ל לכתוב זאת בפירוש.\nב) ועיקר: רש\"י כתב פירושו על התיבות (בפסוק כב) \"ויהי חושך אפילה גו' שלשת ימים\", כטעם למכת חושך — \"ולמה הביא עליהם חושך\" — ולא הזכיר כלל בפירושו את התיבות (מהכתוב שלאח\"ז — פסוק כג) \"ולכל בני ישראל הי' אור במושבותם\".\nומשמע מזה, שלפי פרש\"י היו כאן שני ענינים שונים: א) \"ולכל בני ישראל הי' אור במושבותם\" — שבזה מדובר (כ­פשטות משמעות הלשון) ע\"ד בתי ישראל (שבארץ גושן)<sup data-n=\"361\">10</sup>. ב) זה שבנ\"י \"ראו את כליהם\" של המצרים בבתי המצרים — ודבר זה נלמד (לא ממ\"ש \"ולכל בנ\"י הי' אור במושבותם\", כי אם) מעצם מכת חושך, כיון שזו היתה כוונת המכה, כדי שבנ\"י יוכלו לראות את כליהם ולשאול אותם אח\"כ מהמצריים בעת יציאתם ממצרים.\nב. לפי הנ\"ל נמצינו למדים, שיש חילוק עיקרי בין המדרש ופרש\"י ב­פירוש הכתובים כאן:\nלהמדרש, מ\"ש \"ולכל בני ישראל הי' אור במושבותם\" — גם זה הוא חלק מ­מכת חושך, כי המכה כללה שני פרטים: (א) חושך (נסי) למצרים, (ב) אור (נסי<sup data-n=\"363\">11</sup>) לישראל, \"שכל מקום שהי' יהודי נכנס הי' אור נכנס ומאיר לו כו'\".\nמשא\"כ לפרש\"י הי' כאן רק נס אחד — החושך שהביא הקב\"ה על המצרים, אלא שהטעם שהביא עליהם מכה זו הי' בשביל בנ\"י, שע\"י החושך ניתנה היכולת לבנ\"י לחפש בבתי המצרים ולראות מקום כליהם, אבל לא הי' בזה נס נוסף שבנ\"י יוכלו לראות מה שנמצא בבתי המצריים.\n[ומה שהכתוב ממשיך אח\"כ \"ולכל בנ\"י הי' אור במושבותם\", הוא ענין בפ\"ע, שבא להדגיש שהמכה היתה רק במצרים ולא במקום מושב בנ\"י בארץ גושן. כלומר: זה שלא החשיך לישראל בבית המצרי ה\"ז חלק ממכת חושך, כי זהו המכוון והמטרה של המכה; משא\"כ הכוונה במ\"ש \"ולכל בנ\"י הי' אור במוש­בותם\" היא, אדרבה, להודיע שלא הי' שום רושם מהחושך במושבות בנ\"י. וע\"ד מ\"ש במכת ברד<sup data-n=\"364\">12</sup> \"רק בארץ גושן אשר שם בני ישראל לא הי' ברד\", אף שלכ­אורה פשוט הוא בלאה\"כ, שהרי המכה הי' רק על מצרים<sup data-n=\"365\">13</sup>].\nוחילוק זה בין המדרש ופרש\"י מוד­גש ומדוייק בשינויי הלשונות שביניהם:",[["360","9","ראה ביאורי מהרא\"י על פרש\"י כאן."],["361","10","ראה מדרש שכל טוב כאן (כג) \"ולכל בני ישראל הי' אור במושבותם היינו גושן ופשטי' דקרא הוא אבל רבותינו דורשין כו'\". ועד\"ז הוא בפי' ר\"י בכור שור \"בארץ גושן שהם יושבין\" (אלא שמוסיף \"אבל ארץ מצרים היתה חשוכה לכל העולם אפילו לישראל ורבותינו אמרו כו'\". ואכ\"מ). וראה גם אברבנאל כאן."],["361","10","ראה מדרש שכל טוב כאן (כג) \"ולכל בני ישראל הי' אור במושבותם היינו גושן ופשטי' דקרא הוא אבל רבותינו דורשין כו'\". ועד\"ז הוא בפי' ר\"י בכור שור \"בארץ גושן שהם יושבין\" (אלא שמוסיף \"אבל ארץ מצרים היתה חשוכה לכל העולם אפילו לישראל ורבותינו אמרו כו'\". ואכ\"מ). וראה גם אברבנאל כאן."],["363","11","ראה פי' מהרז\"ו לשמו\"ר שם."],["364","12","וארא ט, כו. משא\"כ במכת ערוב ודבר נאמר \"והפליתי ביום ההוא גו'\" (שם ח, יח), \"והפלה ה' בין מקנה ישראל גו'\" (שם ט, ד)."],["365","13","וראה תפארת יונתן כאן (פסוק כג). ועצ\"ע."]]],[1301470116,"במדרש הלשון שהאור הי' \"מאיר ל­ישראל ומראה להן. . מה שבתיבות ובחביות ובמטמוניות\", ואילו בפרש\"י (א) לא נזכר כלל שהי' כאן איזה \"אור\" (ורק הזכיר ע\"ד ראיית בנ\"י, \"ראו את כלי­הם\"), (ב) מדייק שבנ\"י \"חפשו\" — דלא כבמדרש, שהאור הי' \"מראה להן\", (ג) משמיט שבנ\"י ראו את הכלים ש\"בתיבות ובחביות ובמטמוניות\".\nוע\"פ הנ\"ל מובן טעם השינויים ב­פשטות:\nלהמדרש ש\"ולכל בנ\"י הי' אור ב­מושבותם\" הוא חלק מהנס, א\"כ הי' זה אור מיוחד ונסי שהי' \"מראה להן. . מה שבתיבות ובחביות ובמטמוניות\", וע\"ז אינו מספיק אור טבעי לראות על ידו מה שנמצא בתוך הכלים ו(כ\"ש) במט­מוניות, אלא הי' אור מיוחד ונסי<sup data-n=\"363\">11</sup>.\nמשא\"כ ע\"פ פשוטו של מקרא (דרך רש\"י בפירושו עה\"ת) לא הי' כאן אור נסי, כ\"א רק שהחושך לא החשיך לבנ\"י, ובמילא היו יכולים לראות מה שיש ב­בתי המצרים (באור רגיל וטבעי)<sup data-n=\"367\">14</sup>, ולכן הוצרכו לחפש וכו' עד שראו את כלי המצריים (ועפ\"ז יש לומר, שאפשר שלא מצאו בנ\"י את כל הכלים שהיו טמונים במטמוניות כו').\n[ועפ\"ז יש לבאר עוד שינוי בין ה­מדרש ורש\"י: ברש\"י מפורש שזה שבנ\"י היו נכנסים לבית המצרים ורואים את כליהם, הי' (אחד) מהטעמים למכת חושך<sup data-n=\"368\">15</sup>, משא\"כ מלשון המדרש משמע שאין זה הטעם למכת חושך, אלא דבר נוסף שאירע בשעת מכת חושך<sup data-n=\"369\">16</sup>. וע\"פ הנ\"ל יש לבאר הטעם, כי להמדרש שהי' אור נסי שהראה לישראל את כל כלי המצרים, אין צורך (כ\"כ) להביא עליהם חושך, כי גם אם הי' אור אצל המצרים, היו ישראל רואים את כלי מצרים על ידי אור נסי זה<sup data-n=\"370\">17</sup>; משא\"כ לפרש\"י שלא הי' אור נסי, הרי האפשרות לראות כלי המצרים היתה רק מצד החושך שהביא הקב\"ה על המצרים].\nג. ויש לבאר טעמו של רש\"י ששינה מדרשת המדרש, ובהקדים:\nידוע שבקיום ציווי הקב\"ה, יש ל­השתדל שהקיום יהי' בדרך הטבע, לא ע\"י נס, היינו הן שהחפץ שבו נעשית ה­מצוה יהי' חפץ טבעי ולא מעשה נסים<sup data-n=\"371\">18</sup>, והן שהמעשה דקיום המצוה ייעשה ב­דרך הטבע.\nויתירה מזו נת' במ\"א בארוכה<sup data-n=\"372\">19</sup>, שזה כולל לא רק קיום המצוה עצמה, אלא",[["363","11","ראה פי' מהרז\"ו לשמו\"ר שם."],["367","14","ראה בחיי כאן (פסוק כא בסופו): והי' אור לישראל מפני שלא נסגרו להם שבילי האור כו'. ולהעיר ממושב זקנים שם בסופו \"אע\"פ שהי' חושך למצרים ממונם הי' נראה היכן הוא שהרי המכות לא הי' אלא בשביל גופם שילקו אבל בשביל ממונם לא הי' כו'\"."],["368","15","דהרי הטעם השני \"ועוד\" בא גם בהמשך ותירוץ על השאלה \"ולמה הביא עליהם חושך\" (כנ\"ל הערה 8)."],["369","16","הן בשמו\"ר שם, שענין זה הוא כעין מאמר בפ\"ע \"ובג' ימי אפילה נתן הקב\"ה כו'\", ואי\"ז בהמשך לתחילת הפיסקא \"חושך למה הביא כו'\". ועד\"ז בתנחומא וארא שם, שענין הנ\"ל בא לאחרי סיום הטעמים לכל המכות. ובתנחומא פרשתנו שם ליתא בכלל התחלה זו \"חושך למה הביא כו'\"."],["370","17","ובפרט ע\"פ פי' מהרז\"ו במדרש שם שאין זה ע\"פ אור טבעי אלא אור תורה ודעת רוה\"ק, שעפ\"ז נמצא שלא היו צריכים בכלל ליכנס לבתי המצרים \"לראות\" כליהם."],["371","18","להעיר ממפרשים (מצפה איתן ועוד) לתוד\"ה חטין (מנחות סט, ב). כלי חמדה פ' ויקהל (לה, כז­כח). ועוד."],["372","19","לקו\"ש ח\"ה ע' 80 ואילך."]]],[1301470117,"גם ההכנה למצוה, שגם ההכנה צריכה להיות טבעית. וכפי שלמדים מהספור הידוע<sup data-n=\"373\">20</sup> אודות קידוש לבנה של אדמו\"ר הזקן, שביקש מהפקיד שהי' ממונה על הספינה לעצרה בכדי שיוכל לקדש את הלבנה מעומד ובישוב הדעת, וכאשר הפקיד סירב, עצר אדה\"ז את הספינה בדרך נס, אבל לא קידש אז את הלבנה עד שהפקיד הסכים לעצרה בעצמו — שמהטעמים ע\"ז הוא<sup data-n=\"374\">21</sup>, לפי שרצה שגם ההכנה לקיום המצוה תהי' בדרך הטבע ולא ע\"י ענין נסי<sup data-n=\"375\">22</sup>.\nועפ\"ז יש לבאר מה שלא פירש רש\"י כבמדרש שראיית בנ\"י את כליהם של המצריים היתה ע\"י נס מיוחד (ע\"י אור שלא ע\"פ טבע) — כי לפי דרשה זו, הי' המכוון במכת חושך כדי שיוכלו ישראל לקיים את ציווי ה'<sup data-n=\"376\">23</sup> \"וישאלו איש מאת רעהו ואשה מאת רעותה כלי כסף וכלי זהב\", עד שיהי' \"ונצלתם את מצרים\" — \"ותרוקינון\"<sup data-n=\"377\">24</sup>,\nולפ\"ז נמצא, שההכנה לקיום ציווי זה הי' שלא ע\"פ טבע, בדרך נס, כי רק ע\"י אור נסי זה ראו את כלי כסף וזהב של המצריים ומה שהי' טמון כו', ורק עי\"ז קיימו הציווי לבקש מהם כל כליהם ש­היו במטמוניות וכו'.\nולכן משנה רש\"י ומפרש, שזה שראו את כליהם לא הי' ע\"י אור מיוחד ובדרך נס, אלא ע\"פ טבע, שחפשו ישראל בבתי המצריים וראו את כליהם באור טבעי, בכדי שגם ההכנה להמצוה תתקיים ב­דרך הטבע.\n[ואף שכל עיקר הנס של מכת חושך הי' בשביל זה שישראל יוכלו לראות את כלי המצרים — הרי זה רק בגדר ד­הסרת המניעה, או לכל היותר באופן של סיבה וגרם, ולא הכנה והכשרה להמצוה, שזה הי' דוקא בזה שבנ\"י חפשו וראו את כליהם, ובכגון דא — אין זה שלא ע\"פ טבע.\nוגם דבר זה יש ללמוד מהסיפור הנ\"ל של אדה\"ז, דלכאורה זה שהפקיד הסכים לעצור את הספינה — לא הי' מחמת עצמו (ממש), אלא לפי שראה שבכחו של אדה\"ז להעמיד את הספינה מעצמו באופן נסי,\nאלא שזהו רק גרמא בעלמא; ההכנה עצמה, העמדת הספינה בשביל אמירת הברכה דקידוש הלבנה, היתה ע\"י ה­פקיד בעצמו ולא באופן נסי].\nד. אמנם זה שהמדרש לא חש לזה, ומפרש שהי' בזה אור מיוחד ונסי, י\"ל, משום דס\"ל שבנדו\"ד לא הי' צ\"ל כן — ומצד כמה טעמים:\nא) התנאי שקיום המצות צ\"ל בדרך הטבע דוקא, הוא בעיקר במצות של­אחרי מ\"ת [כי זהו ענין עיקרי במ\"ת, ש­המצות יפעלו בגשמיות העולם, בלשון המדרש<sup data-n=\"378\">25</sup> \"עליונים ירדו לתחתונים\", ולכן רוב המצות ככולן הן בדברים גשמיים, ובזה גופא בדרכי הטבע דוקא, כמשנ\"ת במ\"א<sup data-n=\"372\">19</sup>] — משא\"כ בנדו\"ד שמ­דובר קודם מ\"ת.\nב) תוכן הענין ד\"וישאלו איש מאת",[["373","20","לקו\"ד ח\"ד תשנב, ב."],["374","21","לקו\"ד שם תשנג, א."],["375","22","ראה בארוכה לקו\"ש שם, שמטעם זה גם כאשר קיום המצוה קשור עם קשיים לא כדאי להסירם באופן בלתי טבעי — ראה שם לגבי הנהגת ר\"ג (סוכה מא, ב). ועוד."],["376","23","פרשתנו יא, ב. — וראה לקו\"ש חכ\"א ע' 78 ואילך."],["377","24","שמות ג, כב ובפרש\"י. פרשתנו יב, לו."],["378","25","תנחומא וארא טו. שמו\"ר פי\"ב, ג."],["372","19","לקו\"ש ח\"ה ע' 80 ואילך."]]],[1301470118,"רעהו גו'\" אינו (כ\"כ) בגדר של \"מצוה\" וחיוב (של בנ\"י), אלא אדרבה, קבלת שכר (מלמעלה), שעי\"ז נתקיימה הבטחת הקב\"ה \"ואחרי כן יצאו ברכוש גדול\"<sup data-n=\"380\">26</sup>, אלא שהקב\"ה הלביש תשלום שכר זה בדרכי הטבע, על ידי שבנ\"י ישאלו מה­מצרים כלי כסף גו', אבל תוכן הדבר הוא — קבלת שכר מלמעלה.\n[ולכן מצינו שכללות הענין ד\"וישאלו איש מאת רעהו וגו'\" לא הי' תלוי כ\"כ בידי ישראל, אלא בא בדרך נס מל­מעלה, וכמפורש בתחלת הענין<sup data-n=\"381\">27</sup> \"ונתתי את חן העם בעיני מצרים\", וכנאמר ב­כתוב לאח\"ז שהי' בפועל \"ויתן ה' את חן העם בעיני מצרים\"<sup data-n=\"382\">28</sup>; \"וה' נתן את חן העם בעיני מצרים וישאילום\"<sup data-n=\"383\">29</sup>].\nומובן, שבקיום ציווי כזה לא איכפת לן אם ההכנה נעשית ע\"י נס.\n[ויש להוסיף עוד, שבנדו\"ד הי' מוכ­רח (לדעת המדרש) הנס להאיר את ה­\"מטמוניות\" — כי תכלית ומטרת הציווי \"וישאלו גו'\" היתה (לא רק שבנ\"י יצאו \"ברכוש גדול\", אלא עוד זאת) — \"ונצל­תם את מצרים\", \"ותרוקינון\".\nולכן הי' מוכרח להיות הנס ד\"ולכל בנ\"י הי' אור\", להאיר את המטמוניות שבבתי המצרים, כי דוקא ע\"י אור נסי זה היתה בידם האפשריות לראות כל מה שהי' טמון מכלי כסף וזהב אצל ה­מצריים לקיים מה שנאמר \"ונצלתם את מצרים\" (משא\"כ אם היו רואים רק את הכלים שבחוץ וע\"י שחפשו בבתי ה­מצריים, לא היו יכולים לקיים ציווי זה לרוקן את מצרים)].\nה. לפי זה יש לבאר (ע\"פ פנימיות הענינים) גם החילוק בין המדרש ופרש\"י בפירוש מ\"ש \"ולכל בנ\"י הי' אור ב­מושבותם\" — אם גם זה הוא חלק ממכת חושך או לא:\nאיתא בספרים<sup data-n=\"384\">30</sup> שה\"רכוש גדול\" ש­בנ\"י הוציאו ממצרים מרמז גם על ניצוצות הקדושה שהיו נמצאים בארץ (ועניני) מצרים, דבזה שבנ\"י הוציאו את כלי הכסף וכו' של מצרים, הוציאו את ניצוצות הקדושה (שבהם) מן הרע של מצרים והחזירום לרשות הקדושה.\nותוכן עבודה זו (של \"בירור הניצו­צות\") הוא ענין עיקרי בעבודת כאו\"א מישראל, דנוסף על החיוב של לימוד התורה ועבודת התפלה, שבעיקרם הם בהאדם עצמו, ובזה גופא — ברוחניות שלו (הבנת התורה בשכלו והרגש הלב בתפלה) — צ\"ל גם קיום המצות (שרובן ככולן הם בדברים גשמיים), וכן עשיית דברי הרשות שלו לשם שמים, שעי\"ז ממשיך קדושה בגשמיות העולם ומעלה את ניצוצות הקדושה שבדברים גשמיים לרשות הקדושה (כמבואר בארוכה בספר התניא<sup data-n=\"385\">31</sup>).",[["380","26","להעיר מברכות (ט, א­ב) בפי' הפסוק בפר­שתנו (יא, ב) דבר נא באזני העם וישאלו וגו' \"אין נא אלא לשון בקשה כו' בבקשה ממך לך ואמור להם לישראל בבקשה מכם שאלו כו' שלא יאמר אותו צדיק כו'\" (וראה גם שמו\"ר פ\"ג, יא). משא\"כ ברש\"י, אף שמביא תוכן הנ\"ל שבגמ', משנה מלשון הגמ' וכ' \"בבקשה ממך הזהירם על כך\" (ולא כבגמ' שלשון \"בקשה\" נאמר גם בנוגע לאמירת משה לבנ\"י)."],["381","27","שם ג, כא."],["382","28","פרשתנו יא, ג."],["383","29","שם יב, לו."],["384","30","תו\"א פרשתנו ס, ג — בביאור \"וינצלו את מצרים\" (וראה גם ל\"ת להאריז\"ל ר\"פ תצא). וראה בארוכה לקו\"ש ח\"ג ע' 823 ואילך. וראה בכל הבא לקמן לקו\"ש חכ\"א ע' 15 ואילך."],["385","31","פל\"ז."]]],[1301470119,"וי\"ל, שלפי פרש\"י זהו החילוק בין שני הענינים שבכתוב — (א) עצם מכת חושך, שנתנה את האפשרות לבנ\"י לה­כנס לבתי המצרים ולראות את כליהם, (ב) \"ולכל בנ\"י הי' אור במושבותם\" — שהם כנגד שני סוגי העבודה הנ\"ל: ה­עבודה דתורה ותפלה, שעל ידה מאיר אור הקדושה \"במושבותם\" של בנ\"י (ב­נשמתו ורוחניותו), והעבודה של זיכוך העולם, להוציא את ניצוצות הקדושה שבדברים גשמיים ולהעלותם לקדושה.\nשע\"פ דרך הפשט — היינו כפי שה­דברים נראים בפשטות ובחיצוניות — הרי הם שני סוגי עבודה שונים, ואולי גם סוגים הפכיים.\nאמנם במדרש — אגדה שבתורה ש­\"רוב סודות התורה. . גנוזין באגדות\"<sup data-n=\"386\">32</sup> — מפרש שגם זה ש\"ולכל בנ\"י הי' אור במושבותם\" הוא חלק ממכת חושך, כי מצד הכוונה הפנימית, אין שני סוגי עבו­דה אלה ענינים שונים, אלא הם שייכים וקשורים זב\"ז, כי גם העבודה דתורה ותפלה, תכליתה היא בשביל העבודה של בירור וזיכוך העולם (כמבואר ב­תניא<sup data-n=\"385\">31</sup>, שהנשמה לא ירדה למטה כדי לתקן את עצמה, כ\"א כדי לתקן את הגוף ונפשו הבהמית וחלקו בעולם).\nוזהו התוכן הפנימי בדברי המדרש, שגם זה ש\"לכל בנ\"י הי' אור במושבותם\" הוא חלק ממכת חושך, והיינו מפני שגם האור המאיר לישראל כשהם \"במושבו­תם\", שהוא האור המאיר בנשמתם על ידי תורה ותפלה, צריכים להמשיך ול­הכניס ב\"בתי המצרים\" (חושך העולם), כדי שעל ידו יוכלו להוציא משם את ניצוצות הקדושה הנמצאים שם ולהח­זירם לרשות הקדושה.\nו. ובעומק יותר י\"ל, ע\"פ ה\"יינה של תורה\" שבפרש\"י — דזה שלפי פרש\"י הסיום \"ולכל בנ\"י הי' אור במושבותם\" אינו חלק ממכת חושך, הוא לפי שבזה נרמז ענין גבוה עוד יותר, הבא לאחרי גמר העבודה של בירור וזיכוך העולם.\nדהנה מבואר בכמה מקומות, שירידת הנשמה ועבודתה למטה היא צורך עלי', שלאחרי גמר עבודתה בבירור וזיכוך ה­עולם מתעלית הנשמה למדריגה עליונה יותר מכפי שהיתה קודם ירידתה, ועד שזוכה \"לאשתאבא בגופא דמלכא\"<sup data-n=\"388\">33</sup>.\nוזהו הפירוש הפנימי בכתוב, שלאחרי גמר העבודה בבירור וזיכוך העולם (ש­זה נרמז במכת חושך, שעל ידה הוציאו בנ\"י את רכושם של מצרים והכניסוהו ברשות הקדושה) — זוכים ל\"ולכל בנ\"י הי' אור במושבותם\", שהנשמה באה ל­מושבה ומקומה האמיתי, ישראל וקוב\"ה כולא חד, ששם אין מקום כלל למציאות של מצרים ועניני מצרים (אפילו לא כפי שהם מתבררים ועולים לקדושה)<sup data-n=\"389\">34</sup>, כ\"א רק (בלשון הזהר<sup data-n=\"390\">35</sup>) ישראל ומלכא בל­חודוהי.\nז. ומזה יש ללמוד גם עידוד גדול בעבודתנו עתה, בגלותנו זה האחרון:\nאע\"פ שנמצאים אנו בזמן של \"חושך הגלות\", ובזה גופא — חושך כפול ו­מכופל<sup data-n=\"391\">36</sup> דעקבתא דמשיחא, הרי הקב\"ה מסבב סיבות, ועד לאופנים שלמעלה מן",[["386","32","הל' ת\"ת לאדה\"ז פ\"ב ס\"ב. תניא אגה\"ק סכ\"ג (קלז, א)."],["385","31","פל\"ז."],["388","33","זח\"א ריז, ב."],["389","34","ראה אוה\"ת שמע\"צ ע' א'תתו ואילך."],["390","35","ח\"ג לב, א."],["391","36","כל' השמו\"ר פי\"ד שם. תנחומא וארא יד שם. וראה גם התחלת פרש\"י פרשתנו כאן."]]],[1301470120,"הטבע, כדי שבנ\"י יוכלו לעבוד עבודתם בלי שום מניעות ועיכובים.\nואע\"פ שכל הענינים הנ\"ל צ\"ל בדרכי הטבע דוקא — הרי זה במה שנוגע לקיום המצוה מצד בנ\"י, אבל בנוגע להמצב (בעולם) הנדרש כדי שישראל יוכלו לעבוד עבודתם במילואה, אין שום הגבלות, והקב\"ה עושה גם נסים גלויים כדי לאפשר לישראל לעבוד עבודתם בדרכי הטבע [כמו במכת חושך, שהקב\"ה עשה נס גלוי והביא חושך נסי על המצרים, כדי שבנ\"י יוכלו לחפש ולמצוא הכלים באופן טבעי (מצדם); וכן בסיפור הנ\"ל מאדה\"ז, שפעל על ידי נס, שהפקיד עצמו ירצה לעצור את הספינה].\nועאכו\"כ לפי פירוש המדרש, שהי' כאן גם אור נסי — שודאי גם ענין זה אינו רק דבר חד­פעמי שאירע בגאולת מצרים, אלא מעין זה הוא גם בגאולה מגלות זה האחרון (שהיא \"כימי צאתך מארץ מצרים\"<sup data-n=\"392\">37</sup>), שגם בהיותנו ב\"ארץ מצרים\" (קודם בוא הגאולה) מאיר אור שלמעלה מהטבע, ובלשון הכתוב<sup data-n=\"393\">38</sup> (הו­בא בהמשך הענין במדרש הנ\"ל<sup data-n=\"394\">39</sup>), דגם כש\"החושך יכסה ארץ וערפל לאומים (מ\"מ) ועליך יזרח ה' וגו'\".\nויתירה מזו, אשר אור זה נותן הכח לבנ\"י להפוך לקדושה גם את הענינים שבחושך העולם, אשר בחיצוניות נראה שהם דברים המעלימים ומסתירים ו­מונעים את האדם מלקיים ציוויו של הקב\"ה,\nועד שהם עצמם מסייעים ועוזרים לבנ\"י לקיים ציוויי ה', בדוגמת מה ש­פרעה עצמו סייע ועזר לבנ\"י לצאת מ­גלות מצרים.\nואין מקרא יוצא מידי פשוטו, וזהו העיקר, שבסוף זמן הגלות ישנו \"אור במושבותם\" דכלל ישראל, ובכל אחד ו­אחת מישראל, כפשוטו בגשמיות וברוח­ניות, שיש לכאו\"א מבנ\"י הרחבה ומנוחה בכל עניניו,\nומכינים עצמם מתוך שמחה וטוב לבב לקבל פני משיח צדקנו, בנערינו ו­בזקנינו בבנינו ובבנותינו<sup data-n=\"395\">40</sup> וכספם וזהבם אתם<sup data-n=\"396\">41</sup>, כפשוטו וכן ברוחניות הענינים, בקרוב ממש בעגלא דידן.\n<span data-k=\"q\">(משיחות ש\"פ בא תשמ\"א, ש\"פ ויק\"פ תשמ\"ה)</span>",[["392","37","מיכה ז, טו."],["393","38","ישעי' ס, ב."],["394","39","שמו\"ר שם בסופו (וראה הגהת הרד\"ל שם). וש\"נ."],["395","40","פרשתנו י, ט."],["396","41","ישעי' ס, ט."]]],[1301470121,"<h3>שיחה ב</h3>\nא. תנן במס' פסחים<sup data-n=\"397\">1</sup>, שהחגיגה ה­באה עם הפסח \"נאכלת לשני ימים ו­לילה אחד\". ובגמ' שם<sup data-n=\"398\">2</sup>: מתני' דלא כבן תימא דתניא בן תימא אומר חגיגה הבאה עם הפסח הרי היא כפסח ואינה נאכלת אלא ליום ולילה כו' מ\"ט דבן תימא. . ולא<sup data-n=\"399\">3</sup> ילין לבקר זבח חג הפסח זבח חג זה חגיגה הפסח כמשמעו ואמר רחמנא לא ילין.\nאח\"כ ממשיך בגמ' שם: איבעיא להו לבן תימא נאכלת צלי או אין נאכלת צלי כי אקשי' רחמנא לפסח ללינה אבל לצלי לא או דילמא לא שנא ת\"ש הלילה הזה כולו צלי<sup data-n=\"400\">4</sup> ואמר רב חסדא זו דברי בן תימא שמע מינה.\nהרמב\"ם בהל' חמץ ומצה<sup data-n=\"401\">5</sup> כתב (בנוסח \"מה נשתנה\") — \"שבכל הלילות אנו אוכלין כו' והלילה הזה כולו צלי\". והקשה בלחם משנה<sup data-n=\"402\">6</sup>: תימה על דברי רבינו דהוא פוסק בהלכות קרבן פסח<sup data-n=\"403\">7</sup>. . דחגיגה נאכלת לשני ימים ולילה אחד ודלא כבן תימא וא\"כ לדידן ודאי אינה נאכלת צלי. . ולית לן לומר ה­לילה הזה כולו צלי דהא בגמ' אמרו דזהו כדברי בן תימא דס\"ל היקשא וד­חגיגה נאכלת צלי אבל לדידן דחגיגה אינה נאכלת צלי לא מצינן למימר כולו צלי דהא איכא חגיגה.\nובצל\"ח<sup data-n=\"404\">8</sup> תי' שהרמב\"ם ס\"ל שגם ל­רבנן<sup data-n=\"405\">9</sup> החגיגה נאכלת צלי<sup data-n=\"406\">10</sup>, וטעמם מ­שום שמצינו שהכתוב קראה פסח, וכמו שהביא הרמב\"ם<sup data-n=\"407\">11</sup> \"שעל חגיגת ארבעה עשר נאמר<sup data-n=\"408\">12</sup> וזבחת פסח לה\"א צאן ובקר\", אלא שרבנן ס\"ל דלאו לכל מידי איתקש לפסח אלא רק לצלי (שהוא מידי דאכילה)<sup data-n=\"409\">13</sup>.\nב. והנה ההסברה בדעת רבנן שרק לצלי איתקש חגיגה לפסח ולא לכל מידי דאכילה<sup data-n=\"410\">14</sup> (כמו לינה<sup data-n=\"411\">15</sup> \"דאזהרת",[["397","1","פסחים סט, סע\"ב."],["398","2","ע, א."],["399","3","תשא לד, כה."],["400","4","משנה פסחים קטז, ב."],["401","5","פ\"ח ה\"ב."],["402","6","הל' חמץ ומצה שם."],["403","7","פ\"י הי\"ג."],["404","8","לפסחים שם ע, ב (ד\"ה ובזה זכינו). וראה גם צל\"ח שם קטז, א."],["405","9","ויתירה מזו כתב, דהחידוש דר\"ח \"זו דברי בן תימא\" הוא דגם לדידי' נאכלת צלי. ע\"ש."],["406","10","ומה שהרמב\"ם לא כתב מפורש ההלכה ד­חגיגה נאכלת צלי — תי' הצל\"ח (שם ע, ב ד\"ה ועוד אי האי קרא) \"לפי שאין דרכו לכתוב פרטים שלא נזכרו בגמרא בפירוש\". וראה מאירי פסחים שם שהכוונה ב\"כולו צלי\" היא רק על הפסח. וברבינו מנוח לרמב\"ם שם (ועד\"ז בהגה\"מ שם אות ב) דלענין שתהא נאכלת צלי קיי\"ל כוותי' (דבן תימא) דהא סתם לן תנא כוותי'. וראה (וכן בהבא לקמן) אנציקלופדי' תלמודית ערך חגיגת ארבעה עשר. וש\"נ."],["407","11","הל' ק\"פ שם הי\"ב."],["408","12","פ' ראה טז, ב."],["409","13","ובצל\"ח שם (קכ, א לתוד\"ה מפטירין) כ' דלרבנן יש בחגיגה גם משום שבירת העצם כיון שגם זו היא (ב)מידי דאכילה."],["410","14","ולהעיר דבצל\"ח שם ע, ב (הנ\"ל הערה 10) כתב דלדעת הרמב\"ם להכי קראה פסח (שתהא נאכלת צלי ו)להיות זמן שחיטתה אחר התמיד כמו פסח."],["411","15","דאף שיש לימוד ע\"ז — ראה צל\"ח שם (קטז, א. קכ, א) — מ\"מ צריך ביאור מהי ההסברה בזה."]]],[1301470122,"לינה צווי אכילה היא\"<sup data-n=\"412\">16</sup>) — י\"ל לכ­אורה:\nהטעם שהחגיגה באה עם הפסח הוא \"כדי שיהא פסח נאכל על השובע\"<sup data-n=\"413\">17</sup>, ונמצא שהחגיגה הוי כטפל ומכשיר לפסח<sup data-n=\"414\">18</sup> ולפיכך איתקש חגיגה לפסח; אמנם מהאי טעמא רק אכילה זו של החגיגה הבאה לפני (וכהקדמה ל)אכילת הפסח הוקשה לפסח ונגררת בתר אכילת הפסח, ולכן נאכלת צלי כמוהו; משא\"כ לאחרי גמר אכילת הפסח שוב אין ה­חגיגה טפל לפסח, ולא הוקשה לו.\nועפ\"ז יש לומר לכאורה, דרבנן ובן תימא פליגי בגדר הדין<sup data-n=\"413\">17</sup> ד\"חגיגה ה­באה עם הפסח נאכלת תחילה כדי שיהא פסח נאכל על השובע\":\nלדעת בן תימא, מה שאמרו שע\"י ה­חגיגה ה\"פסח נאכל על השובע\" הוא טעם לא רק על הקדמת אכילת החגיגה לאכילת הפסח, אלא גם על כל עיקר הבאת החגיגה בי\"ד, שהטעם להבאת חגיגה בי\"ד הוא רק כדי שיהא הפסח נאכל על השובע<sup data-n=\"416\">19</sup>, ונמצא שכל עיקרו של הקרבן אינו אלא מכשיר להפסח, ו­לכן ס\"ל לבן תימא שבכל מעשה הקרבן איתקש לפסח (\"כולהו מילי דפסח אתיין בחגיגה בההוא היקשא\"<sup data-n=\"417\">20</sup>);\nאבל לדעת רבנן, הטעם ד\"כדי שיהא פסח נאכל על השובע\" הוא (כפשטות לשון הברייתא) רק על הקדמת אכילת החגיגה לאכילת הפסח, אבל לא על עצם הקרבת החגיגה<sup data-n=\"418\">21</sup>. ולכן יש בחגיגה זו שני דינים: עצם הקרבן יש עליו שם חגיגה ודיני חגיגה; ורק במעשה ה­אכילה שלו, ובזה גופא — רק באכילה הבאה כהקדמה לאכילת הפסח — יש בו דין הכשר למעשה אכילת הפסח, ולענין זה הוקש לפסח, ולכן חלים אז על החגיגה דיני אכילת הפסח (שצ\"ל צלי).\nאבל קשה לבאר כן פלוגתת בן תימא ורבנן — כי מפשטות לשון הגמ'<sup data-n=\"413\">17</sup>, \"וב­מועט (שהי' הפסח מועט לאכילת בני החבורה<sup data-n=\"420\">22</sup>) מיהו מ\"ט אתיא כדתניא חגי­גה הבאה עם הפסח נאכלת תחילה כדי שיהא פסח נאכל על השובע\", משמע, שכל עיקר הבאת החגיגה הוא רק כדי שיהא הפסח נאכל על השובע (וכן מפו­רש בתוס'<sup data-n=\"421\">23</sup> ועוד ראשונים<sup data-n=\"422\">24</sup>, דהא שחגי­",[["412","16","ל' רש\"י שם ע, א ד\"ה למידי דאכילה."],["413","17","פסחים ע, רע\"א. וראה לשון הרמב\"ם הל' ק\"פ פ\"ח ה\"ג."],["414","18","להעיר מדעת ר\"י במשנה פסחים (קכא, א) בירך ברכת הפסח פטר את של זבח (חגיגת י\"ד), וההסברה בזה (להירושלמי (בסוף המסכת), הובא בתוד\"ה כשתמצי לומר בסופו בשם ר\"ח כהן. וראה גם פרש\"י ותוס' זבחים לז, א ד\"ה תרי תנאי), כי ברכה על העיקר (פסח) פוטר את הטפל (זבח). וראה צל\"ח במשנה שם ד\"ה פוטרת בסופו, שהרמב\"ם סובר כפירושו של רבינו חיים שהביאו התוס' כו'. וראה הדרן על מס' פסחים (הדרן הא' שנדפס ב­הגש\"פ עם לקוטי טעמים מנהגים וביאורים (בהוצאת תשמ\"ו ושלאח\"ז — ע' תנט ואילך))."],["413","17","פסחים ע, רע\"א. וראה לשון הרמב\"ם הל' ק\"פ פ\"ח ה\"ג."],["416","19","בתוס' (ותוס' הרשב\"א) פסחים ע, א (ועד\"ז בתוס' חגיגה ח, א ד\"ה אלמא) דלבן תימא הוי חובה מדאורייתא. ועד\"ז הוא בראב\"ד הל' חגיגה פ\"ב ה\"י. אבל ראה כס\"מ ולח\"מ הל' חגיגה שם, דלהרמב\"ם אפי' לבן תימא דאית לי' מקרא דהוי כפסח דרחמנא אקשי' יכולין אנו לומר דהוי רשות. וראה לקמן הערה 24."],["417","20","ל' רש\"י פסחים שם ד\"ה ש\"מ כולהו."],["418","21","ולכאורה כן משמע מלשון הרמב\"ם שב­הערה 17."],["413","17","פסחים ע, רע\"א. וראה לשון הרמב\"ם הל' ק\"פ פ\"ח ה\"ג."],["420","22","ל' רש\"י ד\"ה ובמועט — שם סט, סע\"ב (במשנה)."],["421","23","שם ד\"ה לאו חובה (בתחלתו). וכ\"ה בתוס' הרשב\"א (להר\"ש משנץ) שם."],["422","24","ראה מאירי למשנה פסחים שם: אע\"פ שעלי' נא' בתורה וזבחת פסח. . אינה מצוה לעצמה אלא כדי שיהא הפסח נאכל אכילת שובע מפני שהפסחים לא היו באים אלא זכר ושה תמים בן שנה<sup data-n=\"e12\">*</sup> ולא היו מצוים מהם כ\"כ כו' ומתוך כך רמזה תורה להקריב שלמי חגיגה שתצטרף עם הפסח כו'. — אבל ראה לעיל הערה 21 בדעת הרמב\"ם."],["e12","*","מזה משמע שדברי המאירי הם רק (ל­הלכתא) אליבא דרבנן, ולא לבן תימא שס\"ל (שם ע, א) שגם חגיגה באה רק מאלו."]]],[1301470123,"גת י\"ד לאו חובה היא היינו ש\"אינה באה אלא כדי שיאכל הפסח על השובע\"). וא\"כ גם לדעת רבנן כל עיקר הבאת החגיגה הוא רק הכשר להפסח (ולא רק מעשה אכילה שלה דליל ט\"ו).\nועוד זאת: עצם ההסברה הנ\"ל (בדעת רבנן) שאכילת החגיגה היא \"מכשיר\" לאכילת הפסח — אין בו טעם מספיק לכאורה שיחול עלי' גדר של פסח עד כ\"כ שיהי' חיוב לאכלה צלי דוקא כמו הפסח עצמו. ועכצ\"ל דזה שנאכל צלי הוא לא רק משום שיש על החגיגה שם \"מכשיר\" לפסח, אלא (כמ\"ש הצל\"ח כנ\"ל) משום שהחגיגה עצמה נקראת בשם פסח (\"וזבחת פסח\").\nומכיון שגם לדעת חכמים גוף הקרבן נקרא בשם פסח — טעמא בעי, מדוע חלים עליו דיני הפסח רק לגבי צלי?\nג. ויש לומר הביאור בזה — בהקדם ביאור שיטת הרמב\"ם בדין הסיבה:\nבדין הסיבה בליל פסח כתב ה­רמב\"ם<sup data-n=\"423\">25</sup> \"בכל דור ודור חייב אדם ל­הראות את עצמו כאילו הוא בעצמו יצא עתה משעבוד מצרים כו' לפיכך כש­סועד אדם בלילה הזה צריך לאכול ו­לשתות והוא מיסב דרך חירות\". ובסוף הלכה שלאח\"ז<sup data-n=\"424\">26</sup>, לאחרי שמבאר פרטי דיני הסיבה (מי חייב בהסיבה, ואופן ה­הסיבה), כ' \"ואימתי צריכין הסיבה ב­שעת אכילת כזית מצה ובשתיית ארבע כוסות האלו\".\nועדיין צריך הסברה: מדוע מחלק הרמב\"ם הענין לשתי הלכות נפרדות [הלכה אחת — \"כשסועד אדם בלילה הזה צריך לאכול ולשתות (סתם) והוא מיסב דרך חירות\", והלכה שני' — \"ואי­מתי צריכין הסיבה בשעת אכילת כזית מצה כו' ושאר אכילתו כו'\"] ובמילא גם מאריך — לכאורה הו\"ל לקצר ולכתוב תיכף בהלכה הראשונה \"לפיכך כשסועד בלילה הזה צריך להסב בשעת אכילת כזית מצה כו'\" (וכיו\"ב)?\nונתבאר בזה במקום אחר<sup data-n=\"425\">27</sup>, שלפי שיטת הרמב\"ם יש בהסיבה שני דינים: א) מצוה כללית בפ\"ע, שהאדם צריך להראות בליל פסח הנהגה דרך חירות, ע\"י אכילה ושתי' בהסיבה (ובזה אין נפק\"מ באיזו אכילה ושתי' מדובר<sup data-n=\"426\">28</sup>). ב) פרט ותנאי במצות אחרות (אכילת מצה וחיוב שתיית ד' כוסות) — שאחד מתנאי מצות (וחיובים) אלה הוא שצ\"ל דרך הסיבה.\nוזהו החילוק בין שתי ההלכות: ב­הלכה הראשונה — הבאה בהמשך להל­כה שלפנ\"ז ד\"בכל דור ודור חייב אדם להראות את עצמו כאילו הוא בעצמו יצא עתה משעבוד מצרים כו' (וממשיך) לפיכך כשסועד אדם בלילה הזה צריך",[["423","25","הל' חו\"מ פ\"ז ה\"ו­ז."],["424","26","ה\"ח."],["425","27","ראה בארוכה לקו\"ש חי\"א ע' 15 ואילך."],["426","28","בל' הרמב\"ם (כנ\"ל) \"לאכול ולשתות\" (סתם). — ורק בסוף ה\"ח מפרט דב\"שאר אכילתו ושתייתו אם היסב ה\"ז משובח ואם לאו אינו צריך\" (דהיינו, שגם מצד החיוב הכללי דהסיבה אא\"פ לחייבו להסב בכל הסעודה, וכשמיסב באכילת מצה ושתיית ד' כוסות יצא י\"ח)."]]],[1301470124,"לאכול ולשתות והוא מיסב דרך חירות\" — כוונת הרמב\"ם לחיוב הסיבה כשל­עצמה; וב(סיום) ההלכה שלאח\"ז (לאחרי שפירט פרטי הדינים של חיוב הסיבה) כותב הרמב\"ם \"ואימתי צריכין הסיבה\", שכוונתו בזה היא לדין השני בחיוב הסיבה, מה שהסיבה היא (לא חיוב כללי בפ\"ע, אלא) תנאי במצות אחרות של לילה זה (במצות אכילת מצה וחיוב שתיית ד' כוסות).\nושני דינים אלו בחיוב הסיבה מוד­גשים עוד יותר בלשונו הזהב של אדמו\"ר הזקן בשו\"ע שלו — שלשונו ו­סידור דבריו בנדו\"ד הוא ע\"ד לשון ה­רמב\"ם:\nבתחלה מבאר<sup data-n=\"427\">29</sup> \"ויכין מקום מושבו שישב בהסיבה דרך חירות כדרך שה­מלכים והגדולים אוכלים לפי שבכל דור ודור חייב האדם להראות א\"ע כו' לפיכך צריך לעשות כל מעשה לילה זה דרך חירות\". ולאחר כמה סעיפים (בפי­רוט כמה דיני הסיבה) ממשיך ומבאר<sup data-n=\"428\">30</sup> הדברים הצריכים הסיבה \"אימתי צריך להסב בשעת אכילת כזית. . מצה כו' אכילת הכריכה כו' אפיקומן כו' שתיית ד' כוסות (ומבאר הטעם) לפי שכל דברים אלו הם זכר לגאולה ולחירות כו' לפיכך הם צריכין הסיבה דרך חירות\".\nאשר מזה מוכח, שבהסיבה ישנם שני חיובים וגדרים: (א) מצוה בפ\"ע, שזהו מ\"ש בסעיף שלפנ\"ז \"שישב בהסיבה דרך חירות כו' לפי שבכל דור ודור כו' לפיכך צריך לעשות כל מעשה לילה זה דרך חירות\". והיינו שזהו חיוב כללי ל­התנהג בדרך חירות בזה הלילה; ואח\"כ מפרט (ב) הדברים ש\"הם צריכין הסיבה דרך חירות\", היינו שזהו (לא קיום החיוב של הסיבה בפ\"ע, אלא) פרט ותנאי בדברים אחרים (וכדיוק לשונו \"לפיכך הם צריכין הסיבה דרך חירות\" — ולא כתב \"לפיכך צריך להסב בהן\" וכיו\"ב).\nד. ומכל זה למדנו, שלשיטת ה­רמב\"ם הסיבה היא א) חיוב כללי בפ\"ע, שהאדם צריך להסב \"דרך חירות\" (וכ­לשון אדה\"ז הנ\"ל \"יכין מקום מושבו שישב בהסיבה דרך חירות כדרך שה­מלכים והגדולים אוכלים\"), ב) הסיבה נעשית תנאי במצות אחרות של פסח, באופן, שע\"י אכילת מצה (לדוגמא) בה­סיבה, מקיימים בזה שני דינים: (א) ה­חיוב הכללי דהסיבה. (ב) קיום מצות אכילת מצה בשלימות.\nוהנה לכאורה יש לעיין מהי הסברא וההכרח לחדש שהסיבה הוא גם תנאי ופרט בשאר מצות ליל פסח, ולא לומר שיש חיוב כללי של הסיבה, אלא ש­חכמים תקנו שהזמן המתאים ביותר לקיום חיוב זה הוא בשעת קיום מצות מסוימות (אחרות) של לילה זה?\n[ובפרט שמצות אלו אין עיקר ענינם \"להראות\" חירות, כי אף ש\"דברים אלו הם זכר לגאולה ולחירות\" — מ\"מ, אין גוף מעשה המצוה (בדברים אלו) פעולה המורה על חירות<sup data-n=\"429\">31</sup>. ולדוגמא — אכילת מצה, דהגם שטעם אכילתה הוא מפני שמצה הוי זכר לגאולת מצרים (ש\"לא יכלו להתמהמה גו'\"<sup data-n=\"430\">32</sup>), הרי פשוט שאין במעשה אכילת המצה ענין המורה על \"דרך חירות\" (כמו בפעולת ההסיבה, שעצם ההסיבה מורה על הנהגה של בן",[["427","29","סתע\"ב ס\"ז."],["428","30","שם סי\"ד."],["429","31","וכדיוק ל' אדה\"ז שם \"שכל דברים אלו הם זכר לגאולה ולחירות\"."],["430","32","פרשתנו יב, לט. וראה פ' ראה טז, ג. פסחים קטז, ב (במשנה). רמב\"ם הל' חו\"מ פ\"ז ה\"ה."]]],[1301470125,"חורין, וכדרך מלכים וגדולים), ואדרבה — מצה היא לחם עוני<sup data-n=\"431\">33</sup>].\nויש לומר, שיסוד שיטת הרמב\"ם הנ\"ל בגדר דין הסיבה (דרבנן) הוא — דין (תורה) \"צלי\" שבקרבן פסח (דכל דתקון רבנן כעין דאורייתא תקון<sup data-n=\"432\">34</sup>). וכ­דלקמן.\nה. בדין צלי דפסח כתב הרמב\"ם<sup data-n=\"433\">35</sup> \"כשאדם אוכל את הפסח חותך הבשר ואוכל וחותך כו' וכשיגיע לגיד הנשה מוציאו ומניחו עם שאר הגידים וה­עצמות והקרומות שיוצאין בשעת אכילה שאין מנקין אותו. . ואין מחתכין אותו אלא צולין אותו שלם\" (והראב\"ד פליג \"אין איסור גדול מזה שיצלה הפסח עם גיד הנשה ועם שמנו כו'\").\nוצ\"ע, שהרי לכאורה כל דין צליית פסח הוא קשור באכילתו, \"ואכלו את הבשר בלילה הזה צלי גו'\"<sup data-n=\"434\">36</sup>, וא\"כ הוי כל כולו פרט באכילת הפסח<sup data-n=\"435\">37</sup>, ומה ענין לציווי שיהא צולין אותו (שלם — גם) עם הגיד כו' שאינו שייך לאכילה?\nומוכח מזה דעת הרמב\"ם, שדין צלייתו לא הוי (רק) פרט באכילת הפסח, אלא שהוא חלק מעשיית הפסח<sup data-n=\"436\">38</sup>.\n[ויש לומר שיסודו הוא מזה שהתורה קבעה פרטי דינים באופן מעשה הצלי' — \"צלי אש ראשו על כרעיו ועל קרבו\"<sup data-n=\"437\">39</sup>, שמזה משמע, ד\"צלי גו'\" הוא לא רק פרט באופן אכילת הפסח, אלא דמעשה הצלי' עצמו הוי דין ומצוה ב­פ\"ע במעשה הקרבן].\nויש לומר ההסברה בזה: בס' החי­נוך<sup data-n=\"438\">40</sup> מבואר, ד\"זה שנצטוינו לאכול צלי דווקא\" הוא \"לפי שכך דרך בני מלכים ושרים לאכול בשר צלי שהוא מאכל טוב ומוטעם כו' ואנו שאוכלין הפסח לזכרון שיצאנו לחירות כו' ודאי ראוי לנו להתנהג באכילתו דרך חירות ו­שררות\".\nועפ\"ז י\"ל שהרמב\"ם ס\"ל, שהחיוב לאכול צלי יש בו שני ענינים: א) אחד מתנאי מצות אכילת הפסח. ב) חלק מהחיוב הכללי ד\"חייב אדם להראות את עצמו כאילו הוא בעצמו יצא עתה משעבוד מצרים\"<sup data-n=\"439\">41</sup> — ע\"י שעושה \"כל<sup data-n=\"440\">42</sup> מעשה לילה זה דרך חירות\", והרי אכילת בשר צלי מורה על \"דרך חירות ושררות\". ומטעם זה יש בגוף מעשה הצלי' חשיבות בפ\"ע ועד שחלים עליו דינים מיוחדים (שאינם נוגעים לאכילת הפסח, וכנ\"ל מרמב\"ם שצולין הגיד) — מכיון שענין ה\"צלי\" הוא לא (רק) פרט ותנאי במצות אכילת הפסח, אלא יש בו (גם) ענין בפ\"ע — להראות על ענין החירות (שהוא ענין וחיוב כללי בפ\"ע בלילה זה).\nונמצא, שדין צלי מלמדנו, שהתורה",[["431","33","פ' ראה שם. ונפק\"מ להלכה — ראה רמב\"ם הל' חו\"מ פ\"ה ה\"כ. פ\"ו ה\"ה."],["432","34","פסחים (ל, ב. לט, ב. קטז, ב) וש\"נ."],["433","35","הל' ק\"פ פ\"י הי\"א."],["434","36","פרשתנו יב, ח."],["435","37","וכן משמע ברש\"י פסחים מא, סע\"ב ד\"ה אין לי (ומתורצת קושיית המהרש\"א בפרש\"י שם)."],["436","38","ולהעיר שלדעת הרמב\"ם במו\"נ (ח\"ג פמ\"ו) טעם אכילת צלי הוא כי כשם שהמצה למהירות כך הצלי למהירות ואין שם שהות לעשות מטעמים ולתקן תבשילים (והובא בחינוך שבהערה 40 כטעם נוסף) — והרי טעם זה אינו על אכילתו אלא על עשייתו צלי."],["437","39","פרשתנו יב, ט."],["438","40","מצוה ז."],["439","41","ל' הרמב\"ם (הובא בתחלת ס\"ג) — ממשנה פסחים קטז, ב."],["440","42","ל' אדה\"ז (הובא לעיל ס\"ג)."]]],[1301470126,"קבעה המעשה של \"דרך חירות\" דלילה זה באופן, דנוסף לזה שהחיוב ד\"חירות\" (לעשות פעולות המורות (\"להראות\") על \"דרך חירות\") הוא ענין כללי בפ\"ע, הרי כלל זה נעשה גם תנאי ופרט בפרטי מצות החג (שמצ\"ע אינם באים להראות חירות)\n— וכהדין ד\"צלי\" שהוא תנאי ב­אכילת הפסח, דעצם המעשה דאכילת בשר הפסח אין בו משום מעשה ד\"דרך חירות\" [דהקרבן הוא רק זכר לגאולת מצרים באופן ד\"פסח ה'\"<sup data-n=\"441\">43</sup>, אבל אין מעשה אכילת הבשר פעולה המורה על \"דרך חירות\" (ע\"ד הנ\"ל ס\"ד בנוגע ל­אכילת מצה)] — וחידשה התורה, שגם אכילה זו צ\"ל באופן של \"דרך חירות ושררות\", צלי.\nומזה למד הרמב\"ם גם לענין דין \"דרך חירות\" דרבנן — חיוב הסיבה — דעם היותה חיוב כללי בפ\"ע, קבעוה חכמים באופן שתיעשה תנאי במעשה המצות דלילה זה, כנ\"ל בארוכה.\nו. ע\"פ כהנ\"ל יש לבאר גם שיטת הרמב\"ם בחגיגת ארבעה עשר:\nאכילה \"על השובע\" היא אכילה חשו­בה, \"כדרך שהמלכים אוכלין\"<sup data-n=\"442\">44</sup>; ונמצא שדין אכילת הפסח \"על השובע\" הוא חלק מזה שאכילתו צ\"ל באופן ד\"דרך חירות ושררות\".\nועפ\"ז מובנת גם הסברא לחלק בין דין צלי לשאר תנאי הפסח (ולומר דהא דאיתקש חגיגה לפסח הוא רק לגבי דין צלי): מכיון שכל עיקר הבאת החגיגה שייך לענין זה שבאכילת הפסח, מה שצ\"ל (\"על השובע\" —) \"דרך חירות ושררות\", לכן חל עלי' גם דין \"צלי\" שבאכילת פסח, שגם טעמו הוא \"כדרך שהמלכים אוכלין\"<sup data-n=\"443\">45</sup>. משא\"כ שאר פרטי הדינים שבפסח, שאינם שייכים לענין ה­חירות שבו, אינם שייכים לענין החגיגה.\nומכיון ששיטת הרמב\"ם בדין \"דרך חירות\" דלילה זה היא, שאינו רק חיוב כללי בפ\"ע, אלא שהתורה קבעה \"דרך חירות\" גם בשאר מעשי הלילה (שמצ\"ע אינם פעולות של \"דרך חירות\"), ס\"ל דגם לרבנן חל על החגיגה — הבאה ב­לילה זה בשביל הפסח — החיוב ד\"דרך חירות\" (צלי), ומהאי טעמא קראה התורה את החגיגה בשם \"פסח\" (\"וזבחת פסח\").\n[ופלוגתת בן תימא ורבנן היא: לדעת בן תימא אא\"פ לחול על קרבן שאין עליו שם פסח גדר של \"חירות\", ולכן ס\"ל דכי אקשי' רחמנא חגיגה לפסח",[["441","43","פרשתנו יב, כג. וראה שם, כז. רמב\"ם הל' חו\"מ פ\"ז ה\"ה ממשנה פסחים שם. חינוך מצוה ה. ז."],["442","44","רש\"י פסחים פו, רע\"א. רשב\"ם שם קיט, ב ד\"ה כגון ארדילאי (וראה גם קרית ספר לרמב\"ם סוף הל' חו\"מ). וכבר שקו\"ט דה\"ז \"חובת כל הקר­בנות\", כדברי רש\"י ורשב\"ם שם. ולהעיר שבפרש\"י בהסוגיא כאן (ע, רע\"א) כ' \"על השובע שיהו נהנין באכילתו ותיחשב להן\" (ולא כמ\"ש רש\"י שם פו, א). וראה גם פרש\"י שם סט, סע\"ב במשנה \"כדי שיהא פסח גמר שביעתן ותיחשב להן אכילה\".\nוראה רי\"פ פערלא לסהמ\"צ להרס\"ג עשין מז מח מט (ע' 432) השינוי בפסח לגבי שאר קדשים. אנציקלופדי' תלמודית ערך אכילת פסחים. וש\"נ. ואכ\"מ."],["443","45","עפמ\"ש בחינוך (מצוה טז) שגם טעם מצות שבירת עצם בפסח \"מן השורש הנזכר שאין כבוד לבני מלכים ויועצי ארץ לגרר העצמות ולשברם ככלבים ולא יאותו לעשות ככה כ\"א לעניי העם הרעבים כו'\" — יש לבאר גם הא דלדעת התוס' (לפי' הצל\"ח שם, הנ\"ל הערה 13) יש גם בחגיגה משום שבירת עצם. אבל מובן שאינו דומה לענין אכילת צלי דהוי מעשה חיובי ד\"דרך חירות ושררות\" דבני מלכים ושרים."]]],[1301470127,"נעשה כחלק מגוף הפסח<sup data-n=\"444\">46</sup> וכל דיניו כ­פסח<sup data-n=\"445\">47</sup>; אבל לרבנן, הדין דמעשה חירות חל (גם) על \"כל מעשה לילה זה\", גם במצות דהחג שמצ\"ע אינן פעולות של דרך חירות (ועד שנעשה תנאי וחלק ב­מצות מצה ושתיית ד' כוסות, כנ\"ל). וכן בנוגע לחגיגת י\"ד, שהדין דאכילת צלי (אכילה \"דרך חירות\") חל גם על קרבן שאינו פסח, דאף שיש לו דין ושם בפ\"ע (חגיגת ארבעה עשר, \"ונאכלת לשני ימים ולילה אחד ככל זבחי שלמים\"<sup data-n=\"446\">48</sup>) חל עליו, בו דין מעשה חירות ונאכלת צלי כקרבן פסח.\nויש לקשר זה עם שתי הדיעות<sup data-n=\"447\">49</sup> — דון מינה ומינה, דון מינה ואוקי באתרה. ואכ\"מ].\nז. והנה ענין זה שבליל פסח — שיש במעשה חירות שבו שני ענינים: (א) כמו שהוא בפ\"ע, (ב) כמו שפועל ומשפיע (גם) על ענין אחר שאינו מעשה חירות מצ\"ע — הוא לפי שכן הוא בכללות יחס תוכן ענין (זכירת) יציאת מצרים לכללות התורה ומצוותי'.\nוהביאור: כתב החינוך<sup data-n=\"448\">50</sup> בנוגע לס­פור יציאת מצרים ש\"הוא יסוד גדול ועמוד חזק בתורתינו ובאמונתינו\" (ולכן \"אינו מן התימה אם באו לנו מצות רבות ע\"ז מ\"ע ומל\"ת\"). ותפס כאן שני לשונות — יסוד ועמוד, המורים על ב' ענינים: יסוד יש בו מעלה על עמוד, להיותו היסוד שעליו עומד הבנין כולו ובהבטל היסוד בטל כל הבנין, משא\"כ עמוד ש­לכאורה ה\"ה רק לתמוך הבנין העומד; אמנם לאידך, הרי היסוד הוא דבר ה­טמון ומכוסה ואינו גוף הבנין עצמו, משא\"כ עמוד הוא גלוי ועומד מבחוץ, והוא חלק מגוף הבנין עצמו.\nוכן הוא היחס דיצי\"מ למצוות שב­תורה:\nלגבי כללות התומ\"צ הרי יצי\"מ היא ה\"יסוד\" שלהם, וכמ\"ש בדיבור הראשון (מצוה ראשונה) דעשה\"ד<sup data-n=\"449\">51</sup> \"אנכי ה\"א אשר הוצאתיך מארץ מצרים\", והיסוד שייך ומייסד כל הבנין; אבל לאידך אי\"ז תוכנם הפרטי (הגלוי) של כל ה­מצות אלא שהוא יסוד שלהם — באופן \"טמון\"<sup data-n=\"450\">52</sup>.\nאמנם ישנם \"הרבה דברים (ש)צוה הקב\"ה לעשות זכר ליצי\"מ. . כגון הפרשת בכורות וכל המועדים\"<sup data-n=\"451\">53</sup>, שבהם הענין דיצי\"מ הוא לא באופן של יסוד אלא באופן של עמוד, כלומר שהוא חלק מתוכן מצות אלו<sup data-n=\"452\">54</sup>, והוא אחד מ\"עמודי\" המצוה.",[["444","46","ועפ\"ז מובן דיוק לשון בן תימא \"חגיגה הבאה עם הפסח הרי היא כפסח\" ואינו מסתפק לומר רק הדין, שנאכלת ליום ולילה כפסח וכיו\"ב, וכן להלן בהברייתא \"חגיגה הבאה עם הפסח הרי היא כפסח באה מן הצאן כו'\". וראה צל\"ח שם ד\"ה הרי היא כפסח."],["445","47","וכמובן גם מהאיבעי' בגמ' שם לדעת בן תימא \"אם יש בה דין שבירת עצם או אין בה משום שבירת עצם אע\"ג דכי אקשי' רחמנא לפסח אמר קרא בו בו ולא בחגיגה כו'\"."],["446","48","רמב\"ם הל' ק\"פ פ\"י הי\"ג."],["447","49","יבמות עח, ב. וש\"נ."],["448","50","מצוה כא."],["449","51","יתרו כ, ב. ואתחנן ה, ו."],["450","52","להעיר גם ממשנ\"ת ע\"ד ב' הענינים שנאמרו בנוגע לחג הפסח — ר\"ה לרגלים (ר\"ה ד, א) וחה\"פ נמשך תמיד (ראה שיחת חה\"פ תש\"ג ע' 75) — ראה בארוכה לקו\"ש ח\"ה ע' 173 ובהערות שם."],["451","53","שו\"ת הרא\"ש כלל כד סי' ב."],["452","54","ע\"ש ברא\"ש שממשיך \"שאין צריך להזכיר בהפרשת בכורות שאנו עושין אותו זכר ליצי\"מ אלא שצוה הקב\"ה לעשות המעשה ומתוך כך אנו זוכרין יציאת מצרים\"."]]],[1301470128,"וכמו מצות הנחת תפילין, שצריך לכוין בהנחת תפילין \"שצונו<sup data-n=\"453\">55</sup> המקום להניח ארבע פרשיות אלו שיש בהן יחוד שמו ויציאת מצרים. . כדי שנזכור יצי\"מ ע\"י נסים ונפלאות שעשה עמנו שהם מורים על יחודו שהוא יחיד ב­עולמו ואשר לו הכח והממשלה בעליו­נים ובתחתונים לעשות בהם כרצונו\".\nדעם היות שאין מהות ותוכן הנחת תפילין מוגבל להענין דיצי\"מ — ואד­רבה: עיקר ענינה הוא שעבוד הלב וה­מוח וכו'<sup data-n=\"454\">56</sup> — מ\"מ, גם הענין דיצי\"מ נעשה \"עמוד\" של מצוה זו, ועד שזוהי אחת מהכוונות דהנחת תפילין, כנ\"ל.\nוי\"ל שבאופן זה בא לידי ביטוי עוד יותר גודל הענין דזכר ליציאת מצרים — אשר לא זו בלבד אשר הוא ענין יסודי וכללי בכללות התומ\"צ, אלא ש­חודר גם בתוך פרטי כו\"כ מצות, ונעשה עמוד של כו\"כ מצות.\nויה\"ר שכימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"455\">57</sup>, בגאולה האמיתית וה­שלימה על ידי משיח צדקנו, ובמהרה בימינו ממש.\n<span data-k=\"q\">(משיחת אחש\"פ תשמ\"ג)</span>",[["453","55","טושו\"ע (ודאדה\"ז) או\"ח סכ\"ה ס\"ה (סי\"א)."],["454","56","שו\"ע (ואדה\"ז) שם."],["455","57","מיכה ז, טו."]]],[1301470129,"<h3>שיחה ג</h3>\nא. בפסוק \"והי' כי ישאלך בנך מחר לאמר מה זאת ואמרת אליו בחוזק יד הוציאנו ה' ממצרים גו'\" (שבסוף פרשת­נו<sup data-n=\"456\">1</sup>) מעתיק רש\"י את התיבות \"כי ישאלך בנך מחר\" ומפרש: יש מחר שהוא עכשיו ויש מחר שהוא לאחר זמן כגון זה וכגון מחר יאמרו בניכם לבנינו דבני גד ובני ראובן [הנאמר בספר יהושע<sup data-n=\"457\">2</sup>, כשחזרו לעבר הירדן לאחרי כיבוש וחלוקת<sup data-n=\"458\">3</sup> ה­ארץ].\nמקורו של פרש\"י זה הוא (לכאורה) במכילתא כאן<sup data-n=\"459\">4</sup>, וז\"ל: יש מחר עכשיו ויש מחר לאחר זמן, מה זאת הרי מחר לאחר זמן, מחר יהי' האות הזה [הנאמר לעיל<sup data-n=\"460\">5</sup> במכת ערוב] הרי מחר עכשיו, מחר יאמרו בניכם לבנינו הרי מחר ל­אחר זמן.\nוהנה הטעם שהשמיט רש\"י הראי' ש­\"יש מחר עכשיו\" מן הכתוב \"למחר יהי' האות הזה\", לכאורה הוא (כמ\"ש במפר­שים<sup data-n=\"461\">6</sup>) מפני שאין רש\"י זקוק לראי' שיש מחר שהוא עכשיו, שהרי זהו הפירוש הפשוט של \"מחר\" בכל מקום, ועוד, ש­\"עיקר<sup data-n=\"461\">6</sup> הכוונה לפרש כאן מחר שהוא לאחר זמן\".\nאבל עפ\"ז צ\"ע — מדוע מביא רש\"י הקדמה זו (\"יש מחר שהוא עכשיו\") כל עיקר? הרי בהקדמה זו אין חידוש, ו­הול\"ל בקיצור \"יש מחר שהוא לאחר זמן כגון זה וכגון כו'\"?\nולהעיר שלקמן בפ' ואתחנן<sup data-n=\"463\">7</sup> עה\"פ \"כי ישאלך בנך מחר לאמר מה העדות גו'\", כתב רש\"י בקיצור \"כי ישאלך בנך מחר, יש מחר שהוא אחר<sup data-n=\"464\">8</sup> זמן\", מבלי להקדים \"יש מחר שהוא עכשיו\". אלא שי\"ל ששם החידוש הוא להיפך — שיש מחר שהוא בריחוק זמן רב, לאחר כמה דורות, עד שנשכח ענין יצי\"מ<sup data-n=\"465\">9</sup> ושואלים \"מה העדות גו'\".\nב. גם יש לדייק בלשונו של רש\"י בהראי' שמביא ש\"יש מחר שהוא לאחר זמן\" — \"וכגון מחר יאמרו בניכם לבנינו דבני גד ובני ראובן\" — דלכאורה:\nא) ברובם המכריע של הראיות ש­מביא רש\"י לדבריו מפסוק בתנ\"ך, אין דרכו לכתוב באיזה המשך (או באיזה ענין) נאמר הפסוק אלא רק מעתיק לשון הכתוב; ומדוע מדגיש רש\"י כאן שכתוב",[["456","1","יג, יד."],["457","2","כב, כד. וראה שם, כז­כח. — ולהעיר שבדפוס א' וב' וכת\"י רש\"י (שתח\"י) הועתק הכתוב דיהושע בערבוב לשונות פסוקים הנ\"ל."],["458","3","פרש\"י מטות לב, כד."],["459","4","וכן בתנחומא פרשתנו יג."],["460","5","וארא ח, יט (ושם \"למחר\"). ולהעיר שב­תנחומא (וכן ביל\"ש כאן. וראה מכילתא מהדורת האראוויץ) מביא עוד ראי' מ\"מחר אנכי נצב על ראש הגבעה\" (בשלח יז, ט). ועד\"ז במדרש לקח טוב (ובלקח טוב שם משמיט הראי' על \"מחר לאחר זמן\"!). וצ\"ע הטעם שמובאים כתובים אלו דוקא. ואכ\"מ."],["461","6","נחלת יעקב כאן."],["461","6","נחלת יעקב כאן."],["463","7","ו, כ."],["464","8","כ\"ה בדפוס א' ודפוסי רש\"י שלפנינו (ולא \"לאחר\", כפרש\"י (וכן במכילתא) פרשתנו כאן). ובדפוס ב' וכמה כת\"י רש\"י (שתח\"י) \"לאחר\"."],["465","9","אבל ראה לקמן הערה 28. וראה לקמן סעיף ו והערה 41."]]],[1301470130,"זה נאמר גבי \"בני גד ובני ראובן\"<sup data-n=\"466\">10</sup>? ועכצ\"ל שע\"י הוספה זו נתוסף ביאור והבנה בהראי' ש\"יש מחר שהוא לאחר זמן\".\nב) מהו טעמו של רש\"י שהוא מקדים \"בני גד\" ל\"בני ראובן\"<sup data-n=\"467\">11</sup> — והרי ראובן הבכור? וגדלה התמי': רש\"י מהפך סד­רם מכפי שהוא בכתובים דיהושע (שמ­שם ראייתו<sup data-n=\"468\">12</sup>), שהכתוב מקדים בהם — בכל פעם — בני ראובן לבני גד!\nג) מדוע מביא רש\"י הראי' ש\"יש מחר לאחר זמן\" מכתוב זה (\"דבני גד ובני ראובן\"), ולא מפסוק הנאמר לפנ\"ז בספר יהושע<sup data-n=\"469\">13</sup> — \"למען תהי' זאת אות בקר­בכם כי ישאלון בניכם מחר לאמר מה האבנים האלה לכם\"? ויתירה מזו: מהו הצורך להביא לו \"חבר\" מנביאים — ו­הרי יש פסוק מפורש בחומש, בפ' ואת­חנן, כנ\"ל — \"כי ישאלך בנך מחר לאמר מה העדות גו'\" (שפשוטו ש\"מ שכבר נשכחה יצי\"מ, וכמפורש ברש\"י שם כנ\"ל \"יש מחר שהוא אחר זמן\"<sup data-n=\"470\">14</sup>).\n[ואף שראי' זו שבפרש\"י היא היא המובאת במכילתא כנ\"ל — הרי (א) גם במכילתא צריך ביאור טעם הדבר, (ב) נת' כמ\"פ שאין ענינו של רש\"י בפירושו עה\"ת להעתיק דרשות רז\"ל אלא רק כשהן לפי פשוטו של מקרא. ועכצ\"ל שלהבנת פסוק דידן, מוכרח להביא הראי' דוקא מהפסוק דבני גד ובני ראובן].\nגם יש להבין מדוע מעתיק רש\"י בד\"ה גם התיבות \"כי ישאלך בנך\", אף ש(לכאורה) מפרש כאן רק תיבת \"מחר\".\nג. ויובן זה בהקדם משנ\"ת כמ\"פ ע\"ד דרכו של רש\"י בפירושו עה\"ת — ש­סגנונו בפירושו הוא סגנון ברור, שכדי להבינו אין צורך בעיון בהבנת מקורות רש\"י, ועד שהוא מובן גם לתלמיד שאינו שייך אלא להבנת פשוטו של מקרא, שזהו — כדברי חז\"ל במשנתם<sup data-n=\"471\">15</sup> — \"בן חמש למקרא\".\nומזה מובן, דגם כאשר רש\"י משתמש בלשון חז\"ל, כוונתו למשמעות הפשוטה של לשון וביטוי זה, אף שיתכן ולשון זו מתפרשת (במקורה) בחז\"ל באופן אחר.\nועד\"ז בעניננו: מ\"ש רש\"י \"יש מחר שהוא עכשיו\", כוונתו לפשוטה של תיבת \"עכשיו\", היינו שיש \"מחר\" (שאין פירושו יום הבא לאחר יום זה — כ\"א הבא ל­אחרי המאורע, אע\"פ) \"שהוא עכשיו\" ממש<sup data-n=\"472\">16</sup>, מיד ביום זה. דכיון שבא לאחר המאורע שעוסקים בו, ה\"ז \"מחר\"<sup data-n=\"473\">17</sup>.",[["466","10","וגם במכילתא ליתא הדגשה זו."],["467","11","בא' מכת\"י רש\"י שתח\"י — \"דבני ראובן ובני גד\"."],["468","12","ולא מפ' מטות (לב, א ואילך) שמקדים בכל השקו\"ט (לבד מהקדמתה) גד לראובן."],["469","13","ד, ו (ובמצו\"ד שם: ר\"ל לאחר זמן). וכן שם, כא."],["470","14","אלא י\"ל שאינו מביא מפ' ואתחנן כי ה­נושאים בשני הכתובים דומים זל\"ז, ורוצה להביא לו חבר מלשון \"מחר\" בנושא אחר.\nאבל להעיר ממש\"נ לעיל (ויצא ל, לג) \"וענתה בי צדקתי ביום מחר\", שהכוונה \"לאחר זמן\" ולא יום המחר."],["471","15","אבות ספ\"ה."],["472","16","ולהעיר ממדרש לקח טוב כאן \"יש מחר לאחר זמן ויש מחר בקרוב\" (ולא כל' המכילתא — \"עכשיו\"). ועד\"ז הוא ל' הרד\"ק (בס' השרשים מע' מחר): הוא היום שיבא אחר היום שהוא בו, ויש שאינו בקרוב אחר היום כי אם לאחר זמן ברחוק."],["473","17","ראה ראב\"ע כאן: כי מחר חסר אל\"ף והטעם מה שהוא אחר היום. וראה רד\"ק שבהערה הקודמת.\nוי\"ל שאין רש\"י צריך להביא ראי' לפירוש זה — כי זהו תוכן הפשוט ד(חידוש) \"מחר\", לא שבא השמש ואח\"כ זרח השמש, אלא שזהו לאחר המאורע (בו מדובר שאירע היום)."]]],[1301470131,"[וי\"ל דזהו הטעם שלא הביא רש\"י הראי' שבמכילתא ל\"יש מחר שהוא עכ­שיו\" ממש\"נ \"למחר יהי' האות הזה\" — כי במכילתא הכוונה ב\"עכשיו\" היא ליום שלאחריו (ונקרא \"עכשיו\" לגבי \"מחר שהוא לאחר זמן\"), משא\"כ בפרש\"י ה­כוונה היא ש\"יש מחר שהוא עכשיו\" כ­פשוטו, בהווה, ובמילא אין להכתוב \"למחר יהי' האות הזה\" שייכות לכאן].\nולפי זה מתבאר המשך דברי רש\"י: לפי הפירוש הרגיל בתיבת \"מחר\" — יום שלאחרי יום זה — תמוה, מדוע תהי' שאלת הבן \"מחר\" דוקא? אם הבן אינו מבין טעמה של המצוה, מדוע אינו שואל תיכף בשעת מעשה, היום, אלא מחכה עד למחרתו<sup data-n=\"474\">18</sup>?!\nולכן מבאר רש\"י, ש\"מחר\" אין מובנו בכל מקום כפשוטו — מחרת היום — כי יש בו עוד פירושים (המתאימים כל אחד לתוכן הכתוב, הענין שבו נאמר): \"יש מחר שהוא עכשיו\", כלומר, הזמן הבא תיכף לאחרי הדבר או המעשה (שביום זה) — ה\"ז \"מאחר\", \"מחר\"<sup data-n=\"473\">17</sup>; \"ויש מחר שהוא לאחר זמן\" — ביום מימים של­אחריו, או שנים, או דורות העתידים לבא;\nורש\"י ממשיך \"כגון זה וכגון מחר יאמרו בניכם לבנינו דבני גד כו'\", היינו שבנדו\"ד, הפירוש דתיבת \"מחר\" הוא (לא \"עכשיו\" אלא בדוקא) — \"לאחר זמן\", וכמבואר במפרשים<sup data-n=\"476\">19</sup>, ששאלת הבן לא תתכן אלא \"לאחר זמן\", \"דהא (אם מדובר בבן של זמן ותקופה זו הרי) ראה וידע יציאת מצרים וכל המכות ושלא הספיק בצקת להחמיץ<sup data-n=\"477\">20</sup> אלא ודאי מחר הוא לאחר זמן\".\nד. ולפי זה יש לבאר גם מדוע הוצ­רך רש\"י להקדים \"יש מחר שהוא עכ­שיו\" — אף שזה אינו הפירוש ד\"מחר\" בפסוק זה — ובהקדמה:\nנוסף על הקושי הנ\"ל שבפסוק זה — איך מתאים כאן הלשון \"מחר\", יש כאן גם קושי כללי יותר: למאי נפק\"מ הד­גשה זו כאן, ששאלת הבן תהי' \"מחר\"? ובפרט, שתוכן זה — שאלת הבן — כבר מצינו לעיל בפרשה<sup data-n=\"478\">21</sup>, \"והי' כי תבואו אל הארץ גו' ושמרתם את העבודה ה­זאת, והי' כי יאמרו אליכם בניכם מה העבודה הזאת לכם, ואמרתם זבח פסח הוא גו'\" — ושם לא נאמר ששאלת הבן תהי' \"מחר\"; ומדוע כאן מדגיש הכתוב ששאלת הבן \"מה זאת\" תהי' \"מחר\"?\nואין לתרץ כי שם זה מובן מעצמו, כי הכתוב מקדים \"והי' כי תבואו אל הארץ גו'\", ובמילא פשוט שאין המדובר ב­שאלת הבן בזמן יצי\"מ אלא בשאלה \"לאחר זמן\" (כשיבואו אל הארץ)<sup data-n=\"479\">22</sup> ואין צורך לכתוב \"מחר\" — כי גם כאן מפורש (כהקדמה לשאלת הבן) \"והי' כי",[["474","18","ראה — ע\"ד הדרוש — כלי יקר כאן."],["473","17","ראה ראב\"ע כאן: כי מחר חסר אל\"ף והטעם מה שהוא אחר היום. וראה רד\"ק שבהערה הקודמת.\nוי\"ל שאין רש\"י צריך להביא ראי' לפירוש זה — כי זהו תוכן הפשוט ד(חידוש) \"מחר\", לא שבא השמש ואח\"כ זרח השמש, אלא שזהו לאחר המאורע (בו מדובר שאירע היום)."],["476","19","נחלת יעקב כאן. וראה גם עץ יוסף ל­תנחומא כאן. פי' זה ינחמנו ומרכבת המשנה על המכילתא כאן."],["477","20","מלשון זה (דהנח\"י) משמע שמפרש ששאלת הבן היא בעניני פסח. אבל ראה לקמן סעיף ו שע\"פ פשוטו של מקרא קאי במצות בכור. וראה מרכבת המשנה שבהערה הקודמת."],["478","21","יב, כה­כז."],["479","22","כ\"ה בפשטות, שכתוב זה קאי בפסח דורות (שבפסוק שלפנ\"ז) ולא בפסח מצרים (לפני פניו — שם, כא­כג). וראה פרש\"י (שם, כז): על בשורת הגאולה וביאת הארץ ובשורת הבנים שיהיו להם."]]],[1301470132,"יביאך ה' אל ארץ הכנעני גו'\"<sup data-n=\"480\">23</sup>, וא\"כ אין המדובר בשאלת הבן בדור יצי\"מ, והדרא קושיא לדוכתא — מדוע מוסיף הכתוב כאן תיבת \"מחר\"?\nועכצ\"ל שאין כוונת הכתוב בהוסיפו תיבת \"מחר\" כדי להדגיש הזמן, מתי תהי' שאלת הבן (עכשיו או לאחר זמן), אלא לבאר סיבת השאלה.\nהסברת הענין:\nיש שאלת \"בנך\" שסיבתה היא רק — היותו \"בנך\", כלומר, להיותו בן שחסרים לו הלימוד והידיעות, ולכן כשרואה דבר שלא למד טעמו עדיין הרי הוא שואל \"מה זאת\" [אלא שבזה גופא ישנם כמה אופנים ודרגות, וכמו שמביא רש\"י כאן בד\"ה שלאח\"ז ש\"דברה תורה כנגד ארבעה בנים, תם רשע ושאינו יודע לשאול והשואל דרך חכמה\" — אבל הצד השווה בכולם הוא, ששאלותיהם באות משום שהם בנים, שעדיין לא למדו כו'].\nוזוהי הדגשת והוספת התורה כאן \"כי ישאלך בנך מחר\" — שסיבת שאלה זו אינה רק בגלל זה שהוא בן (כהשאלה דלעיל — \"והי' כי יאמרו אליכם בניכם מה העבודה הזאת לכם\"), אלא בעיקר מפני שהמדובר הוא ב\"מחר\"<sup data-n=\"481\">24</sup>: זה ש­נמצאים בזמן אחר ובתקופה אחרת<sup data-n=\"482\">25</sup> הוא הגורם שאלה זו. וכדלקמן סעיף ו.\nה. עפ\"ז מובן הטעם שלא הסתפק רש\"י לכתוב בקיצור \"מחר — לאחר זמן\", אלא מאריך בפירושו: (א) מקדים \"יש מחר שהוא עכשיו\", (ב) מביא ראי' ודוגמא ל\"יש מחר שהוא לאחר זמן\" ממש\"נ ביהושע \"מחר יאמרו בניכם ל­בנינו\", (ג) מוסיף בסוף הראי' \"דבני גד ובני ראובן\":\nהפירוש ב\"יש מחר שהוא לאחר זמן\" אפשר להסבירו בשני אופנים:\nא) גם לפי זה, \"מחר\" הוא מושג ו­שיעור של זמן, אמנם אין זמן זה מוגבל דוקא ליום הבא לאחרי יום זה, אלא הוא כולל כל יום \"מחר\" מימים שיבואו ב­עתיד<sup data-n=\"483\">26</sup>. ב) \"מחר\" אינו מושג הנקבע לפי סדר הזמנים, אלא תלוי ומתייחס לה­נושא שעוסקים בו, שהזמן שלאחר נושא זה נקרא \"מחר\" לגבי הזמן ההווה<sup data-n=\"484\">27</sup>, שלפי זה הכוונה ב\"לאחר זמן\" אינה רק לעתיד סתם, אלא לתקופה חדשה, הבאה לאחרי סיום התקופה שבהווה.\nוי\"ל, שלפירוש רש\"י כאן, התואר \"מחר. . לאחר זמן\" הוא במובן השני — תקופה חדשה לגמרי (וזוהי הסיבה ל­שאלת הבן). ולכן מקדים רש\"י \"יש מחר שהוא עכשיו\" — כדי להוכיח שתיבת \"מחר\" יכולה להתפרש לא רק בתור שיעור של זמן, אלא גם במובן של \"אחר כך\", ובמובן כזה — \"יש מחר שהוא עכשיו\" בהווה (ונקרא \"מחר\" משום שבא לאחר המעשה); שמזה מובן גם בנוגע ל\"יש מחר שהוא לאחר זמן\" — שאין הכוונה רק שהוא ענין של עתיד (סתם), אלא שהוא בא לאחרי (סיום) תקופת ההווה.",[["480","23","יג, יא — וכפירוש הראשון (והעיקרי) ב­פרש\"י. וראה לקמן סעיף ז."],["481","24","ולכן מעתיק רש\"י בהד\"ה גם התיבות \"כי ישאלך בנך\" — להדגיש החידוש בסיבת שאלת הבן שבכתוב זה."],["482","25","וזהו גם מובנו של \"בנך\" בכתוב זה — דור של \"בנך\", דור הבא (ולא \"בנים\" במובן המצומצם)."],["483","26","ראה ל' הרד\"ק שנעתק לעיל הערה 16."],["484","27","וגם \"מחר\" כפשוטו נק' כן מפני שבא \"אחר היום\" (כנ\"ל הערה 17)."]]],[1301470133,"ולכן הביא רש\"י הראי' מהכתוב \"מחר יאמרו בניכם לבנינו דבני גד ובני ראובן\" דוקא (ולא דפ' ואתחנן \"כי ישאלך בנך מחר לאמר מה העדות גו'\", או ממש\"נ ביהושע \"כי ישאלון בניכם מחר לאמר מה האבנים האלה לכם\") — כי דוקא בפסוק זה מודגש ביותר ש­אפשריות אמירה זו היא רק מפני ש­נמצאים בתקופה חדשה לגמרי — \"יאמרו בניכם לבנינו\", דור חדש ומשני הצדדים, ורק משום כך אפשר שתהי' אמירה כזו<sup data-n=\"485\">28</sup>.\nוכמובן מפשטות הסיפור ביהושע שם, שכאשר חזרו בני גד ובני ראובן לעבר הירדן, לאחרי קיום הבטחתם למשה \"ואנחנו<sup data-n=\"486\">29</sup> נחלץ חושים לפני בני ישראל גו' עד התנחל בני ישראל איש נחלתו\", הקימו שם מזבח, והסבירו טעמם לשאר בנ\"י, שזהו \"עד. . בינינו וביניכם ובין דורותינו\"<sup data-n=\"487\">30</sup>, שאם \"מחר<sup data-n=\"488\">31</sup> יאמרו בניכם לבנינו לאמר מה לכם ולה' אלקי ישר­אל, וגבול נתן ה' בינינו וביניכם גו' את הירדן גו'\", יאמרו \"ראו<sup data-n=\"489\">32</sup> את תבנית מזבח ה' אשר עשו אבותינו גו'\" — וחשש זה, ש\"גבול נתן ה' בינינו וביניכם\", אין לו מקום כלל כל משך ימי הדור ההוא, שהרי בני גד ובני ראובן מסרו נפשם בפועל עבור שאר בנ\"י כדי להנחילם את ארצם. ורק בדור שלאח\"ז, כאשר ישנם רק \"בנים\" — \"בניכם\" ו\"בנינו\", אזי יתכן שישכחו מעשיהם של בני גד ובני ראובן ויעלה על הדעת שיש \"גבול\" והפסק בינם ובין שאר ישראל.\nובזה מוסבר ג\"כ דיוקו של רש\"י, שמקדים \"בני גד\" ל\"בני ראובן\" — כי אף שראובן הוא הבכור ונזכר בדרך כלל לפני גד, מ\"מ בענין מסירת נפשם ומלחמתם עבור כל ישראל, קדמו בני גד לבני ראובן [וכמו שהביא רש\"י<sup data-n=\"490\">33</sup> שבני גד היו גבורים \"שכן נאמר בגד<sup data-n=\"491\">34</sup> וטרף זרוע אף קדקד\", וכמשנ\"ת ב­מק\"א<sup data-n=\"492\">35</sup> שבענין המלחמה היו בני ראובן טפלים לבני גד, ולכן מצינו בכ\"מ הלשון \"בני גד ובני ראובן\", שמקדים בני גד לבני ראובן] — וזוהי ההדגשה כאן, דכיון שהמדובר ב\"בני גד ובני ראובן\" שמסרו נפשם עבור שאר ישראל, לכן כל החשש ד\"יאמרו גו'\" שייך רק \"מחר לאחר זמן\" — לאחרי קום דור חדש של בנים שאינם זוכרים מעשה בני גד ובני ראובן, כנ\"ל.",[["485","28","משא\"כ בסיפור דיהושע ע\"ד \"האבנים ה­אלה\" שאין הכרח שמדובר בתקופה חדשה. וראה רד\"ק שם (ד, כא): אשר ישאלון בניכם הנולדים הקטנים ואשר יולדו.\nוכן בפ' ואתחנן, אף שמתוכן הפסוקים שם מובן שהשאלה היא לאחרי כמה דורות, שכבר נשכח ענין יצי\"מ (כנ\"ל ס\"א) — מ\"מ, בתיבות \"כי ישאלך בנך מחר\" עצמן, אין מודגש שמדובר בתקופה חדשה (משא\"כ בכתוב \"מחר יאמרו בניכם לבנינו\", כב­פנים).\nולהעיר, שע\"פ משנ\"ת במ\"א (הובא לקמן הערה 38 בסופה) שאין השאלה \"מה העדות גו'\" בעניני פסח דוקא, אלא בנוגע לכללות ענין התומ\"צ, הרי עיקר סיבת השאלה, לכאורה, היא (לא משום שנשכח ענין יצי\"מ, אלא) מפני שהמדובר בבן שלא למד עדיין כו' ע\"ד תומ\"צ [אלא שבנוגע לדור שנכנס לארץ, גם אצל בניהם לא תתכן שאלה כזו \"מה העדות גו'\", כ\"א רק אצל \"בנך (של) מחר\"]. ואכ\"מ."],["486","29","מטות לב, יז­יח. וראה גם שם, כז. לב."],["487","30","יהושע כב, כז."],["488","31","שם, כד­כה."],["489","32","שם, כח."],["490","33","מטות שם, יז."],["491","34","ברכה לג, כ."],["492","35","לקו\"ש ח\"ט ע' 1 ואילך ובהערות שם. וראה גם לקו\"ש חט\"ו ע' 392 הערה 14."]]],[1301470134,"ו. אמנם לפי זה יש לתמוה, מהו החילוק בין שאלת הבנים לעיל — \"והי' כי יאמרו אליכם בניכם מה העבודה גו'\", והשאלה כאן בסוף פרשתנו \"והי' כי ישאלך בנך מחר לאמר מה זאת\", שדוקא כאן סיבת שאלתו היא — \"מחר\" (היותו בתקופה חדשה)?\nויש לבאר זה בפשטות — על פי ה­חילוק בין תוכן השאלות:\nהשאלה דלעיל היא בנוגע לקרבן פסח, שמקודם ציוותה תורה<sup data-n=\"493\">36</sup> \"והי' כי תבואו אל הארץ גו' ושמרתם את העבו­דה הזאת\" (דהבאת קרבן פסח), וע\"ז ממ­שיך הכתוב<sup data-n=\"494\">37</sup> \"והי' כי יאמרו אליכם בניכם מה העבודה גו' ואמרתם זבח פסח הוא לה' אשר פסח גו'\"; משא\"כ כאן בסוף הפרשה מדובר אודות מצות בכור<sup data-n=\"495\">38</sup>, כמפורש בתחלתה<sup data-n=\"496\">39</sup> \"והי' כי יביאך ה' אל ארץ הכנעני גו' והעברת כל פטר רחם לה' וכל פטר שגר בהמה גו' וכל פטר חמור תפדה בשה גו' וכל בכור אדם בבניך תפדה\", וע\"ז ממשיך הכתוב<sup data-n=\"497\">40</sup> \"והי' כי ישאלך בנך מחר לאמר מה זאת ואמרת אליו בחוזק יד הוציאנו ה' ממצרים גו' ויהרוג ה' כל בכור בארץ מצרים גו' על כן אני זובח לה' כל פטר רחם הזכרים וכל בכור בני אפדה\".\nועפ\"ז מובן גם החילוק בסיבת ה­שאלות:\nהענין דיציאת מצרים (בכלל) לא שייך שישכח מבני ישראל<sup data-n=\"498\">41</sup>, שהרי בכל יום ויום מזכירים וגם עושים כמה עני­נים \"זכר ליציאת מצרים\"<sup data-n=\"499\">42</sup>, והשאלה ד­\"מה העבודה הזאת לכם\" בליל פסח באה מחמת שהמדובר ב\"בן\" שלא למד עדיין וכו';\nמשא\"כ בנוגע למצות בכור יש הבדל באיזה דור המדובר: הדור של יוצאי מצרים, בודאי היו יודעים וזוכרים הצלת הבכורים שביניהם, ולכן כאשר ציווה הקב\"ה<sup data-n=\"500\">43</sup> (ביום ט\"ו ניסן) \"קדש לי כל בכור פטר כל רחם בבני ישראל גו' לי הוא\" — כפרש\"י<sup data-n=\"500\">43</sup> \"קניתים ע\"י ש­הכיתי בכורי מצרים\" — לא הי' אצלם מקום לשאלה, שהרי הם עצמם קנויים להשם, עי\"ז שהצילם ממות; ורק כשיקום דור חדש, שלא היו במצרים, הרי אצלם שייכת השאלה בנוגע למצות בכור — \"מה זאת\", ויש צורך להסבירם, כי היות ש\"ויהרוג ה' כל בכור בארץ מצרים גו'\" — \"על כן אני זובח לה' כל פטר רחם גו'\".\nז. ע\"פ הנ\"ל שכאן המדובר במצות בכור — יש לומר עוד טעם שרש\"י מקדים בתחילת פירושו \"יש מחר שהוא עכשיו\":",[["493","36","יב, כה."],["494","37","שם, כו­כז."],["495","38","במכילתא (סוף פרשתנו), וכן בהגדה של פסח, איתא שגם שאלה זו היא בשייכות לפסח, אבל לפי פשוטו של מקרא אין המדובר בפסח אלא במצות בכור, כבפנים.\nוכ\"ה בתיב\"ע, ספורנו ואוה\"ח [ומסיים: ורז\"ל אמרו כנגד ד' בנים כו' זה דרך דרוש]. וראה גם בארוכה לקו\"ש חכ\"ז ע' 185 ואילך [וראה שם, דכוונת רש\"י כאן (בד\"ה שלאח\"ז) \"דברה תורה כנגד ד' בנים כו'\" אינה לשאלות בעניני פסח, אלא \"דברה תורה\" בכלל (וגם שאלת הבן חכם (בפ' ואתחנן) אינה בעניני פסח). ע\"ש]."],["496","39","יג, יא­יג."],["497","40","שם, יד­טו."],["498","41","היינו אצל האבות, משא\"כ אצל הבנים (דלא כהדור דיוצאי מצרים, שגם הבנים יצאו כו') — ראה לעיל סעיף א."],["499","42","כמו בק\"ש (פ' ציצית)."],["500","43","פרשתנו יג, ב."],["500","43","פרשתנו יג, ב."]]],[1301470135,"עה\"פ<sup data-n=\"502\">44</sup> \"והי' כי יביאך ה' אל ארץ ה­כנעני\" פרש\"י \"יש מרבותינו<sup data-n=\"503\">45</sup> שלמדו מכאן שלא קדשו בכורות הנולדים ב­מדבר, והאומר שקדשו מפרש<sup data-n=\"504\">46</sup> ביאה זו לומר אם תקיימוהו במדבר תזכו ליכנס לארץ ותקיימוהו שם\". והיינו, שלפירוש הא' (והעיקרי) הבכורות שנולדו במדבר לא נתקדשו<sup data-n=\"505\">47</sup> (ובפשטות כוונת רש\"י רק להנולדים במדבר, אבל הבכורים שהיו במצרים ע\"פ פשוטו ש\"מ נתקדשו<sup data-n=\"506\">48</sup>, כמפורש לעיל \"קדש לי כל בכור\" (בלי תנאי \"והי' כי יביאך גו'\"), וכמפורש ברש\"י כנ\"ל \"קניתים ע\"י שהכיתי בכורי מצרים\"<sup data-n=\"507\">49</sup>); אבל יש פירוש שני שגם הנולדים במדבר נתקדשו.\nולדיעה השני' קשה — מדוע נאמר כאן הלשון \"מחר\", דאא\"פ לפרש שה­שאלה היא מחמת שנמצאים בתקופה חדשה, כי תקופת שהותם במדבר אינה תקופה חדשה (ממש), שהרי דור יוצאי מצרים עדיין היו חיים וקיימים<sup data-n=\"508\">50</sup>? ולכן מקדים רש\"י \"יש מחר שהוא עכשיו\", ובזה מרמז רש\"י, שלפי הדיעה שגם הבכורות שנולדו במדבר נתקדשו ואין התחלת מצות בכור לאחרי שיבואו ל­ארץ, מסתבר לפרש \"מחר\" דכאן — \"מחר שהוא עכשיו\"<sup data-n=\"509\">51</sup>, שכשיראו שהאב מקיים מצות בכור<sup data-n=\"510\">*51</sup>, ישאל תיכף לאח­רי זה — \"מה זאת\" (כנ\"ל סעיף ג בפירוש \"יש מחר שהוא עכשיו\").\nח. מיינה של תורה בפרש\"י<sup data-n=\"511\">52</sup>:\nבפרש\"י זה — \"יש מחר שהוא עכשיו ויש מחר שהוא לאחר זמן\" — י\"ל דמ­רומז לשני סוגי \"בנים\" השואלים שאלות \"מחר\". \"בנים\" של \"מחר\" הם בני הדור הבא, ויש בהם שני אופנים: \"יש מחר שהוא עכשיו\" — הוא אמנם בן, מהדור הבא, אבל בתוכן מהותו הרי הוא חי ונמצא \"עכשיו\", כי אינו נפרד מאביו, אלא הוא חי אותם החיים של האב, חיי היהדות, ומהווה המשך (אבל) ישר (\"מחר\") של האב. ובזה אין חידוש, ד­כאשר \"בן\" זה שואל שאלות ביהדות (ל­היותו עדיין במצב של בן) — חייבים להשתדל לענות לו כדי שיוכל לעבוד את ה' בשמחה וחיות.\nאבל — \"יש מחר שהוא לאחר זמן\", בן כזה שאין לו קשר ושייכות לאופי החיים של האב, והרי הוא מ\"תקופה חדשה\", דור חדש \"אשר לא ידע את יוסף\"<sup data-n=\"512\">53</sup>; ומובן שסוג ה\"שאלות\" של \"בן\" זה, אינן",[["502","44","יג, יא."],["503","45","בכורות ד, ב."],["504","46","שם ה, רע\"א."],["505","47","צע\"ק לשון רש\"י, שהרי מפורש (במדבר ג, מ ואילך) \"פקוד כל בכור זכר לבנ\"י מבן חודש ומעלה\", ש\"בן חודש\" אז הרי נולד במדבר (וכ­קושיית הגמ' שם (ד, סע\"ב), ולכן מסיק שהפלוגתא היא רק אם \"קדשו ולא פסקו\" או \"קדשו ופסקו\". ע\"ש)."],["506","48","ראה גם רמב\"ן עה\"ת שם \"ע\"ד הפשט\"."],["507","49","וכמפורש לקמן בפ' במדבר (ג, יב­יג. שם, מ ואילך)."],["508","50","אלא י\"ל דאף שמצות בכור התחילה תיכף במדבר, מ\"מ לא ישאלו הבנים עד ל\"מחר\" — \"לאחר זמן\" (בתקופה חדשה, לאחרי תום כל הדור של יוצאי מצרים)."],["509","51","ולהעיר שבדפוס שני דפרש\"י ליתא התי­בות \"כגון זה\". ועפ\"ז שפיר י\"ל שכוונת רש\"י שכאן יכולים לפרש בשני אופנים."],["510","*51","\"עכשיו\" היינו בעת קיום הציווי במדבר (לא זמן אמירת הציווי, ביצי\"מ)."],["511","52","ראה גם לקו\"ש ח\"ו ע' 268 ואילך."],["512","53","ל' הכתוב — שמות א, ח. וראה שיחת ש\"פ וישב תשמ\"ח השייכות לדורנו בפרט, שנשיא הדור, כ\"ק מו\"ח אדמו\"ר, שמו (הראשון) \"יוסף\". ולהעיר, שהסתלקותו היתה בש\"פ בא (יו\"ד שבט השי\"ת)."]]],[1301470136,"באות רק מחמת חסרון ידיעה, אלא שאופן החיים ע\"פ תורה ומצות בהידור כו' הוא דבר חדש וזר אצלו ואינו לפי רוחו.\nוזוהי הוראת התורה — דגם \"בן\" כזה, מכיון שהוא \"בנך\", הרי זוהי אחריות שלך (וזכותך) לענות על שאלות של בן זה, ולקרבו תחת כנפי השכינה.\nוע\"י שעוסקים עם כל סוגי הבנים של עם ישראל, מעמידים את \"צבאות ה'\"<sup data-n=\"513\">54</sup>, שיזכו בקרוב ממש לגאולה האמיתית והשלימה על ידי משיח צדקנו, כימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"514\">55</sup>, ובמהרה בימינו ממש.\n<span data-k=\"q\">(משיחת ש\"פ בא תש\"ל)</span>",[["513","54","פרשתנו יב, מא. נת' בהמשך ההילולא — באתי לגני השי\"ת — פ\"י ואילך."],["514","55","מיכה ז, טו."]]],[1301470137,"<h3>שיחה א</h3>\nא. תנו רבנן<sup data-n=\"515\">1</sup>. . דרש רבי עקיבא ב­שעה שעלו ישראל מן הים נתנו עיניהם לומר שירה, וכיצד אמרו שירה כגדול המקרא את הלל<sup data-n=\"516\">2</sup> (להוציאן ידי חובתן. רש\"י) והן עונין אחריו ראשי פרקים (הללוי'<sup data-n=\"517\">3</sup>), משה אמר אשירה לה'<sup data-n=\"518\">4</sup> והן אומרים אשירה לה' משה אמר כי גאה גאה<sup data-n=\"518\">4</sup> והן אומרים אשירה לה'. רבי אלי­עזר בנו של ר' יוסי הגלילי אומר כקטן המקרא את הלל<sup data-n=\"516\">2</sup> והן עונין אחריו כל מה שהוא אומר, משה אמר אשירה לה' והן אומרים אשירה לה', משה אמר כי גאה גאה והן אומרים כי גאה גאה. רבי נחמי' אומר כסופר הפורס על שמע בבית הכנסת שהוא פותח תחילה והן עונין אחריו (\"וקורין כולן יחד<sup data-n=\"521\">5</sup>, וכך שרתה רוח הקודש על כולם<sup data-n=\"522\">6</sup> וכוונו יחד את השירה ככתבה\". רש\"י).\nוהיינו, דכו\"ע ס\"ל שמשה התחיל ב­אמירת השירה לפני בנ\"י, וכמובן מלשון הכתוב \"אז ישיר משה ובני ישראל\", ש­הקדימו למשה בפ\"ע<sup data-n=\"523\">7</sup> — והפלוגתא היא באופן המשך השירה ע\"י בנ\"י, דלדעת רע\"ק אמירת (כל) השירה היתה על ידי משה בלבד, ובנ\"י רק ענו \"אשירה לה'\"; לדעת ר\"א גם בנ\"י אמרו כל השירה, אבל לאחרי (ובדרך \"מענה\" ל)אמירת משה; ואילו לדעת ר' נחמי' משה רבינו רק התחיל את אמירת השירה, אבל אח\"כ אמרו \"כולן יחד\" את כל השירה כולה.\nוקמיפלגי בפירוש תיבת \"לאמר\" שב­כתוב (\"אז<sup data-n=\"518\">4</sup> ישיר גו' לאמר\"), כמבואר בגמ' שם \"במאי קמיפלגי — ר\"ע סבר לאמר אמילתא קמייתא ור\"א בנו של ריה\"ג סבר לאמר אכל מילתא ומילתא ור\"נ סבר ויאמרו — דאמור כולהו בהדי הדדי, לאמר — דפתח משה ברישא\". ויש להבין, מהי סברת מחלקותם בפירוש פסוק זה? ועוד, דמזה גופא שהכתוב משמיענו (בתיבת \"לאמר\") אופן אמירת השירה (מה אמר משה ומה אמרו ישראל) משמע שיש בזה נפק\"מ באמירת השירה ותוכנה — וצריך להבין, למאי נפק\"מ ב­תוכן אמירת השירה, כיצד (ובאיזה אופן משלשת אופנים הנ\"ל) אמרו השירה?\nכן צריך ביאור בדעת ר' נחמי' ש­משה רק פתח לבנ\"י, אבל אח\"כ אמרו השירה \"כולן יחד\" — מהו ענינה של \"פתיחה\" זו על ידי משה רבינו?\nלדעת רע\"ק או לדעת ר\"א, י\"ל בפש­טות, כי בנ\"י לא ידעו מעצמם את נוסח",[["515","1","ברייתא סוטה ל, ב (ובמשנה שם כז, ב הובאו רק דעת רע\"ק ודעת ר\"נ).\nוראה (הגירסאות והדיעות) תוספתא שם פ\"ו, ב. ירושלמי שם פ\"ה ה\"ד. מכילתא ויל\"ש פרשתנו עה\"פ (טו, א). ועוד. ואכ\"מ."],["516","2","ראה סוכה לח, ב."],["517","3","כ\"ה בפרש\"י. וראה רש\"י סוכה שם."],["518","4","פרשתנו טו, א."],["518","4","פרשתנו טו, א."],["516","2","ראה סוכה לח, ב."],["521","5","כ\"ה בפרש\"י. ובתוספתא הנ\"ל (הובא ב­תוד\"ה ר\"נ שם) פי' דעת ר\"נ באו\"א. וראה הנסמן בהערה 1. חדא\"ג מהרש\"א סוטה שם. ועוד. ואכ\"מ."],["522","6","כן מפורש במכילתא פרשתנו שם בדעת ר\"נ. וראה הערה 8."],["523","7","ראה שמו\"ר עה\"פ (פכ\"ג, ט בסופו). וראה לקמן ס\"ב דרשת המכילתא."],["518","4","פרשתנו טו, א."]]],[1301470138,"השירה, ולכן היו צריכים לענות אחרי משה<sup data-n=\"525\">8</sup> (אם רק \"אשירה לה'\", או שענו אחריו כל דברי השירה);\nאבל לדעת ר\"נ ש\"שרתה רוח הקודש על כולם וכוונו יחד את השירה ככתבה\", הרי לא הי' צורך לכאורה ל\"פתיחת\" משה כדי שידעו את דברי השירה<sup data-n=\"526\">9</sup> [ולכ­אורה כן מוכרח לומר לפי הדרשות (ש­הובאו בהמשך הגמ' שם<sup data-n=\"527\">10</sup>) שגם העול­לים ויונקים אמרו שירה, ועוד זאת, \"ש­אפילו עוברים שבמעי אמן אמרו שירה\", שבהם לא שייך לומר שידעו לכוון את השירה ע\"י ששמעו אותה ממשה, אלא שזהו ע\"פ רוח הקודש ששרתה עליהם (וכמבואר בגמ' שם<sup data-n=\"528\">11</sup>, שאמירת השירה שלהם היתה תוצאה מראיית השכינה, כי \"ראו את השכינה. . ואמרו כו' כרס נעשה להן כאספקלריא המאירה וראו\")] — ומהו התוכן והמטרה בהפתיחה על ידי משה<sup data-n=\"529\">12</sup>?\nב. עה\"פ \"אז ישיר גו' אשירה לה' ויאמרו לאמר\" מפרש האוה\"ח \"ויאמרו לאמר אשירה — פי' שאמרו זה לזה לאמר, פי' שיאמרו שירה יחד בלא בחי' השתנות והפרדה עד שיהיו כאיש אחד הגם היותם רבים ונתכוונו יחד ועשו כן ואמרו אשירה לשון יחיד<sup data-n=\"530\">13</sup> כאילו הם איש אחד שזולת זה היו אומרים נשירה\".\nזאת אומרת, שאמירת השירה היתה באופן מיוחד במינו, שכל ישראל אמרוה בהשתוות, כאיש אחד ממש, \"בלא. . השתנות והפרדה\". וע\"פ מחז\"ל הנ\"ל ש­גם עוללים ויונקים, ואפילו עוברים שב­מעי אמן אמרו שירה, נמצא, שבאמירת השירה הי' מצב של אחדות גמורה, בלי שום \"השתנות והפרדה\", בין הגדול שב­גדולים והקטן שבקטנים, עד העוברים שבמעי אמן.\nובזה יש לבאר זה שלכו\"ע היתה אמירת השירה של בנ\"י בהקדמת פתיחת משה — כי אחדות מוחלטת כזו, שכל ישראל יהיו כאיש אחד, מהגדולים ועד הקטנים, כולל עוברים שבמעי אמן, יכולה לבוא אך ורק על ידי משה רבינו.\nוהביאור בזה:\nהיות שמשה רבינו הוא ראש הדור",[["525","8","וראה גם מכילתא פרשתנו עה\"פ, שרק בדעת ר\"נ נזכר ש\"שרתה רוה\"ק על ישראל\", משא\"כ בשאר הדעות<sup data-n=\"e13\">*</sup> (וראה חדא\"ג מהרש\"א סוטה שם). אבל עפ\"ז צ\"ל לכאורה דפליגי על הדרשה שגם העוללים כו' ועוברים אמרו שירה (כדלקמן בפנים), ובגמ' ברכות (נ, א) מפורש שר\"ע ס\"ל* כר\"מ שגם העוברים אמרו שירה, ומשמע שם שכ\"ה לכו\"ע (וראה זהר פרשתנו ס, א). — וראה הערה 20."],["526","9","ולהעיר מירושלמי סוטה שם \"מה ת\"ל לאמר (ש\"הרי כולם אמרו שירה מעצמם כמשה\", קה\"ע), לאמר לדורות\" — דלא כבבבלי שמפרש (לדעת ר\"נ) \"לאמר דפתח משה ברישא\". וראה תרגום לשה\"ש בתחלתו: משה עם בנוי דישראל. . פתחו כולהון ואמרו כחדא שירתא."],["527","10","וראה גם תוספתא וירושלמי (ומכילתא) שם."],["528","11","ל, סע\"ב ואילך."],["529","12","בפשטות י\"ל שזהו\"ע של דרך ארץ, שחיכו למשה שיפתח (ראה רש\"י סוטה שם ד\"ה לאמר \"אחר שנרשו לאמר. . אחר שפתח חכם\"). אבל לכאורה אינו ביאור מספיק, כי בשביל זה לא הי' צריך הכתוב להדגיש זאת (ולכאורה דוחק לומר דהא גופא קמ\"ל הכתוב, שצריכים לחכות לפתיחת החכם)."],["530","13","להעיר מרש\"י יתרו (יט, ב) \"כאיש אחד בלב אחד\". וראה לקמן הערה 51."],["e13","*","ולהעיר שבמכילתא הוצאת האראוויץ שם הועתק הלשון \"שרתה רוה\"ק כו'\" גם בדעת רע\"ק."]]],[1301470139,"ונשיא הדור, לכן הרי הוא כולל את כל הדור כאחד, ובלשון רש\"י<sup data-n=\"531\">14</sup> \"משה הוא ישראל וישראל הם משה. . שנשיא הדור הוא ככל הדור כי הנשיא הוא ה­כל\". ואחדות זו דישראל (כפי שהם כלו­לים במשה) הריהי באופן שלמעלה מהת­חלקות, כי הנשיא (כשמו) מנושא ומובדל מן העם, \"משכמו ומעלה גבוה מכל ה­עם\"<sup data-n=\"532\">15</sup>, ולכן, האחדות דישראל כפי שהם כלולים בו היא באופן שלמעלה מהת­חלקות, אנשים נשים וטף בשווה, ע\"ד \"השוה<sup data-n=\"533\">16</sup> ומשוה קטן וגדול\".\nולכן, ע\"י שפתח משה רבינו את שירת בנ\"י, שאמירת השירה שלהם באה על ידו ובכוחו, ה\"ז פעל שאמירת השי­רה ע\"י \"כל הדור\" תהי' בהשתוות גמורה (כפי שהם כלולים במשה<sup data-n=\"534\">17</sup>), כאיש אחד, \"בלא. . השתנות והפרדה\".\nויש לומר, שזוהי כוונת המכילתא עה\"פ \"אז ישיר משה ובני ישראל\" — \"משה שקול כנגד כל ישראל וישראל שקולין כמשה בשעה שאמרו שירה\": כדי לבאר יתור הלשון בכתוב (\"משה ו­בני ישראל\", אף שמשה הוא בכלל בנ\"י) הי' מספיק לכאורה לבאר ש\"משה שקול כנגד כל ישראל\"<sup data-n=\"535\">18</sup>, ומזה שנקט במכיל­תא (לא רק ש\"משה שקול כנגד כל ישר­אל\", אלא) גם ש\"ישראל שקולין כמשה בשעה שאמרו שירה\", משמע, שכוונת המכילתא לפרש שמשה ובנ\"י השתוו ב­אמירת השירה<sup data-n=\"536\">19</sup>. וי\"ל שהשתוות זו באה מצד זה שבנ\"י הרגישו ש\"משה הוא ישר­אל וישראל הם משה\", שכולם נכללים במציאותו של משה (וזהו מה שמאחד אותם בהתאחדות גמורה ועושה אותם ל­מציאות אחת).\nוזוהי כוונת סיום דברי המכילתא \"וישראל שקולין כמשה בשעה שאמרו שירה\", שאמירת השירה על ידי (פתיחת) משה (\"משה הוא ישראל\") פעלה על ישראל שיהיו \"שקולין כמשה\", היינו שהם דומים ומתאחדים באמירת השירה עם משה (כיון ש\"ישראל הם משה\").\nג. ולפי הקדמה זו יש לבאר את שלש הדיעות הנ\"ל באופן אמירת ה­שירה:\nכיון שאמירת השירה היתה צריכה להיות באופן מיוחד, שיאמרוה כולם ב­אחדות גמורה, לכן לכו\"ע (א) פתיחת ה­שירה היתה על ידי משה (הפועל האח­דות וההשתוות דכל ישראל)<sup data-n=\"537\">20</sup>, (ב) אמי­רת השירה עצמה על ידי ישראל היתה באופן שהתאחדו עם (שירת) משה, כי הרגישו שכל מציאותם היא משה, \"ישר­אל הם משה\" (תכלית האחדות דישראל); והפלוגתא היא במידת ואופן שייכות ד­אמירת השירה של ישראל למשה רבינו:",[["531","14","חקת כא, כא."],["532","15","ש\"א ט, ב (וראה שם י, כג). וראה אוה\"ת וירא (כרך ד) תשסד, ב. שה\"ש (כרך ב) ע' תיד ואילך. ועוד."],["533","16","ל' הפיוט \"האוחז ביד\"."],["534","17","ראה גם ש\"ך עה\"ת כאן \"כיוונו למה שאמר משה כי כולם נכללים בו. . שנשמותיהם הם ניצוצות נשמתו\". ולהעיר ממאמרי אדמו\"ר הזקן תקס\"ו ע' קנ. תו\"ח פרשתנו רכו, א­ב."],["535","18","ראה דיעה הב' במכילתא שם \"שאמר משה שירה כנגד כל ישראל\"."],["536","19","ראה גם פי' מרכבת המשנה על המכילתא שם."],["537","20","ע\"פ המבואר בפנים י\"ל, שלכל הדעות אמרו ישראל השירה ברוה\"ק [וכן הובא בסתם ב­שמו\"ר (פכ\"ב, ג. פכ\"ג, ב) עה\"פ ויאמינו בה' (אבל במכילתא עה\"פ הוא מאמר ר' נחמי'). וראה זהר פרשתנו שם. אלשיך וש\"ך עה\"ת כאן] — ומה שענו אחרי משה הוא מפני ביטולם והתאחדותם עם משה, כבפנים."]]],[1301470140,"לדעת רע\"ק אמירת השירה כולה היתה על ידי משה רבינו וישראל רק ענו \"אשירה לה'\", והיינו שכל ישראל \"יצאו\" ידי אמירת השירה באמירת משה<sup data-n=\"536\">19</sup>, ולדעת ר\"ע זוהי שלימות האח­דות, כאשר היא באופן של ביטול גמור עד ש\"יצאו\" בשירת משה (שהם רק \"עו­נין אחריו\"<sup data-n=\"539\">21</sup>), שבזה מודגש שכל מצי­אותם של ישראל אינה אלא מציאותו של משה.\nלדעת ר\"א היו \"עונין אחריו כל מה שהוא אומר\", כי ס\"ל ששלימות ההת­אחדות היא כאשר בנ\"י מרגישים התאח­דות זו גם כפי שהם במדריגתם. דבאופן הנ\"ל שהיו עונין אחריו (רק) \"אשירה לה'\" מודגש שישראל כפי שהם במדרי­גתם (ומצד מציאותם) אינם במצב של אחדות מוחלטת, והאחדות תלוי' בזה שהם רק \"עונין\" אחרי משה בביטול גמור<sup data-n=\"540\">22</sup>; ולכן ס\"ל שאמרו כל השירה כמו משה, אלא שזה גופא הוא באופן של \"מענה\" לאמירת משה, שהיא תלוי' בשירת משה.\nור\"נ ס\"ל שגם שירת בנ\"י יחד באופן של מענה למשה אין בה עדיין תכלית ההתאחדות עד שיורגש בהם ש\"ישראל הם משה\", מאחר שהם רק עונין אחריו. ולכן לדעת ר\"נ אמרוה \"כולן יחד\" בלי שום התחלקות כלל, שזה מדגיש ש\"משה הוא ישראל וישראל הם משה\"<sup data-n=\"540\">22</sup> [אלא שזה גופא נתגלה על ידי שמשה רבינו \"פתח\" באמירת השירה, כנ\"ל].\nד. האחדות של בנ\"י הנפעלת על ידי משה רבינו דוקא, יובן בעומק יותר ב­הקדם תוספת ביאור בגדר \"אחדות ישר­אל\" — וכמשנ\"ת כמה פעמים שיש שני ענינים: א) המצוה היא אהבת ישראל (\"ואהבת לרעך כמוך\"<sup data-n=\"542\">23</sup>), שבזה יש עדיין שני אישים נפרדים, אוהב ואהוב (אלא שהאהבה היא \"כמוך\"); ב) הסיבה ש­אפשר להיות אהבה \"לרעך כמוך\" היא מצד הענין ד\"אחדות ישראל\", שפירושה, שכל ישראל הם מציאות אחת, כאיש אחד ממש.\nובזה גופא יש כמה אופנים (ודרגות):\nבספר התניא<sup data-n=\"543\">24</sup> מבאר רבינו הזקן, ש­אחדותם של ישראל באה מזה שכל ה­נשמות<sup data-n=\"544\">25</sup> \"כולן מתאימות ואב אחד לכו­לנה, ולכן נקראו כל ישראל אחים<sup data-n=\"545\">26</sup> ממש<sup data-n=\"546\">27</sup> מצד שורש נפשם בה' אחד, רק שהגופים<sup data-n=\"544\">25</sup> מחולקים\".\nוהנה בירושלמי<sup data-n=\"548\">28</sup> מבואר ש\"כל ישר­אל גוף אחד הן\"<sup data-n=\"549\">29</sup> (כמובא שם משל לזה",[["536","19","ראה גם פי' מרכבת המשנה על המכילתא שם."],["539","21","להעיר ממשנ\"ת במ\"א (לקו\"ש חכ\"ג ע' 233) לענין אמירת הלל (ע\"י עניית הללוי'), ע\"ש."],["540","22","וי\"ל שר\"ע ס\"ל שאמירת כל השירה ע\"י כל ישראל (בפ\"ע) ממעטת מדרגת האחדות שע\"י אמירה אחת דמשה; ור\"א ס\"ל שאפשר לאחדות זו להתגלות במציאות (ואמירת) בנ\"י, אבל רק כש­נרגש שהיא באה בדרך \"מענה\" לשירת משה; ור\"נ ס\"ל דכיון ש\"משה הוא ישראל וישראל הם משה\", לכן גם באמירתם \"כולן יחד\" נרגשת אחדות מוח­לטת עם שירת משה. וראה לקמן הערה 54 (בלשון החסידות)."],["540","22","וי\"ל שר\"ע ס\"ל שאמירת כל השירה ע\"י כל ישראל (בפ\"ע) ממעטת מדרגת האחדות שע\"י אמירה אחת דמשה; ור\"א ס\"ל שאפשר לאחדות זו להתגלות במציאות (ואמירת) בנ\"י, אבל רק כש­נרגש שהיא באה בדרך \"מענה\" לשירת משה; ור\"נ ס\"ל דכיון ש\"משה הוא ישראל וישראל הם משה\", לכן גם באמירתם \"כולן יחד\" נרגשת אחדות מוח­לטת עם שירת משה. וראה לקמן הערה 54 (בלשון החסידות)."],["542","23","קדושים יט, יח."],["543","24","פרק לב."],["544","25","ראה גם רדב\"ז להל' ממרים פ\"ב ה\"ד."],["545","26","ראה רמב\"ם הל' מתנות עניים פ\"י ה\"ב."],["546","27","ולא רק \"קרובים\" או \"דומין\" (כבפ' לך יג, ח ובפרש\"י)."],["544","25","ראה גם רדב\"ז להל' ממרים פ\"ב ה\"ד."],["548","28","נדרים פ\"ט ה\"ד."],["549","29","ל' הקה\"ע שם. ועד\"ז הוא ברדב\"ז הנ\"ל. אברבנאל יהושע \"פרשה שביעית\". ועוד. וראה תניא אגה\"ק סו\"ס כב (ע\"פ ס' שופטים כ, יא). שם סל\"א. ובארוכה — סהמ\"צ להצ\"צ מצות אהבת ישראל."]]],[1301470141,"מב' ידים של גוף אחד), שלכאורה זהו אופן נעלה יותר באחדות ישראל. כי זה ש\"כל ישראל אחים ממש\" להיות ש\"אב אחד לכולנה\" מורה רק שה\"אב\" (שורש ומקור) שלהם הוא אחד, אבל ישראל עצמם (כפי שהם במקומם) מחולקים זה מזה (\"אב אחד לכולנה\" — רבים), אלא שהם \"כמו אחים ממש\" [דאע\"פ שאהבת אחים אינה כאהבה לאיש זר, אלא היא אהבה עצמית, בלשון הכתוב<sup data-n=\"550\">30</sup> \"עצמי ובשרי אתה\" — מ\"מ הרי הם אישים נפר­דים ומחולקים]; משא\"כ זה שכל ישראל גוף אחד הן, מפני שכל ישראל הם \"קומה אחת שלימה\"<sup data-n=\"551\">31</sup>, אין בהם (גם כפי שהם במקומם) גם ההתחלקות של אחים, אלא הם מציאות אחת, \"גוף אחד\".\nועפ\"ז צריך ביאור: מדוע לא הביא רבינו הזקן בתניא זה שכל ישראל הם \"קומה אחת שלימה\", \"גוף אחד\", וכתב רק ש\"אב אחד לכולנה ולכן נקראו כל ישראל (רק) אחים\"?\nה. ויש לומר הביאור בזה:\nזה ש\"נקראו כל ישראל אחים ממש\" לא הובא בתניא שם כדי להגדיר מהות ודרגת האהבה (שאהבת ישראל צ\"ל כ­אהבת אחים), אלא רק בתור הוכחה לזה ש\"אב אחד לכולנה\" (לכל הנשמות). ולכן לא הביא שם הא ד\"כל ישראל גוף אחד הן\", כי האהבה שעלי' מדובר בתניא שם (הבאה מזה ש\"אב אחד לכולנה\") היא למעלה יותר גם מזה ש\"כל ישראל גוף אחד הן\".\nהסברת הענין: זה שמביא בתניא שם ע\"ד אחדות נפשות ישראל בשרשן ו­מקורן (\"אב אחד לכולנה\") הוא כדי לבאר שהאהבה דישראל במקומם יכולה להיות כתוצאה מהרגש ה\"התאמה\" וה­אחדות (של כל נפשות ישראל) כפי ש­היא מצד \"שורש נפשם בה' אחד\"<sup data-n=\"552\">32</sup>, וכ­דיוק לשון אדה\"ז, ש\"אהבה ואחוה אמי­תית\" באה ע\"י שהאדם (לא רק מגביר נפשו על הגוף, אלא) מגבי' ומעלה את הנפש \"מעלה מעלה עד עיקרא ושרשא כו'\"<sup data-n=\"553\">33</sup>, כי עי\"ז מרגיש שורש נפשו (ה\"אב אחד\").\nופשוט הוא, שהאחדות מצד זה ש\"אב אחד לכולנה\" היא למעלה יותר מה­אחדות ד\"כל ישראל גוף אחד\". שהרי אפילו דרגת האחדות דגוף אחד ממש (לא רק אחים), אינה אחדות מוחלטת, כי גם בגוף אחד ישנה ההתחלקות דאברי הגוף, עד לחילוק מן הקצה אל הקצה — ראש ורגל; משא\"כ כפי שנפשות ישראל כלולות בשרשן ב\"אב אחד\" ה\"ה למעלה מהתחלקות<sup data-n=\"554\">34</sup>; ועאכו\"כ מצד אמיתית שו­רש הנשמה ב\"ה' אחד\"<sup data-n=\"555\">35</sup> (דנשמת כל איש",[["550","30","ויצא כט, יד."],["551","31","לקו\"ת ר\"פ נצבים. ובכ\"מ. — וראה בפרטיות לקו\"ש חלק ל ע' 19­218."],["552","32","ראה ד\"ה אלה תולדות תער\"ב (סה\"מ תער\"ב­ע\"ו ע' נ) \"דמצד שורש נפשם בה' א' גם ב­המשכתם מתאימות הנה\". ע\"ש. וכן משמע מל' כ\"ק מו\"ח אדמו\"ר — בעל ההילולא דיו\"ד שבט — דלקמן הערה 35."],["553","33","וממשיך \"וגם להמשיך אוא\"ס. . במקור נשמות כל ישראל\". ולהעיר ממ\"ש לפנ\"ז \"והנפש והרוח מי יודע גדולתן ומעלתן בשרשן ומקורן כו'\"."],["554","34","ראה תניא פ\"ב שהוא כמו בן הנמשך ממוח האב. ע\"ש."],["555","35","ולא רק \"אב אחד\" — בחי' חכמה, שהוא מקור להתחלקות. וי\"ל שנרמז בל' התניא שם \"ש­כולן מתאימות\" — ראה סה\"מ תרס\"ט (ע' עג) \"ש­מתאימות המה דהיינו בעצם מהותם\", העצם של­מעלה מגילויים. ע\"ש. וראה מכ' כ\"ק מו\"ח אדמו\"ר (קובץ מכתבים לתהלים בתחלתו. אגרות קודש שלו כרך ב' ע' תקכד): \"הנפשות אוהבים זה את זה להיותם אחד ממש מצד העצם דאלקות שהוא ה­עצמות ב\"ה הכוללם וזה הבנת מאמר. . דהנפשות מתאימות\"."]]],[1301470142,"ישראל היא \"חלק אלקה ממעל ממש\"<sup data-n=\"556\">36</sup>), הרי כשם ש\"ה' אחד\" הוא פשוט בתכלית הפשיטות<sup data-n=\"557\">37</sup>, למעלה מכל התחלקות, כן הוא בנוגע לנשמות ישראל (שהם \"חלק אלקה ממעל ממש\"), שענין האחדות \"מצד שורש נפשם בה' אחד\" הוא באופן של נקודה אחת שלמעלה מגדר התחל­קות לגמרי.\nו. והנה הכח לעבודה נעלית כזו, להגבי' ולהעלות את הנפש שתרגיש את שרשה בה' אחד הוא ע\"י דביקות בתל­מידי חכמים, וכמו שביאר רבינו הזקן<sup data-n=\"558\">38</sup> מה שאמרו רז\"ל \"על פסוק<sup data-n=\"559\">39</sup> ולדבקה בו שכל הדבק בת\"ח מעלה עליו הכתוב כאילו נדבק בשכינה ממש\", כי \"על ידי דביקה בתלמידי חכמים\" (שהם \"הצדי­קים והחכמים ראשי בני ישראל שבדו­רם\"<sup data-n=\"560\">40</sup>) מתדבקות נפשות ההמון \"במהותן הראשון ושרשם\" למעלה (כמבואר ב­ארוכה בתניא).\nויש לומר, שבזה גופא יש חילוק בין תלמידי חכמים בכלל (\"ראשי בני ישר­אל שבדורם\") ונשיא הדור (כמו משה רבינו).\nויובן זה בהקדם שמצינו בכמה מקו­מות שה\"מלך\" נמשל ל\"לב\"<sup data-n=\"561\">41</sup> (וכנרמז בלשון הרמב\"ם<sup data-n=\"562\">42</sup> \"לבו (של מלך) הוא לב כל קהל ישראל\"), שהטעם בפשטות הוא, דכשם שחיות כל הגוף תלוי' בלב כך חיות \"כל קהל ישראל\" תלוי' במלך.\nאבל צריך להבין: הלא חיות הגוף תלוי' בעיקר במוח שבראש (שממנו נמ­שכת חיות לכל אברי הגוף, גם להלב<sup data-n=\"563\">43</sup>), וא\"כ למה מדמים מלך ללב ולא למוח?\nויש לומר הביאור בזה<sup data-n=\"564\">44</sup>:\nהמעלה שבהשפעת הלב לאברי הגוף לגבי השפעת המוח אליהם היא — ש­אותה החיות הנמשכת מהלב באבר זה נמשכת גם באבר אחר ובכל האברים, שהרי מהלב נמשך דם לכל האברים (שבו מלובשת חיות הנפש, \"כי הדם הוא הנפש\"<sup data-n=\"565\">45</sup>), והרי בכל האברים נמצא אותו הדם, בלי התחלקות<sup data-n=\"566\">46</sup>; משא\"כ (עיקר) החיות הנשפעת (בגלוי) לאברי הגוף מהמוח שבראש, היא באופן שכל אבר מקבל \"חיות וכח\" השייכים לו \"לפי מזגו ותכונתו, העין לראות והאוזן לשמוע ו­הפה לדבר והרגלים להלוך\"<sup data-n=\"563\">43</sup>.",[["556","36","ל' התניא רפ\"ב (ע\"פ ל' הכתוב איוב (לא, ב), אלא שמוסיף תיבת \"ממש\"). וראה בארוכה שפע טל בהקדמה."],["557","37","ראה רמב\"ם הל' יסוה\"ת פ\"א ה\"ז. שם פ\"ב ה\"י."],["558","38","תניא ספ\"ב."],["559","39","עקב יא, כב. ספרי ורש\"י עה\"פ. כתובות קיא, ב. סהמ\"צ להרמב\"ם מ\"ע ו. הל' דעות פ\"ו ה\"ב. שו\"ע אדה\"ז או\"ח שם ס\"ד. — ולהעיר ממכילתא פרשתנו עה\"פ ויאמינו בה', \"שכל המאמין ברועה נאמן כאילו מאמין במי שאמר והי' העולם\"."],["560","40","ל' התניא שם (ו, סע\"ב)."],["561","41","ראה ס' יצירה (פ\"ו מ\"ב) \"לב בנפש כמלך במלחמה\". בחיי ריש פרשתנו. אברבנאל פ' שופטים בפרשת המלך (בשם הפלוסופים). ועוד."],["562","42","הל' מלכים פ\"ג ה\"ו.\nבפשטות אין כוונת הרמב\"ם לדמות המלך ללב כל קהל ישראל, אלא \"שלבו הוא לב כל קהל ישר­אל\", שלכן \"על הסרת לבו (דמלך) הקפידה תורה\". אבל מזה ש\"הקפידה תורה\" בעיקר בנוגע ללבו של מלך (משום ש\"לבו הוא לב כל קהל ישראל\"), מובן, שעיקר שייכות המלך לכל קהל ישראל הוא בענין הלב."],["563","43","תניא פנ\"א."],["564","44","ראה (באו\"א) לקו\"ש חי\"ט ע' 165 ואילך."],["565","45","פ' ראה יב, כג. ועוד."],["566","46","ראה לקו\"ת במדבר יג, א."],["563","43","תניא פנ\"א."]]],[1301470143,"וזהו הטעם שהמלך נמשל ל\"לב\", כי נוסף לזה שהמלך משפיע לבני המדינה את כל צרכיהם (לכל אחד ואחד לפי ענינו), הרי עיקר ענין המלכות הוא, מה שעצם מציאות המדינה כולה תלוי' בה­מלך<sup data-n=\"568\">47</sup>, כמו הלב המשפיע עצם החיות לכל אברי הגוף.\nויש לומר, שעד\"ז הוא ההפרש ברוח­ניות שבין ראשי אלפי ישראל שבכל דור ודור ונשיא הדור: החיות הרוחנית הנשפעת לכל אנשי הדור על ידי תלמי­די חכמים בכלל, ראשי אלפי ישראל שבכל דור ודור (שהם כמו \"ראש ומוח לגבי נשמות ההמון\"<sup data-n=\"569\">48</sup>), היא בבחי' \"מזון רוחני\" לכל אחד ואחד לפי ערכו; אבל עיקר חידושו של משה רבינו (\"נשיא הדור\") הוא, שממנו נמשך עצם החיות (הרוחני) לכל אנשי הדור, כמו הדם ה­נשפע מהלב<sup data-n=\"570\">49</sup> לכל האברים, כי הוא מגלה אצל ישראל את נקודת היהדות שלהם, שהיא בשווה ממש אצל כל ישראל.\nומזה מובן גם בענין התקשרות נפשות ההמון בשרשן ומקורן: זה שעל ידי ראשי אלפי ישראל בכלל מתקשרות נפשות ההמון לשרשן למעלה, היינו ל­בחי' \"אב אחד לכולנה\", שהתואר \"אב\"<sup data-n=\"571\">50</sup> מורה על השייכות (שורש, מקור) לבנים, והיינו שהוא שורש להתחלקות למטה<sup data-n=\"572\">51</sup>; ואילו משה רבינו (נשיא הדור) מקשר נפשות ישראל בשרשם בה' אחד של­מעלה<sup data-n=\"572\">51</sup> מהתחלקות לגמרי<sup data-n=\"574\">52</sup> (שזה שייך לנקודת היהדות שלהם, שהיא בשווה ממש אצל כל ישראל<sup data-n=\"575\">53</sup>).\nז. ע\"פ כל הנ\"ל מובן גם בעניננו — אמירת שירה ע\"י משה ובני ישראל:\nזה שמשה רבינו \"פתח\" באמירת שירה פעל בכל ישראל אמירת שירה מצד נקודת היהדות שלהם שהיא שווה ממש אצל כל ישראל<sup data-n=\"576\">54</sup>. ולכן גם ה­עוללים ויונקים אמרו שירה, ועוד זאת — גם העוברים שבמעי אמן, כי אמירת שירה זו באה מצד עצם המציאות של ישראל, שבכללה גם עובר שבמעי אמו; ועוד זאת — כיון שעצם מציאותם הוא בשווה ממש עם גדול שבגדולים, לכן אמירת השירה הי' באופן של השתוות גמורה, \"בלא. . השתנות והפרדה\"<sup data-n=\"577\">*54</sup>.",[["568","47","שלכן המורד במלך יש למלך רשות להרגו (רמב\"ם הל' מלכים שם ה\"ח), כולל גם מאן דמחוי במחוג קמי מלכא (חגיגה ה, ב). — וראה לקו\"ש ח\"ד ע' 1050 ואילך. ח\"ח ע' 25. ועוד."],["569","48","תניא פ\"ב (ו, ריש ע\"ב)."],["570","49","להעיר מהמבואר בכ\"מ שיחידה שבנפש שורה בלב דוקא (ראה המשך תער\"ב ח\"א פל\"ה. וראה תו\"א מג\"א צד, סע\"ד ואילך. שערי אורה ד\"ה וקבל פט\"ז ואילך. ועוד)."],["571","50","ראה לעיל הערה 35."],["572","51","וי\"ל שזהו פירוש ב' הלשונות \"כאיש אחד בלב אחד\" (ראה לעיל הערה 13) — \"כאיש אחד\", שעדיין יש בו התחלקות האברים, ראש ורגל כו'; \"בלב אחד\" — נקודת החיות שלמעלה מהתחלקות."],["572","51","וי\"ל שזהו פירוש ב' הלשונות \"כאיש אחד בלב אחד\" (ראה לעיל הערה 13) — \"כאיש אחד\", שעדיין יש בו התחלקות האברים, ראש ורגל כו'; \"בלב אחד\" — נקודת החיות שלמעלה מהתחלקות."],["574","52","בלשון החסידות — שנשיא הדור הוא ה­\"יחידה\" הכללית של כל הדור, המגלה את ה­\"יחידה\" שבכאו\"א מאנשי הדור."],["575","53","ולהעיר גם מלקו\"ש חלק ל ע' 20­219 — לענין האחדות הנעשית ע\"י מלך."],["576","54","ויש לומר, שג' האופנים (דיעות) באופן אמירת שירה הם ע\"ד ג' האופנים שישנם בגילוי נקודת היהדות (כמשנ\"ת במ\"א); א) גילוי נקודת היהדות בפ\"ע (שלמעלה מהשכל). ב) הגילוי הוא באופן שפועל על השכל, שה\"הנחות\" שבשכלו הם בהתאם לנקודת היהדות, אבל נרגש שמקורן (אינו בשכל מצ\"ע, אלא) בנקודת היהדות. ג) נקודת היהדות חודרת בכל מהותו ומציאותו, שאז השכל מצ\"ע מבין כפי המחוייב מצד נקודת היהדות (ראה לקו\"ש ח\"ח ע' 5 ואילך. ועוד)."],["577","*54","ראה גם מאמרי אדמו\"ר האמצעי ויקרא ע' של."]]],[1301470144,"ויש לומר, שהחידוש בשירת הים הי' שאחדות זו (שמצד עצם מציאותם של ישראל) היתה באופן גלוי ממש. ולכן התבטאה האחדות בענין השירה, המורה על שמחה — כי \"שמחה פורצת גדר\"<sup data-n=\"578\">55</sup>, וכן בעניננו, שהיא פורצת את ההגבלות וההגדרות של האדם ומגיעה לעצמות ומהות נפשו, וכן שמחה מורה על \"בחי' התגלות\"<sup data-n=\"579\">56</sup>, שעל ידי השמחה באמירת שירה נמשכה אחדות זו באופן גלוי (כשם שגילוי השכינה אז הי' באופן שהיו רואים ממש, כאמרם<sup data-n=\"580\">57</sup> \"זה א­לי גו'\", ש\"היו מראין אותו באצבע\").\nוכן תהי' לנו, שנזכה בקרוב ל\"שירה העשירית\"<sup data-n=\"581\">58</sup>, כאשר \"קהל<sup data-n=\"582\">59</sup> גדול ישובו הנה\", בגאולה האמיתית והשלימה על ידי משיח צדקנו, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחת ש\"פ בשלח תשמ\"ח)</span>",[["578","55","ראה בארוכה המשך שמח תשמח (בסה\"מ) תרנ\"ז (ע' רכג ואילך)."],["579","56","תו\"א פרשתנו סב, א. וראה בארוכה המשך הנ\"ל בתחילתו (ע' קעג ואילך)."],["580","57","טו, ב וברש\"י שם."],["581","58","מכילתא פרשתנו כאן. ועוד."],["582","59","ירמי' לא, ז."]]],[1301470145,"<h3>שיחה ב</h3>\nא. עה\"פ<sup data-n=\"583\">1</sup> \"מקדש אדנ\"י כוננו ידיך\" איתא במכילתא (והובא ברש\"י עה\"פ) \"חביב בית המקדש לפני הקב\"ה שכש­ברא הקב\"ה את עולמו לא בראו אלא בידו אחת שנאמר<sup data-n=\"584\">2</sup> אף ידי יסדה ארץ וכשבא לבנות בית המקדש כביכול ב­שתי ידיו שנאמר מקדש ה'<sup data-n=\"585\">3</sup> כוננו ידיך אימתי תבנהו בשתי ידיך<sup data-n=\"586\">4</sup>. . ה' ימלוך לעולם ועד\" (לעתיד לבא שכל המלוכה שלו. רש\"י<sup data-n=\"587\">5</sup>). והיינו שפירוש \"כוננו ידיך\" הוא כפשוטו, שהמקדש הוא מעשה ידי הקב\"ה.\nאבל בגמ'<sup data-n=\"588\">6</sup> איתא \"גדולים מעשה צדיקים יותר ממעשה שמים וארץ דאילו במעשה שמים וארץ כתיב אף ידי יסדה ארץ (חדא יד. רש\"י) וימיני טפחה שמים ואילו במעשה ידיהם של צדיקים כתיב מכון לשבתך פעלת ה' מקדש אדנ\"י כוננו ידיך\"<sup data-n=\"589\">7</sup>, ופרש\"י \"מקדש מעשה ידי צדיקים הוא\" [ואף שבכתוב נאמר \"מקדש אדנ\"י כוננו ידיך\" — הרי מעשה ידי צדיקים \"קרוין. . מעשה ידיו של הקב\"ה\"<sup data-n=\"590\">8</sup>].\nולכאורה יש מקום לומר, שפלוגתת הגמ' והמכילתא (אי \"מקדש אדנ\"י כוננו ידיך\" הוא מעשה ידי הקב\"ה (ממש) או מעשה ידי צדיקים) תלוי' בפלוגתא ה­ידועה אי בית המקדש השלישי יבנה על ידי בני אדם<sup data-n=\"591\">9</sup> או שיבנה על ידי הקב\"ה עצמו<sup data-n=\"592\">10</sup> (ולכו\"ע מדובר בפסוק ע\"ד בית הג').\nועפ\"ז י\"ל דזה שרש\"י עה\"פ הביא את דרשת המכילתא הוא משום דאזיל לשי­טתו בכ\"מ בש\"ס<sup data-n=\"593\">11</sup> ש\"מקדש העתיד שאנו מצפין בנוי ומשוכלל הוא יגלה ויבא משמים שנאמר מקדש ה' כוננו ידיך\"<sup data-n=\"594\">12</sup>.",[["583","1","פרשתנו טו, יז."],["584","2","ישעי' מח, יג."],["585","3","כן הוא במכילתא, זח\"ג שבהערה 10 ובכו\"כ מקומות. ובכתוב (וכן הועתק בגמ' דלהלן) \"אדנ\"י\". ולהעיר ממדרש לקח טוב עה\"פ."],["586","4","במכילתא הובא כאן משל ללסטים כו' (כ­דלקמן סוף ס\"ב), ומסיים \"ואח\"כ נתודעה מלכותו לעולם לכך נאמר מקדש ה' כוננו ידיך ה' ימלוך לעולם ועד\" (ולכמה גי' \"ה' ימלוך לעולם ועד\" היא התחלת המאמר שלאח\"ז). ולכאורה במקום תוכן זה מסיים רש\"י \"ואימתי יבנה בשתי ידים בזמן שה' ימלוך לעולם ועד לעתיד לבא שכל המלוכה שלו\", כבפנים. אבל ראה לקמן בפנים סעיף ג."],["587","5","כ\"ה בדפוסי רש\"י שלפנינו. ובא' מכת\"י רש\"י (שתח\"י).\nבדפוס ראשון ושני וכת\"י רש\"י (שתח\"י) סיום פרש\"י הוא \"בזמן שה' ימלוך לעולם ועד\", ואח\"כ מפרש רש\"י תיבת \"ועד\" — \"לשון עולמית כו'\". ובדפוס ראשון איתא בסוף ד\"ה זה (ועד) \"(קמוצה היא) הוא לעתיד לבא שהמלוכה שלו היא לעולם\". ולכאורה ט\"ס שם."],["588","6","כתובות ה, א."],["589","7","ראה בארוכה לקו\"ת נשא כא, סע\"ב ואילך."],["590","8","רש\"י כתובות שם ד\"ה הכי קאמר. שטמ\"ק לכתובות שם בפירוש השני."],["591","9","רמב\"ם הל' מלכים רפי\"א ובסופו. והוא ע\"פ ירושלמי מגילה פ\"א הי\"א. ויק\"ר פ\"ט, ו. וראה גם ירושלמי פסחים פ\"ט ה\"א (תוספתא פסחים פ\"ח, ב)."],["592","10","ראה זח\"א כח, א. ח\"ב נט, סע\"א. קח, סע\"א. ח\"ג רכא, א. יל\"ש תהלים רמז תתמח בסופו. וראה תנחומא (באבער) בראשית יז (בסופו)."],["593","11","סוכה מא, סע\"א (הובא בתוס' שם). ר\"ה ל, סע\"א."],["594","12","ל' רש\"י סוכה שם."]]],[1301470146,"אמנם לפי זה יש לתמוה לאידך גיסא — מדוע כתב רש\"י (בפירושו לש\"ס) ב­נוגע למקדש הג', ד\"מקדש מעשה ידי צדיקים הוא\" — היפך שיטתו (הנ\"ל) ב­כ\"מ שמקדש דלעתיד \"יגלה ויבא מ­שמים\".\nולכן נראה יותר לפרש, שהפלוגתא היא — באיזה מקדש מדובר בפסוק \"מקדש אדנ\"י כוננו ידיך\"<sup data-n=\"595\">13</sup>: להמכילתא (ורש\"י עה\"ת) קאי על מקדש השלישי, ולכן פי' \"כוננו ידיך\" שהמקדש הוא מעשה ידיו של הקב\"ה; משא\"כ להגמ' קאי במקדש הא' (והב') שלכו\"ע הם מעשה ידי אדם<sup data-n=\"596\">14</sup>.\nוצריך להבין מהו יסוד וטעם פלוגת­תם, אם בשירת הים מדובר ע\"ד מקדש הא' (והב') או במקדש השלישי דלעתיד?\nב. והנה גם במפרשי התורה על אתר מצינו שתי שיטות בפירוש מקראות אלה, דלכמה מפרשים<sup data-n=\"597\">15</sup> קאי על המשכן וה­מקדש הא' שנבנה על ידי דוד (ושלמה), ומש\"נ ע\"ז \"מקדש אדנ\"י כוננו ידיך\" הוא כאמרו \"ככל אשר אני מראה אותך\"<sup data-n=\"598\">16</sup>; \"והקמות את המשכן כמשפטו אשר הראת בהר\"<sup data-n=\"599\">17</sup>, ש\"הקב\"ה הראה<sup data-n=\"600\">18</sup> למשה תבנית כל המשכן בנוי\"<sup data-n=\"601\">19</sup>, ו\"כן דוד אמר הכל בכתב מיד ה' עלי השכיל\"<sup data-n=\"602\">20</sup>, ולפי­כך נקרא ע\"ש הקב\"ה; אמנם לפרש\"י (ועוד) קאי על המקדש שיבנה לעת\"ל, כנ\"ל.\nולכאורה יש לדייק בזה: שיטתו ו­ענינו של פרש\"י עה\"ת הוא לפרש פשוטו של מקרא, ובפשטות הרי כתוב זה בא בהמשך להתחלתו \"תביאמו ותטעמו בהר נחלתך מכון לשבתך פעלת ה'\", דהיינו הכניסה לארץ ובנין המקדש הא' — ו­מדוע מחלק רש\"י את הכתוב לשנים, וזמן כל הגליות מפריד ביניהם, ואח\"כ בא סוף הכתוב ע\"ד המקדש דלעתיד [ובלאה\"כ לכאורה פירוש זה הוא רחוק יותר מפשש\"מ, מהפירוש דמ\"ש \"כוננו ידיך\" קאי על המקדש סתם (הראשון) (שנבנה על ידי בנ\"א ונק' \"כוננו ידיך\" מ­פני ש\"הכל בכתב מיד ה' עלי השכיל\")].\nוגם מצד הסברא אינו מובן — איך מתאים שב(אמצע) שירה והודי' על ה­נסים דקי\"ס, יזכירו בנ\"י ע\"ד ביהמ\"ק דלעתיד, שזה מדגיש שהמקדש שיבנה כשיכנסו לארץ אז עתיד ליחרב<sup data-n=\"603\">21</sup> [וכ­מודגש בלשון המכילתא כאן \"אימתי תבנהו בשתי ידיך, משל ללסטים שנכנסו לפלטרין של מלך בזזו נכסיו והרגו כו' והחריבו כו' לאחר זמן ישב המלך עמהם לדין תפס מהם הרג כו' וישב בפלטרין שלו ואח\"כ נתודעה מלכותו לעולם\"] — שע\"י הוספה זו עירבו עניני פורענות ל(תוך) השירה<sup data-n=\"604\">22</sup>!",[["595","13","ראה מרכבת המשנה למכילתא. ועוד."],["596","14","וראה גו\"א לפרש\"י שם בסופו. וראה בכל הנ\"ל בביאור הרי\"פ פערלא לסהמ\"צ לרס\"ג עשין יג (קיג, א ואילך)."],["597","15","ראה ראב\"ע כאן עה\"פ ובפסוק יח. כלי יקר וספורנו כאן. וכ\"ה במדרש לקח טוב כאן."],["598","16","תרומה כה, ט — הובא בספורנו כאן."],["599","17","שם כו, ל — הובא בכלי יקר כאן."],["600","18","ועפ\"ז יובן דיוק הכתוב \"כוננו\" ולא \"בנאו\" וכיו\"ב. ובפרט שרש\"י עצמו כאן ממשיך \"ואימתי יבנה\" (ועד\"ז במכילתא)."],["601","19","כלי יקר כאן."],["602","20","דה\"א כח, יט. ספורנו כאן."],["603","21","להעיר מפרש\"י שמות ג, יד."],["604","22","אף שעל תחלת הכתוב \"תביאמו ותטעמו\" מפורש במכילתא \"נתנבאו אבות ולא ידעו מה נתנבאו תביאנו ותטענו אין כתיב כאן אלא תביאמו ותטעמו אמרו הבנים נכנסין ולא האבות\" — הרי זהו רמז ודיוק בתיבות שאמרו בלאה\"כ, אבל בנדו\"ד נמצא שאמרו \"מקדש אדנ\"י כוננו ידיך\" בנוגע ל­מקדש דלעתיד."]]],[1301470147,"ג. ויש לומר הביאור בזה:\nמה שפרש\"י \"ואימתי יבנה בשתי ידים בזמן שה' ימלוך לעולם ועד לעתיד לבא שכל המלוכה שלו\", אין הפירוש בזה שזו היתה כוונת משה ובני ישראל ב­אמרם שירה זו, להזכיר ע\"ד בנין ה­מקדש לעתיד לבא (לאחרי זמנו דרש\"י) — אלא זוהי הסברתו של רש\"י, שבפועל יהי' זה לעת\"ל, אבל באמרם השירה התכוונו ישראל שזה יהי' במקדש סתם (הראשון), שהקב\"ה יבנה את המקדש הזה בשתי ידיו ויקויים אז \"ה' ימלוך לעולם ועד\". כמבואר בכ\"מ<sup data-n=\"605\">23</sup>, שאלמלא חטאו היו ישראל נכנסים לא\"י באופן של גאולה שלימה ונצחית שאין אחרי' גלות<sup data-n=\"606\">24</sup>.\nובזה מובן בפשטות טעם השינוי בין רש\"י והמכילתא: במכילתא מאריך ב­משל (כנ\"ל) \"אימתי תבנהו בשתי ידיך, משל ללסטים שנכנסו לפלטרין של מלך בזזו נכסיו והרגו כו' והחריבו כו' (שכ\"ז הי' במשך זמן רב ו)לאחר זמן ישב המלך עמהם לדין תפס מהם הרג כו' וישב בפלטרין שלו ואח\"כ נתודעה מלכותו לעולם\" — דהיינו שהמדובר הוא במקדש שיבנה לעתיד, זמן רב לאחרי שיחרב המקדש (הא' והב'); משא\"כ רש\"י לא הביא אריכות זו, כי לפרש\"י כוונת ישר­אל<sup data-n=\"607\">25</sup> היתה שהמקדש שיבנה תיכף ב­כניסתם לארץ יהי' נבנה ב\"שתי ידיו\" של הקב\"ה.\nכלומר: לפי המכילתא סיום הכתוב \"מקדש אדנ\"י כוננו ידיך\" לא קאי על המקדש שמדובר אודותו בחלק הראשון של הכתוב \"מכון לשבתך פעלת ה'\" [ש­בפשטות אמרוהו בנ\"י בשייכות למקדש הא' שנבנה כאשר \"תביאמו ותטעמו בהר נחלתך\"; ולהעיר שזה ש\"כסא של מטה הוא מכוון כנגד כסא של מעלה\" — שזהו הפירוש ב\"מכון לשבתך פעלת ה'\" (כ­מ\"ש במכילתא<sup data-n=\"608\">26</sup>) — הוא בכל המקדשות, גם במקדש הא' והב']; משא\"כ לפרש\"י, לא התכוונו ישראל למקדש אחר, אלא לאותו המקדש שבתחילת הכתוב [אלא שבפועל גרם החטא ולא נתקיים זה, ולא יהי' עד לעתיד לבא, כפרש\"י].\nנמצינו למדים, ששלש שיטות יש בפירוש \"מקדש אדנ\"י כוננו ידיך\": לה­מכילתא קאי על המקדש דלעתיד, ש­יבנה (זמן רב) לאחרי שיחרבו המקדשות הראשונים; להגמ' קאי על מקדש ראשון (ושני<sup data-n=\"609\">27</sup>), שהם מעשה ידיהם של צדיקים; ואילו לפרש\"י<sup data-n=\"610\">28</sup>, אף שקאי על המקדש שנבנה אז בכניסתם לארץ, מ\"מ הכוונה שהקב\"ה יבנהו בשתי ידיו \"ואימתי (בא בפועל) כו'\".\nד. ויש לומר, שג' שיטות אלו תלויות בשלשת האופנים בלימוד ודרשת לשונה של שירה:\nלפי כמה פשטנים<sup data-n=\"611\">29</sup>, דרך הכתובים במשל ושיר וכיו\"ב לכפול הענין במלות שונות, ליופי המליצה בלבד; לאידך, ב­לימוד ע\"ד הדרש — דורשים כל ענין שבשירה לענין בפ\"ע.",[["605","23","זח\"ג שבהערה 10. וראה גם עירובין נד, א. שמו\"ר רפל\"ב."],["606","24","וראה אלשיך כאן."],["607","25","שהיא דוקא פשוטו של מקרא."],["608","26","הובא גם בפרש\"י עה\"פ."],["609","27","כ\"ה בגו\"א לפרש\"י כאן, שלהגמ' קאי גם על מקדש הב'."],["610","28","וראה גם זח\"ג שם."],["611","29","ראה ראב\"ע עה\"פ. אברבנאל כאן טו, ב (ועוד שם). ועוד."]]],[1301470148,"ויש לומר, ששיטת רש\"י בפירושו על התורה היא שיטה ג', ממוצעת ביניהם: גם בשירה ס\"ל לרש\"י שלא קיימת הכפלה סתם, כי אם כאשר נוסף פרט וענין חדש [וכמ\"ש רש\"י (ישן)<sup data-n=\"612\">30</sup> בנוגע לשירת הים \"כי גאה גאה. . בא הכפל לומר. . וכן כל השירה תמצא כפולה\", ורש\"י מפרש בהכתובים טעם לכפל ה­ענין<sup data-n=\"613\">31</sup>]; אבל לאידך, ההוספה אינה ב­ענין חדש (לגמרי), אלא פרט נוסף באותו ענין [ע\"ד \"ועל<sup data-n=\"614\">32</sup> השנות החלום אל פרעה פעמים כי נכון הדבר מעם האלקים וממהר האלקים לעשותו\" — שהכפל מוסיף תוקף וזריזות בענין זה עצמו].\nוכן הוא בכתוב דידן — שיש בו כפל לשון, \"מכון לשבתך פעלת ה', מקדש אדנ\"י כוננו ידיך\"; וכוונת הכפל יש לפרש בג' אופנים: (א) שזהו כפל גמור, רק ליופי המליצה, (ב) שזה מוסיף ענין חדש לגמרי, (ג) זהו פרט נוסף באותו ענין.\nוזהו ההבדל בין ג' שיטות הנ\"ל:\nבמכילתא — בו דרשו רבותינו — דריש את הכפל \"מקדש אדנ\"י כוננו ידיך\" בענין חדש (שלא דובר אודותו לפנ\"ז) — המקדש דלעתיד שיבנה לאחרי שיחרב הראשון והשני;\nפירוש הגמ' דקאי על בנין המקדש הראשון (והשני) על ידי צדיקים — מתאים להשיטות שהכפל בכתוב הוא ליופי המליצה, ועפ\"ז כוונת הכתוב ב­\"מקדש אדנ\"י כוננו ידיך\" היא כמו בהת­חלת הכתוב \"מכון לשבתך פעלת ה'\"<sup data-n=\"615\">33</sup>;\nולפרש\"י, כפל זה בא להוסיף פרט נוסף במקדש זה שיבנה בכניסתם לארץ, דנוסף על כך שהקב\"ה פעל \"מכון לשב­תו\" למעלה, הנה עוד זאת שיבנה את המקדש דלמטה בשתי ידיו [אלא שב­פועל לא נתקיים זה בכניסתם לארץ בפעם הא', ואימתי יקויים — \"לעתיד לבא\"].\nה. ויש לבאר בעומק יותר תוכן החי­לוק בין ג' הפירושים, ובהקדם ביאור הטעם שבשירת הים (שתוכנה ההודאה על נס דקריעת ים סוף והריגת המצרים) נזכר בכלל \"בית המקדש\" ומעלתו (\"מ­כון גו' מקדש גו'\") — דלכאורה מאי בעי הכא?\nזה שנזכר בשירה ע\"ד הכניסה לארץ — \"תביאמו ותטעמו בהר נחלתך\"<sup data-n=\"583\">1</sup> — מובן, כי זהו ההמשך והשלימות דגאולת מצרים, כמ\"ש<sup data-n=\"617\">34</sup> \"אעלה אתכם מעני מצרים אל ארץ הכנעני גו'\"<sup data-n=\"618\">35</sup> (וכאמרם לפני זה בהשירה עצמה<sup data-n=\"619\">36</sup> — \"נחית ב­חסדך עם זו גאלת נהלת בעזך אל נוה קדשך\"<sup data-n=\"620\">37</sup>); וכיון שקי\"ס הוא הגמר וה­סיום דיציאת מצרים (שהרי רק אז בטל כל הפחד מהמצריים), לכן כללו בשירת הים, שמעתה שנגמרה יציאת מצרים הרי",[["612","30","טו, א."],["613","31","ראה לדוגמא גם רש\"י שם, ג ד\"ה ה' שמו. שם, ו ד\"ה ימינך ה'. ועוד."],["614","32","מקץ מא, לב."],["615","33","להעיר שבכתובות שם הובאו ב' הפרטים — \"מכון לשבתך פעלת ה' מקדש אדנ\"י כוננו ידיך\"."],["583","1","פרשתנו טו, יז."],["617","34","שמות ג, יז."],["618","35","וראה גם שם, ח. וארא ו, ו­ח. ועוד."],["619","36","טו, יג."],["620","37","ראה רשב\"ם שם. אבל בראב\"ע שם: הוא הר סיני. ובתיב\"ע: טור בית מקדשך. ועד\"ז ברמב\"ן \"ונוה קדשך הוא בית המקדש\". וכ\"ה במכילתא עה\"פ."]]]]});
